import { describe, expect, it, vi } from "vitest";
import { isVpsOwnedPlatformCollect } from "@changmen/venue-adapter/registry";
import { saveBetSource, saveLiveTimer, saveMatchSource } from "./match";
import { postForm } from "@/api/client";

vi.mock("@/api/client", () => ({
  post: vi.fn(),
  postForm: vi.fn(async () => ({ success: 1 })),
  unwrap: vi.fn(),
}));

describe("api/match VPS Save* gate", () => {
  it("adds raw result facts only to the existing RAY SaveBet request", async () => {
    const matchResult = { id: "1", status: 1, odds: [{ win: 1 }] };
    await saveBetSource("RAY", "1", [], matchResult);
    expect(postForm).toHaveBeenLastCalledWith("API_SaveBet?RAY", {
      provider: "RAY", matchId: "1", bets: "[]", matchResult: JSON.stringify(matchResult),
    });
    await saveBetSource("OB", "1", [], matchResult);
    expect(postForm).toHaveBeenLastCalledWith("API_SaveBet?OB", { provider: "OB", matchId: "1", bets: "[]" });
    await saveBetSource("RAY", "1", []);
    expect(postForm).toHaveBeenLastCalledWith("API_SaveBet?RAY", { provider: "RAY", matchId: "1", bets: "[]" });
  });
  it("blocks Save* for every vps_http_ws platform from manifest", async () => {
    expect(isVpsOwnedPlatformCollect("PredictFun")).toBe(true);
    expect(isVpsOwnedPlatformCollect("Polymarket")).toBe(true);
    expect(isVpsOwnedPlatformCollect("SXBet")).toBe(true);
    expect(await saveMatchSource("PredictFun", [])).toBe(false);
    expect(await saveMatchSource("Polymarket", [])).toBe(false);
    expect(await saveMatchSource("SXBet", [])).toBe(false);
    expect(await saveBetSource("PredictFun", "1", [])).toBe(false);
    expect(await saveBetSource("Polymarket", "1", [])).toBe(false);
    expect(await saveBetSource("SXBet", "1", [])).toBe(false);
    expect(await saveLiveTimer("PredictFun", [])).toBe(false);
    expect(await saveLiveTimer("Polymarket", [])).toBe(false);
    expect(await saveLiveTimer("SXBet", [])).toBe(false);
  });

  it("allows classic browser Save* platforms through the gate", async () => {
    expect(isVpsOwnedPlatformCollect("OB")).toBe(false);
    expect(await saveMatchSource("OB", [])).toBe(true);
    expect(await saveBetSource("OB", "1", [])).toBe(true);
    expect(await saveLiveTimer("OB", [])).toBe(true);
  });
});

import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import type { OrderRow, PageResult } from "@/types/esport";
import { post, unwrap } from "@/api/client";
import type { PmSubmission } from "@changmen/shared/pm_submission";

/** [changmen 扩展] 同步专用投影；未注册或没有匹配原单时沿用原保存数组。 */
let orderSyncProjection: ((account: PlatformAccount, orders: VenueOrder[]) => VenueOrder[] | Promise<VenueOrder[]>) | undefined;
export function registerOrderSyncProjection(project: NonNullable<typeof orderSyncProjection>): () => void {
  orderSyncProjection = project;
  return () => { if (orderSyncProjection === project) orderSyncProjection = undefined; };
}

/** [changmen 扩展] 旧待确认队列按原单恢复申请额，不能从当前赔率推算。 */
export async function getPmSubmission(playerId: number, orderId: string): Promise<PmSubmission | null> {
  const response = await post<PmSubmission>("Pm_GetSubmission", { playerId, orderId }, "", { errorTip: false });
  return response.success === 1 ? response.info ?? null : null;
}

/** [A8 可证实] `Ut.getOrders`：success!==1 时不更新侧栏（返回 null） */
export async function getOrderList(body: Record<string, unknown> = {}) {
  const data = await post<PageResult<OrderRow>>("Client_GetOrderList", body);
  if (data.success !== 1)
    return null;
  return data.info ?? { list: [], total: 0, pageIndex: 1, pageSize: 20 };
}

export async function saveOrder(body: Record<string, unknown>) {
  return unwrap(await post<unknown>("Client_SaveOrder", body));
}

/**
 * 对齐 bundle `Vt.saveOrders`：按 provider 分组调用 `Client_SaveOrder`。
 * [changmen 扩展] PredictFun 禁止客户端回写：订单只经 Pf_* 服务端落库。
 */
export async function saveOrders(account: PlatformAccount, orders: VenueOrder[]): Promise<void> {
  orders = await (orderSyncProjection?.(account, orders) ?? orders);
  if (String(account.provider ?? "").trim() === "PredictFun")
    return;
  const byProvider = new Map<string, VenueOrder[]>();
  for (const order of orders) {
    const provider = String(order.provider ?? "").trim();
    if (provider === "PredictFun")
      continue;
    const list = byProvider.get(provider) ?? [];
    list.push(order);
    byProvider.set(provider, list);
  }
  for (const [type, list] of byProvider) {
    await saveOrder({
      type,
      playerId: account.accountId,
      orders: JSON.stringify(list),
    });
  }
}

/**
 * [A8 可证实] `Vt.saveOrderBind`：空数组不 POST。
 * [changmen 扩展] 返回是否成功（业务失败不抛，供绑单重试/UI 感知）。
 */
export async function saveOrderBind(body: Record<string, unknown>): Promise<boolean> {
  const raw = body.orders;
  if (typeof raw === "string") {
    try {
      const rows = JSON.parse(raw) as unknown[];
      if (!rows?.length)
        return true;
    }
    catch {
      // 非 JSON 时仍交给服务端
    }
  }
  const data = await post<boolean>("Client_SaveOrderBind", body, "", { errorTip: false });
  return data.success === 1;
}

/** [changmen 扩展] 侧栏手动改绑：单笔订单 link 新→老 */
export async function rebindOrderLink(body: {
  orderId: string;
  toLinkId: number;
}): Promise<{ orderId: string; fromLinkId: number; toLinkId: number }> {
  return unwrap(
    await post<{ orderId: string; fromLinkId: number; toLinkId: number }>(
      "Client_RebindOrderLink",
      body,
    ),
  );
}

import type { PlatformId } from "@/types/esport";
import type { PolymarketApiCreds } from "@changmen/venue-adapter/polymarket";

export interface PastedAccountCredential {
  provider?: PlatformId;
  token?: string;
  referer?: string;
  gateway?: string | string[];
}

export function isSportObCollectCredential(parsed: Record<string, unknown> | undefined): boolean {
  if (!parsed)
    return false;
  if (String(parsed.kind || "").toLowerCase() === "sport")
    return true;
  const token = String(parsed.token || "").trim();
  const sessionId = String(parsed.sessionId || "").trim();
  return Boolean(sessionId && token && /^[0-9a-f]{16,}$/i.test(token) && !/^\d+$/.test(token));
}

export function parsePastedObject(raw: string): Record<string, unknown> | undefined {
  return tryParseJson(raw) ?? tryParseJson(decodeBase64Utf8(raw));
}

export function parsePastedAccountCredential(raw: string): PastedAccountCredential | undefined {
  const parsed = parsePastedObject(raw);
  if (!parsed)
    return undefined;
  if (isSportObCollectCredential(parsed))
    return undefined;
  if (parsed.provider) {
    const credential = parsed as PastedAccountCredential;
    if (!credential.token && typeof parsed.accessToken === "string")
      credential.token = String(parsed.accessToken);
    if (
      credential?.provider === "Polymarket"
      && !credential.token
    ) {
      credential.token = JSON.stringify({
        walletAddress: parsed.walletAddress,
        address: parsed.address,
        funder: parsed.funder,
        signatureType: parsed.signatureType,
        privateKey: parsed.privateKey,
        private_key: parsed.private_key,
        apiKey: parsed.apiKey,
        key: parsed.key,
        secret: parsed.secret,
        passphrase: parsed.passphrase,
        apiCreds: parsed.apiCreds,
        polyHeaders: parsed.polyHeaders,
      });
    }
    return credential;
  }
  if (
    parsed.walletAddress
    || parsed.address
    || parsed.apiCreds
    || parsed.apiKey
    || parsed.key
    || parsed.secret
    || parsed.passphrase
    || parsed.privateKey
    || parsed.private_key
  ) {
    return {
      provider: "Polymarket",
      gateway: "https://clob.polymarket.com",
      token: JSON.stringify(parsed),
      referer: "",
    };
  }
  return undefined;
}

export function parsePolymarketTokenObject(raw: string | undefined): Record<string, unknown> | undefined {
  const text = raw?.trim();
  if (!text)
    return {};
  const parsed = tryParseJson(text) ?? tryParseJson(decodeBase64Utf8(text));
  if (!parsed)
    return undefined;

  const nestedToken = typeof parsed.token === "string" ? parsed.token.trim() : "";
  if (nestedToken) {
    const nested = tryParseJson(nestedToken) ?? tryParseJson(decodeBase64Utf8(nestedToken));
    if (nested)
      return nested;
  }

  return parsed;
}

export function normalizePolymarketTokenObject(token: Record<string, unknown>): Record<string, unknown> {
  const walletAddress = String(token.walletAddress ?? token.address ?? "");
  const funder = String(token.funder ?? token.funderAddress ?? "");
  if (walletAddress && funder && walletAddress.toLowerCase() !== funder.toLowerCase())
    token.signatureType = "3";
  else if (token.signatureType === undefined || token.signatureType === "")
    token.signatureType = "3";
  return token;
}

export function normalizePolymarketApiCreds(token: Record<string, unknown>): PolymarketApiCreds | undefined {
  const rawApi = token.apiCreds;
  const api = rawApi && typeof rawApi === "object"
    ? rawApi as Record<string, unknown>
    : token;
  const apiKey = String(api.apiKey ?? api.key ?? api.api_key ?? "");
  const secret = String(api.secret ?? api.apiSecret ?? api.api_secret ?? "");
  const passphrase = String(api.passphrase ?? "");
  if (!apiKey || !secret || !passphrase)
    return undefined;
  return { apiKey, secret, passphrase };
}

export function tokenFromPolymarketForm(
  values: {
    walletAddress: string;
    funder: string;
    privateKey: string;
    apiCreds?: PolymarketApiCreds;
  },
): string {
  const token: Record<string, unknown> = {
    walletAddress: values.walletAddress.trim(),
    funder: values.funder.trim(),
    signatureType: "3",
    privateKey: values.privateKey.trim(),
  };
  if (values.apiCreds) {
    token.apiCreds = {
      apiKey: values.apiCreds.apiKey,
      secret: values.apiCreds.secret,
      passphrase: values.apiCreds.passphrase,
    };
  }
  return JSON.stringify(normalizePolymarketTokenObject(token));
}

export function tryParseJson(raw: string | undefined): Record<string, unknown> | undefined {
  if (!raw)
    return undefined;
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed as Record<string, unknown> : undefined;
  }
  catch {
    return undefined;
  }
}

export function decodeBase64Utf8(raw: string): string | undefined {
  try {
    const atobFn = typeof globalThis.atob === "function" ? globalThis.atob.bind(globalThis) : undefined;
    if (!atobFn)
      return undefined;
    const binary = atobFn(raw);
    const bytes = Uint8Array.from(binary, ch => ch.charCodeAt(0));
    return new TextDecoder().decode(bytes);
  }
  catch {
    return undefined;
  }
}

