import type { GtcExecution, GtcFinancialOrder } from "@changmen/shared/pm_gtc";
import { buildPolymarketMatchedBuyVenueOrderUsdc } from "@changmen/venue-adapter/polymarket";
import { scalePolymarketVenueOrdersForDisplay } from "@changmen/venue-adapter/polymarket/orders";

/** [changmen 扩展] 原单事实适配；金额、费用舍入、赔率和汇率均由普通 PM 助手处理。 */
export function gtcMatchedOrder(row: GtcExecution, fee: number) {
  const usdc = buildPolymarketMatchedBuyVenueOrderUsdc(row.orderId ?? `gtc-pending:${row.id}`, {
    status: "matched",
    takingAmount: row.matched,
  }, { fallbackStakeUsdc: Number(row.principal), feeUsdc: fee });
  if (!usdc)
    return null;
  // [changmen 扩展] 普通 PM 助手的成交份数会舍入到四位；GTC 事实及持久化须保留官方六位数量。
  // 金额、费用和赔率仍使用普通助手的结果。
  usdc.pmShares = Number(row.matched);
  return scalePolymarketVenueOrdersForDisplay([usdc])[0]!;
}

export function gtcFinancialOrder(row: GtcExecution): GtcFinancialOrder | undefined {
  if (!row.orderId || row.fee == null || (!row.complete && !Object.values(row.fills).some(fill => fill.status === "FAILED")))
    return;
  if (Number(row.matched) === 0 && Object.values(row.fills).some(fill => fill.status === "FAILED"))
    return { pmShares: 0, pmFillPrice: 0, pmStakeUsdc: 0, pmFeeUsdc: 0, odds: 0, betMoney: 0 };
  const order = gtcMatchedOrder(row, Number(row.fee));
  if (!order)
    return;
  return { pmShares: order.pmShares!, pmFillPrice: order.pmFillPrice!, pmStakeUsdc: order.pmStakeUsdc!, pmFeeUsdc: order.pmFeeUsdc ?? 0, odds: order.odds, betMoney: order.betMoney };
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { GtcPlan } from "@changmen/shared/pm_gtc";
import type { ViewBet, ViewMatch } from "@/models/match";
import type { PlatformAccount } from "@/models/platformAccount";
import type { GtcExecutionResult } from "@/orderModes/gtc/executionResult";
import { BetResult } from "@changmen/client-core/models/betResult";
import { getExchange, resolveAccountCurrency } from "@changmen/shared/currency";
import { getAuthSessionVersion, isAuthSessionCurrent } from "@/api/client";
import { useUserStore } from "@/stores/userStore";
import { createGtc } from "./api";
import { checkBetting } from "./gateway";
import { gtcExecutionResult } from "./result";
import { acceptGtc, currentGtc, mutateGtc, pollGtc, startGtcRuntime } from "./runtime";
import { notifyBet } from "@/shared/betNotification";
import { gtcPmNotice } from "./notifications";
import { lookupPolymarketOrderBetLabel } from "@changmen/venue-adapter/polymarket/orders";

/** [changmen 扩展] 单次手动 GTC，不依赖自动下注开关、不触发另一腿或旧 FOK 编排。 */
export async function executeManualGtc(account: PlatformAccount, input: BetOption, context: {
  match: ViewMatch;
  bet: ViewBet;
}): Promise<GtcExecutionResult> {
  const user = useUserStore(); const owner = String(user.userId);
  const session = getAuthSessionVersion();
  if (!user.isLoggedIn || !user.userId || account.provider !== "Polymarket" || input.type !== "Polymarket")
    throw new Error("请登录后使用 PM 手动 GTC");
  const checkSession = () => {
    if (!isAuthSessionCurrent(session) || String(user.userId) !== owner)
      throw new Error("用户会话已变更，禁止继续发送手动 GTC");
  };
  // 仅保存持续恢复标记；不设置自动套利的 GTC 选择或激活凭据。
  if (!user.extensionPrefs.pmGtcV1Participant) {
    user.extensionPrefs.pmGtcV1Participant = true;
    await user.saveExtensionPrefs();
  }
  checkSession(); startGtcRuntime(owner); checkSession();
  const { pmSubmitMaker, prepareManualGtcBuy } = await import("@changmen/venue-adapter/polymarket/gtc");
  const maker = pmSubmitMaker(account);
  // [changmen 扩展] 每次人工下单是独立订单；历史执行或现有挂单不限制新手动单。
  const option = await checkBetting(account, input, { skipAccountRate: true, manual: true });
  checkSession();
  if (!option.data || option.checkError)
    throw new Error(option.checkError || "PM 手动 GTC 预检未通过，未发送订单");
  return notifyBet(account, option, async () => {
    const prepared = await prepareManualGtcBuy(account, option);
    checkSession();
    const fx = getExchange(resolveAccountCurrency(account.provider, account.currency));
    if (option.stakeExchange != null && option.stakeExchange !== fx)
      throw new Error("PM 手动 GTC 金额币种不一致，未发送订单");
    const { submit, validate, prepareSubmit, ...frozen } = prepared;
    const plan: GtcPlan = { ...frozen, source: "manual", playerId: Number(account.accountId), otherPlayerId: 0, originalPmLeg: "A", otherProvider: "", otherTarget: option.target === "Home" ? "Away" : "Home", otherOdds: 0, otherStake: 0, otherVenueMatchId: "", otherVenueItemId: "", parallel: false, matchId: context.match.id, betRowId: context.bet.id, linkId: -Date.now(), tokenId: option.itemId, conditionId: option.betId, target: option.target, match: context.match.title, bet: lookupPolymarketOrderBetLabel(option.betId, option.itemId) || "盘口待核实", item: option.target === "Home" ? context.bet.homeName : context.bet.awayName, fx };
    const id = crypto.randomUUID();
    validate(); checkSession();
    acceptGtc(await createGtc(id, maker, plan));
    try {
      await prepareSubmit(); checkSession();
      await mutateGtc(id, { kind: "authorize_pm" });
      checkSession();
      const submittedAt = Date.now();
      try {
        const ack = await submit();
        const accepted = ack.success === true && Boolean(ack.orderID);
        await mutateGtc(id, ack.pmSubmitNotSent && ack.success === false && !ack.orderID
          ? { kind: "not_sent", leg: "PM", message: ack.errorMsg || "发送前检查失败，未提交" }
          : { kind: "ack", state: accepted ? "accepted" : ack.success === false ? "rejected" : "unknown", orderId: ack.orderID, message: accepted ? "" : ack.errorMsg || "官方受理结果待核实，请勿重复下单" });
        const result = new BetResult("Polymarket", accepted, accepted ? "手动 GTC 已受理，成交继续核对" : "手动 GTC 未确认受理", { orderType: "GTC", source: "manual" }, ack);
        result.orderId = ack.orderID ?? null; result.link = plan.linkId; result.pending = accepted;
        result.saveLog(account, submittedAt);
      }
      catch (error) {
        await mutateGtc(id, { kind: "ack", state: "unknown", message: error instanceof Error ? error.message : "提交结果待核实，请勿重复下单" });
      }
    }
    finally {
      // 关闭的只是本次发送窗口，绝不取消 PM 剩余挂单；恢复时只查同一个订单。
      await mutateGtc(id, { kind: "close" });
    }
    await pollGtc(id).catch(() => {});
    return gtcExecutionResult(currentGtc(id));
  }, gtcPmNotice, 10, { matchTitle: context.match.title, betName: context.bet.getBetName() });
}

import type { GtcExecution } from "@changmen/shared/pm_gtc";
import { gtcDecimal, gtcPmNeverSubmitted, gtcUnits } from "@changmen/shared/pm_gtc";
import { resolveGtcFillFee } from "@changmen/venue-adapter/polymarket/gtc";
import { gtcOriginalOrderActions } from "@/orderModes/gtc/executionIdentity";
import { legacyGtcQueryIssue } from "./syncStatus";

/** [changmen 扩展] 只整理 GTC 附加信息，普通订单字段由 OrderList 显示。 */
export function gtcOrderCardView(row: GtcExecution) {
  const unsubmitted = gtcPmNeverSubmitted(row);
  const matched = gtcUnits(row.matched);
  const total = gtcUnits(row.plan.shares);
  const fills = Object.values(row.fills).filter(fill => fill.status !== "FAILED");
  const detailMatched = fills.reduce((quantity, fill) => quantity + gtcUnits(fill.shares), 0n);
  const quantitiesAgree = Boolean(row.order) && gtcUnits(row.order!.matched) === matched && detailMatched === matched;
  const takerShares = fills.filter(fill => fill.role === "TAKER").reduce((quantity, fill) => quantity + gtcUnits(fill.shares), 0n);
  const makerShares = fills.filter(fill => fill.role === "MAKER").reduce((quantity, fill) => quantity + gtcUnits(fill.shares), 0n);
  const fees = fills.map(fill => fill.fee == null ? resolveGtcFillFee(row.plan.feeProof, fill.role, Number(fill.shares), Number(fill.price)) : Number(fill.fee));
  const fee = quantitiesAgree && fees.every(value => value != null)
    ? gtcDecimal(fees.reduce<bigint>((sum, value) => sum + gtcUnits(value!.toFixed(6)), 0n))
    : null;
  const confirmedFull = matched === total && matched > 0n && quantitiesAgree && fills.every(fill => fill.status === "CONFIRMED");
  const queryErrorKind = legacyGtcQueryIssue(row.error);
  let state = "提交待核实";
  let tone = "default";
  if (unsubmitted) {
    state = "未提交";
  }
  else if (row.submit === "rejected") {
    state = "明确拒单"; tone = "fail";
  }
  else if (matched > 0n && quantitiesAgree) {
    state = matched === total ? "全部成交" : row.terminal ? "部分成交 · 余量已终止" : "部分成交";
    tone = "success";
  }
  else if (matched > 0n) {
    state = "成交待核实";
  }
  else if (row.submit === "accepted") {
    state = row.terminal ? "余量已终止" : row.order?.status === "DELAYED" ? "待撮合" : row.open != null ? "挂单中" : "已受理";
  }
  else if (row.submit === "prepared") {
    state = "准备中";
  }
  const verification: string[] = [];
  if (!unsubmitted && row.submit !== "rejected") {
    if (fee == null)
      verification.push("费用待核实");
    if (matched > 0n && fills.some(fill => fill.status !== "CONFIRMED"))
      verification.push("成交待确认");
    if (!quantitiesAgree || (!row.complete && !row.error))
      verification.push("成交明细待核实");
  }
  const actions = gtcOriginalOrderActions(row);
  return {
    state,
    tone,
    unsubmitted,
    verification,
    quantitiesAgree,
    takerShares: quantitiesAgree ? gtcDecimal(takerShares) : null,
    makerShares: quantitiesAgree ? gtcDecimal(makerShares) : null,
    principal: quantitiesAgree ? row.principal : null,
    fee,
    detailError: row.error === "成交费用待核实" || queryErrorKind ? "" : row.error,
    queryErrorKind,
    queryDiagnostic: confirmedFull && /GTC (?:原单尚未查到|本次原单查询未返回记录)/.test(row.error) ? row.error : "",
    showCancel: actions.showCancel && !row.terminal && (row.open == null || gtcUnits(row.open) > 0n),
    canCancel: actions.canCancel,
  };
}

import type { GtcExecution } from "@changmen/shared/pm_gtc";
import type { OrderRow } from "@/types/order";
import { gtcPmNeverSubmitted } from "@changmen/shared/pm_gtc";
import { orderExecutionIdentity } from "@/orderModes/gtc/executionIdentity";
import { isFootballOrderRow } from "@/shared/orderDomain";
import { resolveOrderItemLabel } from "@/shared/orderItemDisplay";
import { compareOrderLinkDesc, dropOrphanPolymarketSellGroups, filterOrdersBelongingToDate, groupOrdersByEffectiveLink, orderLinkMapEntries } from "@/shared/orderLink";
import { gtcMatchedOrder } from "./financialOrder";
import { gtcOrderCardView } from "./orderCardView";
import { lookupPolymarketOrderBetLabel } from "@changmen/venue-adapter/polymarket/orders";

function originalItemText(execution: GtcExecution): string {
  const entities: Record<string, string> = { apos: "'", quot: "\"", amp: "&", lt: "<", gt: ">", nbsp: " " };
  // Match 在普通列表中按 HTML 展示，Item 是纯文本，先解码以避免实体字面量泄漏。
  return resolveOrderItemLabel(execution.plan.item, execution.plan.match)
    .replace(/&(?:#(\d+)|#x([\da-f]+)|(apos|quot|amp|lt|gt|nbsp));/gi, (entity, decimal: string | undefined, hex: string | undefined, named: string | undefined) => {
      if (named)
        return entities[named.toLowerCase()]!;
      const point = decimal ? Number(decimal) : Number.parseInt(hex!, 16);
      return point > 0 && point <= 0x10FFFF && !(point >= 0xD800 && point <= 0xDFFF) ? String.fromCodePoint(point) : entity;
    });
}

/** [changmen 扩展] 未落财务库的原单仅适配为展示行，不写 OrderStore/统计/数据库。 */
function pendingOrderRow(execution: GtcExecution): OrderRow {
  const { plan } = execution;
  const view = gtcOrderCardView(execution);
  const matched = Number(execution.matched);
  const display = view.quantitiesAgree && matched > 0
    ? gtcMatchedOrder(execution, view.fee == null ? 0 : Number(view.fee))
    : null;
  return {
    OrderID: execution.orderId ?? `gtc-pending:${execution.id}`,
    DisplayOnly: true,
    PmGtcExecutionId: execution.id,
    PmTokenId: plan.tokenId,
    PmConditionId: plan.conditionId,
    PmOrigin: "changmen",
    Link: plan.linkId,
    Type: "Polymarket",
    PlayerID: plan.playerId,
    Match: plan.match,
    Bet: lookupPolymarketOrderBetLabel(plan.conditionId, plan.tokenId) || "盘口待核实",
    Item: originalItemText(execution),
    CreateAt: execution.createdAt,
    Status: execution.submit === "rejected" && !view.unsubmitted
      ? "Reject"
      : execution.submit === "accepted" && execution.terminal && execution.complete && !execution.error && view.quantitiesAgree && matched === 0 ? "Return" : "None",
    PmSide: "buy",
    // 普通 PM 成交显示助手负责金额、成交价和赔率；无明细不使用计划量/限价。
    ...(view.quantitiesAgree ? { PmShares: matched } : {}),
    ...(display
      ? {
          PmFillPrice: display.pmFillPrice,
          Odds: display.odds,
          // 未知手续费不能按零费用展示成本；成交价/赔率仍来自普通助手。
          ...(view.fee != null
            ? {
                PmStakeUsdc: display.pmStakeUsdc,
                PmFeeUsdc: display.pmFeeUsdc ?? 0,
                BetMoney: display.betMoney,
              }
            : {}),
        }
      : view.quantitiesAgree && matched === 0 ? { PmStakeUsdc: 0, PmFeeUsdc: 0, BetMoney: 0 } : {}),
  };
}

export function gtcOrderDisplayGroups(financialRows: OrderRow[], executions: GtcExecution[], date: string, accountId: number) {
  const byExecution = new Map<string, { rows: OrderRow[]; execution?: GtcExecution; pending?: OrderRow }>();
  for (const row of filterOrdersBelongingToDate(financialRows, date)) {
    if (isFootballOrderRow(row) || (accountId && row.PlayerID !== accountId))
      continue;
    const identity = orderExecutionIdentity(row);
    if (identity.executionKind !== "pm-gtc-v1" || !identity.executionId)
      continue;
    const group = byExecution.get(identity.executionId) ?? { rows: [] };
    // 旧 GTC 入库赔率曾误用含费成本；展示沿用普通 PM 的成交价赔率回退。
    const pmLabel = row.Type === "Polymarket" ? lookupPolymarketOrderBetLabel(row.PmConditionId, row.PmTokenId) : "";
    group.rows.push({ ...row, ...(pmLabel ? { Bet: pmLabel } : {}),
      ...(row.Type === "Polymarket" && row.PmSide !== "sell" && Number(row.PmFillPrice) > 0 ? { Odds: undefined } : {}),
    });
    byExecution.set(identity.executionId, group);
  }
  for (const execution of executions) {
    // [changmen 扩展] 临时原单也只住 Link 归属日；未释放执行不能绕过日期筛选。
    const belongsToDate = filterOrdersBelongingToDate([{ CreateAt: execution.createdAt, Link: execution.plan.linkId }], date).length > 0;
    // [changmen 扩展] 副本缺失时可展示完整、相互一致的官方成交事实；不从旧累计量复活已释放历史。
    const releasedFactsCanDisplay = execution.submit === "accepted" && (Number(execution.matched) === 0
      || (execution.complete && !execution.error && gtcOrderCardView(execution).quantitiesAgree));
    // [changmen 扩展] 未提交的是执行记录；即使对腿已受理，也不能生成 PM 订单占位行。
    const showMissingOriginal = belongsToDate && !gtcPmNeverSubmitted(execution)
      && (!execution.released || releasedFactsCanDisplay);
    let group = byExecution.get(execution.id);
    if (!group) {
      if (!showMissingOriginal)
        continue;
      group = { rows: [] };
      byExecution.set(execution.id, group);
    }
    group.execution = execution;
    const hasOriginal = group.rows.some(row => row.Type === "Polymarket" && row.PmSide !== "sell"
      && row.PlayerID === execution.plan.playerId
      && String(row.OrderID).toLowerCase() === String(execution.orderId ?? execution.plan.orderHash).toLowerCase());
    if (!hasOriginal && showMissingOriginal) {
      group.pending = pendingOrderRow(execution);
      group.rows.push(group.pending);
    }
  }
  return [...byExecution].map(([id, group]) => ({
    id,
    ...group,
    // 临时原单与财务行均使用普通日期归属，不影响独立监控恢复。
    entries: orderLinkMapEntries(dropOrphanPolymarketSellGroups(groupOrdersByEffectiveLink([
      ...filterOrdersBelongingToDate(group.rows.filter(row => row !== group.pending), date),
      ...(group.pending ? [group.pending] : []),
    ]))),
  })).filter(group => group.entries.length);
}

export function isGtcOriginalBuy(row: OrderRow, execution: GtcExecution): boolean {
  return row.Type === "Polymarket" && row.PmSide !== "sell" && row.PlayerID === execution.plan.playerId
    && [execution.orderId, execution.plan.orderHash, `gtc-pending:${execution.id}`].filter(Boolean).some(id => String(row.OrderID).trim().toLowerCase() === String(id).trim().toLowerCase());
}

/** [changmen 扩展] 仅提供尚无财务行的展示原单；账号筛选及精确身份去重不改财务数据。 */
export function gtcPendingDisplayRows(financialRows: OrderRow[], executions: GtcExecution[], date: string, accountId: number): OrderRow[] {
  return gtcOrderDisplayGroups(financialRows, executions, date, accountId)
    .flatMap(group => group.pending && (!accountId || group.pending.PlayerID === accountId)
      && !financialRows.some(row => isGtcOriginalBuy(row, group.execution!)
        && (!row.PmGtcExecutionId || row.PmGtcExecutionId === group.id))
      ? [group.pending]
      : []);
}

/** [changmen 扩展] 精确原单恢复监控标识，再合入同 Link 展示行；FOK 原组保持原对象。 */
export function mergeGtcPendingDisplayEntries(entries: readonly (readonly [number, OrderRow[]])[], pendingRows: OrderRow[], executions: GtcExecution[] = []) {
  if (!pendingRows.length && !executions.length)
    return entries;
  const groups = new Map(entries);
  let changed = false;
  for (const [link, rows] of groups) {
    let tagged = false;
    const next = rows.map((row) => {
      if (row.PmGtcExecutionId || row.Type !== "Polymarket" || row.PmSide === "sell")
        return row;
      const originals = executions.filter(execution => isGtcOriginalBuy(row, execution));
      // 身份冲突保持原行，不按 Link 猜测来源，也不覆盖财务字段。
      if (originals.length !== 1)
        return row;
      tagged = true;
      return { ...row, PmGtcExecutionId: originals[0]!.id };
    });
    if (tagged) {
      groups.set(link, next);
      changed = true;
    }
  }
  for (const pending of pendingRows) {
    if ([...groups.values()].some(rows => rows.some(row => row.Type === "Polymarket" && row.PmSide !== "sell"
      && row.PlayerID === pending.PlayerID && String(row.OrderID).trim().toLowerCase() === String(pending.OrderID).trim().toLowerCase()))) {
      continue;
    }
    const link = Number(pending.Link);
    groups.set(link, [...(groups.get(link) ?? []), pending]);
    changed = true;
  }
  return changed ? orderLinkMapEntries(groups).sort(([a], [b]) => compareOrderLinkDesc({ Link: a }, { Link: b })) : entries;
}

import type { PmSubmission } from "@changmen/shared/pm_submission";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import type { OrderRow } from "@/types/order";
import { getAuthSessionVersion, isAuthSessionCurrent, post, unwrap } from "@/api/client";
import { tagKnownGtcVenueOrders } from "./executionProjection";
import { reconcileGtcSellFinancials } from "./sellFinancials";
import { listGtc } from "./api";
import { pendingGtcResults } from "./localStore";
import { confirmedGtcResult } from "./confirmedResult";

/** [changmen 扩展] 监控恢复按原单身份取数，不受侧栏日期限制，不建立第二份财务列表。 */
export async function loadGtcMonitorOrders(ids: string[], isCurrent: () => boolean = () => true): Promise<OrderRow[]> {
  if (!Array.isArray(ids) || ids.some(id => typeof id !== "string" || !/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(id)))
    throw new Error("GTC 监控恢复执行 ID 无效");
  if (!ids.length) return [];
  const session = getAuthSessionVersion();
  const checkCurrent = () => {
    if (!isAuthSessionCurrent(session) || !isCurrent())
      throw new Error("GTC 监控恢复登录状态已变更");
  };
  const read = async <T>(action: string, body: Record<string, unknown>) => {
    checkCurrent();
    const response = await post<T>(action, body, "", { errorTip: false });
    checkCurrent();
    return response;
  };
  const rows: OrderRow[] = [];
  const records = await listGtc();
  checkCurrent();
  if (ids.some(id => !records.some(row => row.id === id))) throw new Error("GTC 本地原单身份尚未恢复");
  const confirmed = records.filter(row => ids.includes(row.id) && row.fills && Number(confirmedGtcResult(row)?.financial.pmShares) > 0);
  // [changmen 扩展] 读取前捕获待同步状态，避免同步确认与 RDS 读取交错时误报缺失。
  const pending = new Set(confirmed.length ? (await pendingGtcResults(confirmed[0]!.owner)).map(entry => entry.result.executionId) : []);
  checkCurrent();
  for (let offset = 0; offset < ids.length; offset += 1000) {
    const batch = ids.slice(offset, offset + 1000);
    const anchors = records.filter(row => batch.includes(row.id)).flatMap(row => [
      { executionId: row.id, playerId: row.plan.playerId, provider: "Polymarket", orderId: row.orderId || row.plan.orderHash },
      ...(row.other.orderId ? [{ executionId: row.id, playerId: row.plan.otherPlayerId, provider: row.plan.otherProvider, orderId: row.other.orderId }] : []),
    ]);
    for (let start = 0; start < anchors.length; start += 1000) {
      const selected = anchors.slice(start, start + 1000);
      const orders = unwrap(await read<OrderRow[]>("Pm_GtcReadResults", { anchors: selected }));
      if (!Array.isArray(orders) || orders.some(order => !selected.some(anchor => order.PmGtcExecutionId === anchor.executionId
        && order.PlayerID === anchor.playerId && order.Type === anchor.provider && String(order.OrderID).toLowerCase() === anchor.orderId.toLowerCase())))
        throw new Error("GTC 监控恢复订单响应无效");
      rows.push(...orders);
    }
  }
  checkCurrent();
  if (confirmed.some(row => !pending.has(row.id) && !rows.some(order => order.PmGtcExecutionId === row.id
    && order.PlayerID === row.plan.playerId && order.Type === "Polymarket")))
    throw new Error("GTC 监控恢复已确认原单财务记录缺失，请核对原单身份");
  return rows;
}

export async function getPmSubmission(playerId: number, orderId: string): Promise<PmSubmission | null> {
  const response = await post<PmSubmission>("Pm_GetSubmission", { playerId, orderId }, "", { errorTip: false });
  return response.success === 1 ? response.info ?? null : null;
}

export async function saveOrders(account: PlatformAccount, orders: VenueOrder[]): Promise<void> {
  if (account.provider === "PredictFun")
    return;
  const session = getAuthSessionVersion();
  const checkCurrent = () => { if (!isAuthSessionCurrent(session)) throw new Error("GTC 结果保存登录状态已变更"); };
  checkCurrent();
  const tagged = await reconcileGtcSellFinancials(account, tagKnownGtcVenueOrders(account.accountId, orders));
  checkCurrent();
  const groups = new Map<string, VenueOrder[]>();
  const records = await listGtc();
  checkCurrent();
  for (const order of tagged) {
    const type = String(order.provider ?? account.provider);
    if (type === "PredictFun")
      continue;
    const list = groups.get(type) ?? [];
    list.push(order);
    groups.set(type, list);
  }
  for (const [type, list] of groups) {
    const origins = list.map(order => {
      const id = (order as VenueOrder & { pmGtcExecutionId?: string }).pmGtcExecutionId;
      const execution = records.find(row => row.id === id);
      if (!execution || ![execution.plan.playerId, execution.plan.otherPlayerId].includes(account.accountId))
        throw new Error("GTC 已确认原单身份缺失");
      return { executionId: execution.id, playerId: account.accountId, provider: type,
        orderId: order.pmBuyOrderId ?? order.pfBuyOrderId ?? order.orderId };
    });
    checkCurrent();
    unwrap(await post("Pm_GtcSaveOrders", { type, playerId: account.accountId, orders: JSON.stringify(list), origins }));
    checkCurrent();
  }
}

export async function refreshGtcOrders(date?: string, isCurrent: () => boolean = () => true): Promise<void> {
  const session = getAuthSessionVersion();
  const { useOrderStore } = await import("@/stores/orderStore");
  if (!isAuthSessionCurrent(session) || !isCurrent())
    return;
  const store = useOrderStore();
  await store.fetchOrders(date ?? store.orderDate);
}

import type { GtcExecution } from "@changmen/shared/pm_gtc";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
/** 原单 id 优先；缺 id 时只接纳唯一的场馆比赛/选项/金额/时间完全绑定候选。 */
export function findGtcOtherOrder(row: GtcExecution, orders: readonly VenueOrder[]): VenueOrder | undefined {
  const candidates = orders.filter((order) => {
    if (order.provider !== row.plan.otherProvider)
      return false;
    if (row.other.orderId)
      return order.orderId === row.other.orderId;
    // 提交未知不等于已受理；相同盘口/金额的 FOK 不能证明未知 GTC 的身份。
    if (!["accepted", "pending", "filled"].includes(row.other.state))
      return false;
    // 已绑定其它 changmen 执行的订单不是待猜测的 GTC 原单，禁止改绑 FOK。
    const link = Number(order.link);
    if (Number.isFinite(link) && Math.abs(link) >= 1_000_000_000_000 && link !== row.plan.linkId)
      return false;
    return Boolean(row.plan.otherVenueMatchId && row.plan.otherVenueItemId)
      && order.venueMatchId === row.plan.otherVenueMatchId && order.venueItemId === row.plan.otherVenueItemId
      && Math.abs(order.betMoney - row.plan.otherStake) < 0.01
      && order.createAt >= row.other.submittedAt - 1000 && order.createAt <= row.other.submittedAt + 120000;
  });
  return candidates.length === 1 ? candidates[0] : undefined;
}

/** [changmen 扩展] PM 配对状态消费场馆订单事实；RAY 沿用公共拉单、保存和绑定流程。 */
