import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import { Currency, getExchange } from "@changmen/shared/currency";
import { readGtcSellCash } from "@changmen/venue-adapter/polymarket/gtc";

/** [changmen 扩展] 卖出回款已含卖出手续费；买入含费成本由服务端原单校准。 */
export async function reconcileGtcSellFinancials(account: PlatformAccount, orders: VenueOrder[]): Promise<VenueOrder[]> {
  const result = orders.map(row => ({ ...row }));
  for (const sell of result.filter(row => row.provider === "Polymarket" && row.pmSide === "sell"
    && (row as VenueOrder & { pmGtcExecutionId?: string }).pmGtcExecutionId)) {
    const cash = await readGtcSellCash(account, sell);
    const fx = getExchange(Currency.USDT);
    const buy = result.find(row => row.orderId.toLowerCase() === sell.pmBuyOrderId?.toLowerCase());
    const event = buy?.positionEvents?.sells?.find(event => event.id.toLowerCase() === sell.orderId.toLowerCase());
    // 公共卖单 CNY 镜像可能已取两位；差额必须用该次原币流水核对。
    const delta = cash - (event?.proceeds ?? sell.betMoney / fx);
    sell.betMoney = cash * fx;
    sell.pmRealizedPnlUsdc = Math.round((cash - (Number(sell.pmStakeUsdc) || 0)) * 10000) / 10000;
    if (!buy) continue; // 服务端也支持仅卖单重试，按本卖单流水校准原买单。
    buy.pmSellProceeds = Math.round(((Number(buy.pmSellProceeds) || 0) + delta) * 10000) / 10000;
    buy.pmRealizedPnlUsdc = Math.round(((Number(buy.pmRealizedPnlUsdc) || 0) + delta) * 10000) / 10000;
    buy.money = Math.round(buy.pmRealizedPnlUsdc * fx * 10000) / 10000;
    if (buy.positionEvents) buy.positionEvents = { ...buy.positionEvents,
      sells: buy.positionEvents.sells?.map(event => event.id.toLowerCase() === sell.orderId.toLowerCase()
        ? { ...event, proceeds: cash, pnl: sell.pmRealizedPnlUsdc } : event) };
  }
  return result;
}

/** [changmen 扩展] 只保留已保存原单的结算证据，查询停止不随侧栏日期/筛选改变。 */
import type { GtcExecution } from "@changmen/shared/pm_gtc";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { OrderRow } from "@/types/order";

function isFinal(row: OrderRow) {
  return row.PmSide !== "sell"
    && ["win", "lose", "lost", "return", "reject"].includes(String(row.Status).toLowerCase());
}
const key = (row: OrderRow) => JSON.stringify([row.PmGtcExecutionId, row.PlayerID, row.Type, String(row.OrderID).toLowerCase()]);

export function createGtcSettlementEvidence() {
  const settled = new Map<string, OrderRow>();
  return {
    rows(current: OrderRow[]): OrderRow[] {
      for (const row of current) {
        if (!row.PmGtcExecutionId || row.PmSide === "sell")
          continue;
        if (isFinal(row))
          settled.set(key(row), row);
      }
      return [...settled.values(), ...current];
    },
    rememberOther(execution: GtcExecution, original: VenueOrder): void {
      const row: OrderRow = { PmGtcExecutionId: execution.id, PlayerID: execution.plan.otherPlayerId, Type: execution.plan.otherProvider, OrderID: original.orderId, Status: original.status };
      if (isFinal(row))
        settled.set(key(row), row);
    },
    reset(): void { settled.clear(); },
  };
}

import { wait } from "@changmen/client-core/shared/wait";
import {
  ensureChangmenHubConnected,
  leaveChangmenChannel,
  publishChangmenChannel,
  subscribeChangmenChannel,
} from "@changmen/venue-adapter/shared";

/**
 * [changmen 实现] 自研 realtime-hub pub/sub 客户端（BetTarget / 操盘 / 跟单）
 * 频道名与 A8 bundle GoEasy pub/sub 对齐；不经第三方 GoEasy SaaS。
 */

const channelCleanups = new Map<string, () => void>();
const channelHandlers = new Map<string, Set<(content: string) => void>>();

function contentToString(content: unknown): string {
  if (typeof content === "string")
    return content;
  if (content == null)
    return "";
  try {
    return JSON.stringify(content);
  }
  catch {
    return String(content);
  }
}

function dispatchChannelMessage(channel: string, content: unknown) {
  const handlers = channelHandlers.get(channel);
  if (!handlers)
    return;
  const text = contentToString(content);
  for (const fn of handlers)
    fn(text);
}

/** 对齐 A8 `W8e`：连接 changmen realtime-hub */
export function ensurePubsubConnected(): Promise<void> {
  return ensureChangmenHubConnected().then((ok) => {
    if (!ok)
      throw new Error("realtime hub 连接失败");
  });
}

/** 对齐 A8 `lv` */
export async function pubsubSubscribe(
  channel: string,
  onMessage: (content: string) => void,
): Promise<void> {
  await ensurePubsubConnected();

  let set = channelHandlers.get(channel);
  if (!set) {
    set = new Set();
    channelHandlers.set(channel, set);
  }
  set.add(onMessage);

  if (!channelCleanups.has(channel)) {
    const cleanup = await subscribeChangmenChannel(channel, (msg) => {
      dispatchChannelMessage(channel, msg);
    });
    channelCleanups.set(channel, cleanup);
  }
}

export function pubsubUnsubscribe(channel: string) {
  channelHandlers.delete(channel);
  const cleanup = channelCleanups.get(channel);
  if (cleanup) {
    cleanup();
    channelCleanups.delete(channel);
  }
  else {
    leaveChangmenChannel(channel);
  }
}

/** 对齐 A8 `ax` */
export function pubsubPublish(channel: string, message: string): Promise<boolean> {
  return publishChangmenChannel(channel, message);
}

const replyWaiters = new Map<string, unknown>();

/** 对齐 A8 `L8e` */
export function pubsubSetReply(msgId: string, content: unknown) {
  replyWaiters.set(msgId, content);
}

/** 对齐 A8 `U8e`：发布并等待对端经 reply 频道回传 msgId */
export async function pubsubRequestReply(
  channel: string,
  msgId: string,
  payload: string,
  timeoutMs = 3000,
): Promise<unknown> {
  if (!(await pubsubPublish(channel, payload)))
    return undefined;
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (replyWaiters.has(msgId)) {
      const value = replyWaiters.get(msgId);
      replyWaiters.delete(msgId);
      return value;
    }
    await wait(10);
  }
  return undefined;
}

export function newMsgId(): string {
  return globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

