export type PodRayFollowPlaceTicket = Omit<PodPmFollowPlaceTicket, "pmMatchId"> & {
  rayMatchId: string; submitBefore?: number;
};

export function listRayFollowAccounts(accounts: PlatformAccount[], ids?: number[]): PlatformAccount[] {
  const selected = ids ? new Set(ids) : null;
  return accounts.filter(a => a.provider === "RAY" && (!selected || selected.has(Number(a.accountId))));
}

export function podRayFollowPlaceBlock(ticket: PodRayFollowPlaceTicket): string | null {
  if (ticket.fixtureStatus !== "matched") return "场未对上";
  if (ticket.market.status !== "matched" || ticket.market.venue !== "RAY") return "无 RAY 盘";
  if (!ticket.rayMatchId || !ticket.market.oid) return "RAY 盘口不完整";
  if (ticket.market.locked) return "RAY 锁盘";
  if (!['home', 'away', 'draw', 'over', 'under'].includes(String(ticket.market.boardSide))) return "无投注方向";
  if (ticket.quote.status !== "ok") return ticket.quote.status === "spike" ? "EV 异常" : "RAY 价不够";
  if (!(Number(ticket.stake) > 0)) return "RAY金额未设";
  if (!ticket.accountIds?.some(id => Number(id) > 0)) return "请选择 RAY 账号";
  if (ticket.auto && ticket.fixtureBasis !== "confirmed") return "身份未确认";
  if (ticket.auto && !ticket.market.fromLive) return "等实时价";
  if (ticket.auto && ticket.submitBefore && Date.now() >= ticket.submitBefore) return "信号已过期或比赛已开赛";
  return null;
}

export function rayGateEntry(ticket: PodRayFollowPlaceTicket): PodOutcomeGateEntry {
  return { obMid: ticket.rayMatchId, marketCode: ticket.market.marketCode, boardSide: ticket.market.boardSide };
}

export function pickPodRayAutoTicket(
  tickets: PodRayFollowPlaceTicket[], skipped: Iterable<string>, entries: PodOutcomeGateEntry[],
  cap: { todayProfit: number; openStake: number; maxDailyLoss: number },
): PodRayFollowPlaceTicket | null {
  if (podYaboDailyLossBlocked(cap)) return null;
  const seen = new Set(skipped);
  return tickets.filter(t => !seen.has(t.id) && t.fixtureBasis === "confirmed" && t.market.fromLive
    && !podRayFollowPlaceBlock(t) && evaluatePodOutcomeGate(rayGateEntry(t), entries).allow)
    .sort((a, b) => Number(b.quote.evPercent) - Number(a.quote.evPercent))[0] || null;
}

type RayBindTask = {
  key: string; ticket: PodRayFollowPlaceTicket; accountId: number; at: number;
  beforeIds: string[]; match: string; bet: string; item: string;
  venueStake: number; exchange: number; accepted: boolean;
};

function storageKey(): string {
  const user = useUserStore();
  return `changmen:ray-football-bind:v1:${String(user.userId || user.userName || "")}`;
}

export function readRayFootballBindTasks(scope = storageKey()): RayBindTask[] {
  try {
    const rows = JSON.parse(localStorage.getItem(scope) || "[]");
    return Array.isArray(rows) ? rows.filter(r => r && typeof r.key === "string"
      && r.ticket?.rayMatchId && Array.isArray(r.beforeIds) && r.at > 0 && r.venueStake > 0) : [];
  }
  catch { return []; }
}

function writeTasks(rows: RayBindTask[], scope = storageKey()): void {
  // 提交前必须能保存恢复任务；失败时不调用场馆。
  localStorage.setItem(scope, JSON.stringify(rows));
}

function upsertTask(task: RayBindTask, scope: string): void {
  const rows = readRayFootballBindTasks(scope);
  writeTasks([...rows.filter(r => r.key !== task.key), task], scope);
}

export function matchRayFootballOrder(task: RayBindTask, orders: VenueOrder[]): VenueOrder | null {
  const previous = new Set(task.beforeIds);
  const rows = orders.filter(o => !previous.has(String(o.orderId)) && o.orderId
    && Number(o.createAt) >= task.at - 2000 && Number(o.createAt) <= task.at + 60_000
    && String(o.match).trim() === task.match && String(o.bet).trim() === task.bet
    && String(o.item).trim() === task.item && Math.abs(Number(o.betMoney) - task.venueStake) < 0.01);
  return rows.length === 1 ? rows[0] : null;
}

function taggedOrder(task: RayBindTask, order: VenueOrder): VenueOrder {
  return { ...order, domain: "sports", sport: "football",
    source: task.ticket.auto ? "football-pod-auto" : task.ticket.id.startsWith("board:") ? "football-board" : "football-pod",
    podClientId: task.ticket.id, podRayMatchId: task.ticket.rayMatchId,
    podMarketCode: task.ticket.market.marketCode, podBoardSide: task.ticket.market.boardSide || undefined };
}

let syncing = false;
export async function syncRayFootballOrders(): Promise<void> {
  if (syncing) return;
  syncing = true;
  const scope = storageKey();
  try {
    const accounts = useAccountStore();
    const { getOrderList } = await import("@/api/order");
    const existing = await getOrderList({ domain: "sports", sport: "football", pageIndex: 1, pageSize: 1024 });
    const saved = (existing?.list || []).filter(r => r.Type === "RAY" && r.Domain === "sports" && r.Sport === "football");
    const tasks = readRayFootballBindTasks(scope);
    const ids = new Set([...tasks.map(t => t.accountId), ...saved.map(r => Number(r.PlayerID))]);
    for (const id of ids) {
      const account = accounts.findAccount(id);
      if (!account || account.provider !== "RAY") continue;
      const provider = getProvider(account);
      if (!provider?.getOrders) continue;
      try {
        const orders = await provider.getOrders(account);
        if (storageKey() !== scope) return;
        for (const task of tasks.filter(t => t.accountId === id)) {
          const order = matchRayFootballOrder(task, orders);
          if (!order) continue;
          await saveOrders(account, [taggedOrder(task, order)]);
          writeTasks(readRayFootballBindTasks(scope).filter(t => t.key !== task.key), scope);
        }
        for (const row of saved.filter(r => Number(r.PlayerID) === id)) {
          const order = orders.find(o => String(o.orderId) === String(row.OrderID));
          if (order) await saveOrders(account, [{ ...order, domain: "sports", sport: "football",
            source: row.Source, podClientId: row.PodClientId, podRayMatchId: row.PodRayMatchId,
            podMarketCode: row.PodMarketCode, podBoardSide: row.PodBoardSide }]);
        }
      }
      catch (err) { console.warn("[football] RAY order sync failed", err); }
    }
  }
  finally { syncing = false; }
}

// [changmen 扩展] 复用场馆预检时隔离电竞 fo，RAY 平局仍由 oddId 唯一选择。
class RayFootballBetOption extends BetOption {
  override updateOdds(odds: number) {
    useSportOddsStore().saveMany("RAY", [{ id: this.itemId, odds }]);
  }
}

let placing = false;
export async function placePodRayFollowBet(ticket: PodRayFollowPlaceTicket): Promise<{ ok: boolean; message: string }> {
  const block = podRayFollowPlaceBlock(ticket);
  if (block) return { ok: false, message: block };
  if (placing) return { ok: false, message: "RAY 下单中" };
  const store = useAccountStore();
  const accounts = listRayFollowAccounts(store.accounts, ticket.accountIds || []);
  if (!accounts.length) return { ok: false, message: "未找到已选择的 RAY 账号" };
  const notes: string[] = [], failures: string[] = [];
  const scope = storageKey();
  placing = true;
  try {
    for (const account of accounts) {
      const key = `${ticket.id}#RAY#${account.accountId}`;
      if (readRayFootballBindTasks().some(t => t.key === key)) {
        failures.push(`${account.playerName}:已有待确认提交`); continue;
      }
      if (!account.gateway || !account.token) { failures.push(`${account.playerName}:凭证不完整`); continue; }
      const side = ticket.market.boardSide === "away" || ticket.market.boardSide === "under" ? "Away" : "Home";
      const option = new RayFootballBetOption("RAY", ticket.rayMatchId, String(ticket.market.betId || ""),
        ticket.market.oid, ticket.stake, side, ticket.quote.quote);
      // 场馆预检允许涨价；足球策略必须再次校验 EV 上限。
      const checked = await store.checkBetting(account, option);
      const live = Number(checked.odds);
      if (!checked.data || checked.checkError || !(live > 1) || live < ticket.quote.minObOdds
        || (ticket.quote.maxObOdds > 1 && live > ticket.quote.maxObOdds)) {
        failures.push(`${account.playerName}:${checked.checkError || "预检赔率不在策略范围"}`); continue;
      }
      const raw = checked.response as { match_name?: string; match_stage?: string; group_name?: string; name?: string };
      const provider = getProvider(account);
      if (!provider?.getOrders || !raw.match_name || !raw.group_name || !raw.name) {
        failures.push(`${account.playerName}:缺少订单绑定信息`); continue;
      }
      let before: VenueOrder[];
      try { before = await provider.getOrders(account); }
      catch { failures.push(`${account.playerName}:提交前订单查询失败`); continue; }
      if (storageKey() !== scope) { failures.push("登录用户已切换"); break; }
      let leaseToken = "";
      if (ticket.auto) {
        const lease = await reservePodBetExecution({ alertId: ticket.id, venue: "RAY", playerId: account.accountId });
        if (!lease.acquired) { failures.push(`${account.playerName}:已由其他页面处理`); continue; }
        leaseToken = lease.leaseToken;
      }
      const task: RayBindTask = { key, ticket, accountId: account.accountId, at: Date.now(),
        beforeIds: before.map(o => String(o.orderId)), match: raw.match_name.trim(),
        bet: `${raw.match_stage || ""} ${raw.group_name}`.trim(), item: raw.name.trim(),
        venueStake: Math.round(checked.betMoney), exchange: getExchange(account.currency), accepted: false };
      try { upsertTask(task, scope); }
      catch { failures.push(`${account.playerName}:无法保存提交恢复任务`); continue; }
      const settings = ticket.auto ? readPodBetSettings() : null;
      const paused = settings && (!settings.enabled || !settings.autoPlace || !(settings.rayStake > 0)
        || !settings.rayFollowAccountIds.includes(account.accountId));
      const lateBlock = storageKey() !== scope ? "登录用户已切换" : paused ? "RAY 自动跟单已暂停或账号已取消" : podRayFollowPlaceBlock(ticket);
      if (lateBlock) {
        writeTasks(readRayFootballBindTasks(scope).filter(t => t.key !== key), scope);
        if (leaseToken) await finalizePodBetExecution({ leaseToken, state: "failed", message: lateBlock }).catch(() => {});
        failures.push(`${account.playerName}:${lateBlock}`); continue;
      }
      let result;
      try { result = await store.betting(account, checked, 0, { requirePreparedQuote: true }); }
      catch (err) {
        if (leaseToken) await finalizePodBetExecution({ leaseToken, state: "unknown", message: String(err) }).catch(() => {});
        failures.push(`${account.playerName}:结果未知，等待回查`); continue;
      }
      if (!result.success) {
        const unknown = result.response == null;
        if (!unknown) writeTasks(readRayFootballBindTasks(scope).filter(t => t.key !== key), scope);
        if (leaseToken) await finalizePodBetExecution({ leaseToken, state: unknown ? "unknown" : "failed", message: result.message || undefined }).catch(() => {});
        failures.push(`${account.playerName}:${unknown ? "结果未知，等待回查" : result.message}`); continue;
      }
      // POST 成功后即受理；绑单/落库失败不能把成功伪装成可重试失败。
      try { upsertTask({ ...task, accepted: true }, scope); } catch { /* 提交前的任务仍可恢复 */ }
      if (leaseToken) await finalizePodBetExecution({ leaseToken, state: "accepted", message: "RAY 已受理，回查订单号" }).catch(() => {});
      notes.push(`${account.playerName}:已受理`);
    }
    await syncRayFootballOrders().catch(() => {});
  }
  catch (err) { failures.push(err instanceof Error ? err.message : String(err)); }
  finally { placing = false; }
  return { ok: notes.length > 0, message: [...notes, ...failures].join("；") || "RAY 下单失败" };
}

import type { PlatformProvider } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import { getProvider as venueProvider } from "@/runtime/venueAdapters";
import { beginRayOrderObservation } from "./orderMonitoring/rayOrders";
import { beginRaySubmissionPreview } from "./rayOrderMonitor/submissionPreview";

export { supportedBetProviders } from "@/runtime/venueAdapters";
const observed = new WeakMap<PlatformProvider, PlatformProvider>();

/** [changmen 扩展] 原查询每次照常执行，只旁听返回值；不缓存、合并、重试或等待消费者。 */
export function getProvider(account: PlatformAccount): PlatformProvider | undefined {
  const provider = venueProvider(account);
  if (account.provider !== "RAY" || !provider?.getOrders)
    return provider;
  let wrapper = observed.get(provider);
  if (!wrapper) {
    wrapper = { ...provider, betting(account, option) {
      let accept: ReturnType<typeof beginRaySubmissionPreview>;
      try { accept = beginRaySubmissionPreview(account, option); }
      catch { /* 提前展示登记失败不阻断原下注。 */ }
      return provider.betting.call(provider, account, option).then((result) => {
        try { accept?.(result); }
        catch { /* 提前展示不改变原回执。 */ }
        return result;
      });
    }, getOrders(account) {
      const publish = beginRayOrderObservation(account);
      return provider.getOrders!.call(provider, account).then((orders) => {
        try { publish(orders); }
        catch { /* 被动展示不能影响原查询结果和拒单检测。 */ }
        return orders;
      });
    } };
    observed.set(provider, wrapper);
  }
  return wrapper;
}

/** [changmen 扩展] 独立订单监控的关联及补单上下文；没有查询或定时器。 */
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import type { RayOrderContext, RegisterRayOrderContextInput } from "./types";
import { saveUserLog } from "@/api/chat";
import { observeOrder } from "@/services/orderObservation";
import { rayRejectFailureEvidence } from "@/services/orderObservationEvidence";
import { useUserStore } from "@/stores/userStore";
import { useRayOrderContextStore } from "./contextStore";
import { matchRayVenueOrder } from "./match";

type RayOrderFact = Pick<VenueOrder, "orderId" | "status"> & Partial<VenueOrder>;
function log(task: RayOrderContext, event: "registered" | "bound" | "rejected" | "closed", order?: RayOrderFact): void {
  try {
    observeOrder(task.observation, task.linkId, event === "rejected" || event === "closed" ? "settlement_observed" : "decision", {
      provider: "RAY", accountId: task.accountId, orderId: order?.orderId || task.boundOrderId,
      target: task.target, outcome: event === "rejected" ? "unfilled" : event === "closed" ? "filled" : event,
      source: "ray_monitor", phase: "ray_order_monitor", observedStatus: order?.status, reasonCode: event,
      ...(event === "rejected" && order?.venueRejectReason ? rayRejectFailureEvidence(order.venueRejectReason) : {}),
    });
    void saveUserLog(`RAY订单监控 => ${event}`, {
      diagnosticVersion: 3, monitoringMode: "ray-order-monitor", monitorEvent: event,
      linkId: task.linkId, provider: "RAY", accountId: task.accountId,
      orderId: order?.orderId ?? task.boundOrderId ?? null, betId: task.betId, side: task.side,
      target: task.target, match: task.match, bet: task.bet, item: task.item, odds: task.odds,
      betMoney: task.betMoney, placedAt: task.submittedAt, observedAt: Date.now(),
      rejectDelayMs: task.rejectDelayMs ?? null, observedStatus: order?.status ?? task.lastObservedStatus ?? "missing",
    }).catch(() => {});
  }
  catch { /* 观察日志不影响原下注流程或监控。 */ }
}
/** 原首次确认完成后，只交接上下文，不查询、不修改首次拒单检测结论。 */
export function registerRayOrderContext(input: RegisterRayOrderContextInput): void {
  try {
    if (input.initialRejected || !input.linkId || !input.accountId)
      return;
    const userId = String(useUserStore().userId || "");
    if (!userId)
      return;
    const store = useRayOrderContextStore(); store.restore(userId);
    const key = `${userId}:${input.linkId}:${input.side}:${input.accountId}`;
    if (store.tasks.has(key))
      return;
    const { initialOrders, initialRejected: _initialRejected, ...context } = input;
    const now = Date.now();
    const task: RayOrderContext = { ...context, key, userId, submittedAt: input.submittedAt || now,
      status: "binding", candidateCount: 0, pollCount: 0, updatedAt: now };
    const match = matchRayVenueOrder(task, initialOrders);
    if (match.kind === "matched") {
      task.boundOrderId = match.candidate.order.orderId;
      task.submittedAt = match.candidate.order.createAt || task.submittedAt;
      task.lastObservedStatus = match.candidate.order.status;
      task.status = "watching";
    }
    else if (match.kind === "ambiguous") {
      task.status = "ambiguous";
    }
    task.candidateCount = match.candidates.length;
    store.upsert(task); log(task, "registered");
  }
  catch { /* 登记失败不能改变首次下注收尾。 */ }
}
/** [changmen 扩展] 只确认用户端原单身份；数据库保存及 Link 绑定由订单同步负责。 */
export function bindRayOrderContexts(account: PlatformAccount, orders: readonly VenueOrder[], current: () => boolean): void {
  const store = useRayOrderContextStore();
  for (const original of store.activeTasks.filter(task => task.accountId === account.accountId)) {
    if (!current())
      return;
    const claimed = new Set([...store.tasks.values()].filter(task => task.accountId === account.accountId && task.key !== original.key && task.boundOrderId).map(task => task.boundOrderId));
    const candidates = orders.filter(order => order.provider === "RAY" && (original.boundOrderId || !claimed.has(order.orderId)));
    const match = original.boundOrderId ? undefined : matchRayVenueOrder(original, candidates);
    const order = original.boundOrderId ? candidates.find(order => order.orderId === original.boundOrderId)
      : match?.kind === "matched" ? match.candidate.order : undefined;
    const task: RayOrderContext = { ...original, pollCount: original.pollCount + 1, lastPollAt: Date.now(), updatedAt: Date.now() };
    if (!order) {
      task.status = match?.kind === "ambiguous" ? "ambiguous" : original.boundOrderId ? "watching" : "binding";
      task.candidateCount = match?.candidates.length ?? task.candidateCount;
      task.lastObservedStatus = "missing";
      store.upsert(task); continue;
    }
    task.boundOrderId = order.orderId;
    task.submittedAt = order.createAt || task.submittedAt;
    task.candidateCount = match?.candidates.length ?? task.candidateCount;
    task.status = "watching";
    store.upsert(task);
    store.patch(task.key, { monitorBound: true, lastError: undefined });
    if (!original.monitorBound) {
      store.patch(task.key, { boundAt: Date.now() });
      log(task, "bound", order);
    }
  }
}
function dispatchMakeup(task: RayOrderContext, current: () => boolean): void {
  void import("./autoMakeup").then(({ handleRayLateRejectAutoMakeup }) => {
    if (current())
      return handleRayLateRejectAutoMakeup(task, current);
  }).catch((error) => {
    if (current())
      useRayOrderContextStore().patch(task.key, { autoMakeupStatus: "failed", autoMakeupReason: String(error), updatedAt: Date.now() });
  });
}
/** [changmen 扩展] 消费唯一确认的场馆原单事实，拒单仍交给原补单策略。 */
export function observeRayOrderContexts(player: number, orders: readonly RayOrderFact[], current: () => boolean): void {
  if (!current())
    return;
  const store = useRayOrderContextStore();
  for (const task of store.activeTasks.filter(task => task.accountId === player && task.boundOrderId && (task.monitorBound || task.bindingSaved))) {
    const order = orders.find(order => order.orderId === task.boundOrderId);
    if (!order)
      continue;
    const now = Date.now();
    if (order.status === "reject") {
      const enabled = useUserStore().extensionPrefs?.rayLateRejectAutoMakeup?.enabled === true;
      const rejected: RayOrderContext = { ...task, status: "rejected", lastObservedStatus: "reject", rejectedAt: now,
        rejectDelayMs: Math.max(0, now - task.submittedAt), lastError: undefined, updatedAt: now,
        autoMakeupStatus: enabled ? undefined : "disabled", autoMakeupReason: enabled ? undefined : "自动补单未开启" };
      store.upsert(rejected); log(rejected, "rejected", order);
      if (enabled)
        dispatchMakeup(rejected, current);
    }
    else if (["win", "lose", "return"].includes(order.status)) {
      store.patch(task.key, { status: "closed", lastObservedStatus: order.status, lastError: undefined, updatedAt: now });
      log(task, "closed", order);
    }
    else {
      store.patch(task.key, { lastObservedStatus: order.status, lastError: undefined, updatedAt: now });
    }
  }
}
export function resumeRayContextMakeup(current: () => boolean): void {
  for (const task of useRayOrderContextStore().tasks.values()) {
    if (task.status === "rejected" && (!task.autoMakeupStatus || task.autoMakeupStatus === "enqueuing"))
      dispatchMakeup(task, current);
  }
}

/** [changmen 扩展] 场馆监控仅更新现有客户端订单，不创建账本订单或发起 HTTP 请求。 */
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { OrderRow } from "@/types/order";
import { useOrderStore } from "@/stores/orderStore";

export function rayClientStatus(status: VenueOrder["status"]): OrderRow["Status"] {
  return (status[0]!.toUpperCase() + status.slice(1)) as OrderRow["Status"];
}

export function updateRayOrdersLocally(player: number, orders: readonly VenueOrder[]): void {
  const store = useOrderStore();
  const byId = new Map(orders.filter(order => order.provider === "RAY").map(order => [String(order.orderId), order]));
  let changed = false;
  for (const rows of store.orders.values()) {
    for (const row of rows) {
      if (row.Type !== "RAY" || row.PlayerID !== player || row.DisplayOnly)
        continue;
      const order = byId.get(String(row.OrderID));
      if (!order || ["win", "lose", "lost", "return", "reject"].includes(String(row.Status).toLowerCase()))
        continue;
      const status = rayClientStatus(order.status);
      if (row.Status !== status) { row.Status = status; changed = true; }
      // 身份、Link、买入时间和 GTC/POD 元数据沿用已有行，仅更新场馆事实。
      for (const [field, value] of [["Odds", order.odds], ["BetMoney", order.betMoney], ["Money", order.money]] as const) {
        if (typeof value === "number" && Number.isFinite(value) && row[field] !== value) {
          row[field] = value; changed = true;
        }
      }
    }
  }
  if (changed)
    store.updateTodayProfit([...store.orders.values()].flat());
}

import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type {
  RayOrderCandidate,
  RayOrderMatchResult,
  RayOrderContext,
} from "./types";

const MAX_ORDER_TIME_DRIFT_MS = 120_000;
const MIN_MATCH_SCORE = 10;
const MIN_UNIQUE_MARGIN = 3;

function normalizeText(value: unknown): string {
  return String(value ?? "")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/\b(vs|v)\b/gi, " ")
    .replace(/[^\p{L}\p{N}]+/gu, "")
    .toLowerCase();
}

function textMatches(expected: string, actual: string): boolean {
  const left = normalizeText(expected);
  const right = normalizeText(actual);
  if (!left || !right)
    return false;
  return left === right || left.includes(right) || right.includes(left);
}

function scoreCandidate(task: RayOrderContext, order: VenueOrder): RayOrderCandidate | null {
  if (String(order.provider).toUpperCase() !== "RAY")
    return null;

  const timeDiff = Math.abs((Number(order.createAt) || 0) - task.submittedAt);
  if (!Number(order.createAt) || timeDiff > MAX_ORDER_TIME_DRIFT_MS)
    return null;

  const moneyDiff = Math.abs((Number(order.betMoney) || 0) - task.betMoney);
  const moneyTolerance = Math.max(1, Math.abs(task.betMoney) * 0.02);
  if (moneyDiff > moneyTolerance)
    return null;

  const oddsDiff = Math.abs((Number(order.odds) || 0) - task.odds);
  if (task.odds > 0 && oddsDiff > 0.05)
    return null;

  let score = 0;
  const reasons: string[] = [];

  score += moneyDiff <= 0.01 ? 5 : 3;
  reasons.push(`金额差${moneyDiff.toFixed(2)}`);

  if (task.odds > 0) {
    score += oddsDiff <= 0.011 ? 4 : 2;
    reasons.push(`赔率差${oddsDiff.toFixed(3)}`);
  }

  if (timeDiff <= 10_000)
    score += 4;
  else if (timeDiff <= 60_000)
    score += 3;
  else
    score += 1;
  reasons.push(`时间差${Math.round(timeDiff / 1000)}s`);

  if (textMatches(task.item, order.item)) {
    score += 4;
    reasons.push("选项一致");
  }
  if (textMatches(task.match, order.match)) {
    score += 3;
    reasons.push("比赛一致");
  }
  if (textMatches(task.bet, order.bet)) {
    score += 2;
    reasons.push("盘口一致");
  }

  return { order, score, reasons };
}

/** 只在候选唯一且分数足够时绑定；模糊结果宁可等待，不猜单。 */
export function matchRayVenueOrder(
  task: RayOrderContext,
  orders: readonly VenueOrder[],
): RayOrderMatchResult {
  const candidates = orders
    .map(order => scoreCandidate(task, order))
    .filter((candidate): candidate is RayOrderCandidate => Boolean(candidate))
    .sort((a, b) => b.score - a.score || b.order.createAt - a.order.createAt);

  const best = candidates[0];
  if (!best || best.score < MIN_MATCH_SCORE)
    return { kind: "missing", candidates };

  const second = candidates[1];
  if (second && best.score - second.score < MIN_UNIQUE_MARGIN)
    return { kind: "ambiguous", candidates };

  return { kind: "matched", candidate: best, candidates };
}

/** [changmen 扩展] RAY 用户端原单监控：恢复、查单、本地更新及拒单事件，不写订单数据库。 */
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import type { OrderRow } from "@/types/order";
import { getAuthSessionVersion, isAuthSessionCurrent } from "@/api/client";
import { readRayAccountOrders, resetRayOrderPolling } from "@/runtime/orderPolling/ray";
import { rayMonitoring, resetRayMonitoring, setRayMonitoring } from "./state";
import { useAccountStore } from "@/stores/accountStore";
import { useOrderStore } from "@/stores/orderStore";
import { useUserStore } from "@/stores/userStore";
import { loadRayMonitorOrders } from "./api";
import { rayClientStatus, updateRayOrdersLocally } from "./localOrders";
import { bindRayOrderContexts, observeRayOrderContexts, resumeRayContextMakeup } from "./contexts";
import { useRayOrderContextStore } from "./contextStore";

import { startRaySubmissionPreviewPolling, stopRaySubmissionPreviewPolling } from "./submissionPreviewPolling";

export const RAY_ORDER_POLL_MS = 5000;
export const RAY_ORDER_RECOVERY_MS = 60_000;
const tasks = new Map<string, OrderRow>();
const finished = new Set<string>();
const polling = new Map<number, Promise<void>>();
const recovering = new Map<number, Promise<void>>();
const recoveredAt = new Map<number, number>();
const polledAt = new Map<number, number>();
let owner = "";
let generation = 0;
let timer: ReturnType<typeof setTimeout> | undefined;
const key = (row: OrderRow) => `${row.PlayerID}:${row.OrderID}`;
const terminal = (status: unknown) => ["win", "lose", "lost", "return", "reject"].includes(String(status).toLowerCase());
const storageKey = () => `changmen:ray-order-monitor:v1:${owner}`;

function persist(): void {
  try { sessionStorage.setItem(storageKey(), JSON.stringify([...tasks.values()])); }
  catch { /* 数据库仍保留原单，下次恢复继续监控。 */ }
}
function register(row: OrderRow): void {
  if (!row || row.Type !== "RAY" || !row.PlayerID || !String(row.OrderID ?? "").trim() || row.DisplayOnly)
    return;
  const id = key(row);
  if (terminal(row.Status)) {
    tasks.delete(id); finished.add(id);
    const state = rayMonitoring.orders.get(id);
    if (state?.phase !== "closed" || String(state.status).toLowerCase() !== String(row.Status).toLowerCase())
      setRayMonitoring(owner, row.PlayerID, String(row.OrderID), { phase: "closed", status: String(row.Status) });
  }
  else if (!finished.has(id)) {
    const previous = tasks.get(id);
    tasks.set(id, { ...previous, ...row, Status: previous?.Status ?? row.Status });
    if (!rayMonitoring.orders.has(id))
      setRayMonitoring(owner, row.PlayerID, String(row.OrderID), { phase: "watching", status: String(row.Status) });
  }
}
/** 同一会话跨日期保留任务；不把陈旧侧栏快照重新登记为未结算。 */
export function recoverRaySettlement(): void {
  const current = String(useUserStore().userId || "");
  if (!current || useUserStore().isLoggedIn === false || useAccountStore().adminWorkspacePreview)
    return;
  if (owner !== current) {
    clearRuntime(); owner = current;
    try {
      const stored: unknown = JSON.parse(sessionStorage.getItem(storageKey())
        || sessionStorage.getItem(`changmen:ray-settlement:v1:${owner}`) || "[]");
      if (Array.isArray(stored)) {
        for (const row of stored)
          register(row);
      }
    }
    catch { /* 损坏的会话缓存不阻止数据库恢复。 */ }
  }
  const contexts = useRayOrderContextStore(); contexts.restore(current);
  for (const row of [...useOrderStore().orders.values()].flat())
    register(row);
  for (const task of contexts.activeTasks) {
    if (task.boundOrderId && (task.monitorBound || task.bindingSaved) && !tasks.has(`${task.accountId}:${task.boundOrderId}`))
      register({ Type: "RAY", PlayerID: task.accountId, OrderID: task.boundOrderId, Link: task.linkId, Status: "None" });
  }
  persist();
}
function capture(account: PlatformAccount): () => boolean {
  const stamp = generation; const session = getAuthSessionVersion(); const currentOwner = owner;
  const binding = JSON.stringify([account.gateway, account.token, account.currency]);
  return () => stamp === generation && owner === currentOwner
    && String(useUserStore().userId || "") === currentOwner && isAuthSessionCurrent(session)
    && useUserStore().isLoggedIn !== false
    && !useAccountStore().adminWorkspacePreview && useAccountStore().findAccount(account.accountId) === account
    && binding === JSON.stringify([account.gateway, account.token, account.currency]);
}
function recoverAccount(account: PlatformAccount): void {
  const id = account.accountId;
  if (recovering.has(id) || (recoveredAt.has(id) && Date.now() - recoveredAt.get(id)! < RAY_ORDER_RECOVERY_MS))
    return;
  const current = capture(account);
  const ids = [...tasks.values()].filter(row => row.PlayerID === id).map(row => String(row.OrderID));
  const task = loadRayMonitorOrders(id, ids).then((rows) => {
    if (!current())
      return;
    for (const row of rows) {
      if (row.PlayerID === id) {
        register(row);
        for (const context of useRayOrderContextStore().activeTasks) {
          if (context.accountId === id && context.boundOrderId === String(row.OrderID) && context.linkId === row.Link)
            useRayOrderContextStore().patch(context.key, { bindingSaved: true });
        }
      }
    }
    observeRayOrderContexts(id, rows.filter(row => row.PlayerID === id && terminal(row.Status)).map(row => ({
      orderId: String(row.OrderID), status: String(row.Status).toLowerCase().replace("lost", "lose") as VenueOrder["status"],
    })), current);
    recoveredAt.set(id, Date.now()); persist();
    pollAccount(account);
  }).catch((error) => {
    if (current())
      reportError(id, error);
  }).finally(() => {
    if (recovering.get(id) === task)
      recovering.delete(id);
  });
  recovering.set(id, task);
}
function reportError(player: number, error: unknown): void {
  for (const row of tasks.values()) {
    if (row.PlayerID === player)
      setRayMonitoring(owner, player, String(row.OrderID), { phase: "watching", status: String(row.Status), error: error instanceof Error ? error.message : String(error) });
  }
}
function pollAccount(account: PlatformAccount): void {
  const player = account.accountId;
  // 原下注确认窗口仍使用自己的查单；后台查询不能覆盖在途确认结果。
  if (polling.has(player) || account.active || (polledAt.has(player) && Date.now() - polledAt.get(player)! < RAY_ORDER_POLL_MS))
    return;
  const originals = new Set([...tasks.values()].filter(row => row.PlayerID === player).map(key));
  if (!originals.size && !useRayOrderContextStore().activeTasks.some(task => task.accountId === player))
    return;
  polledAt.set(player, Date.now());
  const current = capture(account);
  const task = (async () => {
    const orders = await readRayAccountOrders(account);
    if (!current() || account.active)
      return;
    recoverRaySettlement();
    bindRayOrderContexts(account, orders, () => current() && !account.active);
    for (const context of useRayOrderContextStore().activeTasks) {
      if (context.accountId !== player || !context.boundOrderId || !context.monitorBound)
        continue;
      const id = `${player}:${context.boundOrderId}`;
      const known = tasks.get(id);
      // 保留原 Link 冲突保护：监控不能把其他套利组的原单交给本组补单。
      if (known?.Link && known.Link !== context.linkId && known.Link !== known.CreateAt && known.Link !== Number(known.CreateAt) - 1) {
        useRayOrderContextStore().patch(context.key, { monitorBound: false, bindingSaved: false, lastError: "场馆原单已属于其他 Link，未自动改绑" });
        continue;
      }
      register({ ...known, Type: "RAY", PlayerID: player, OrderID: context.boundOrderId, Link: context.linkId, Status: "None" });
      originals.add(id);
    }
    // GTC 等客户端消费者可能先更新侧栏为终态；拒单事件仍由本轮唯一场馆事实触发。
    const contextOrders = orders.filter(order => order.provider === "RAY"
      && useRayOrderContextStore().activeTasks.some(context => context.accountId === player
        && context.monitorBound && context.boundOrderId === order.orderId));
    const matched = orders.filter(order => order.provider === "RAY" && originals.has(`${player}:${order.orderId}`) && tasks.has(`${player}:${order.orderId}`));
    const seen = new Set(matched.map(order => `${player}:${order.orderId}`));
    for (const id of originals) {
      const row = tasks.get(id);
      if (row && !seen.has(id))
        setRayMonitoring(owner, player, String(row.OrderID), { phase: "watching", status: String(row.Status), error: "场馆本次未返回该原单，继续查询" });
    }
    updateRayOrdersLocally(player, matched);
    for (const order of matched) {
      const id = `${player}:${order.orderId}`;
      const row = tasks.get(id);
      if (!row)
        continue;
      row.Status = rayClientStatus(order.status);
      setRayMonitoring(owner, player, order.orderId, { phase: terminal(order.status) ? "closed" : "watching", status: order.status });
      if (terminal(order.status)) { tasks.delete(id); finished.add(id); }
    }
    persist();
    observeRayOrderContexts(player, contextOrders, current);
  })().catch((error) => {
    if (current() && !account.active)
      reportError(player, error);
  }).finally(() => {
    if (polling.get(player) === task)
      polling.delete(player);
  });
  polling.set(player, task);
}
export function pollRaySettlement(): void {
  if (!useUserStore().userId || useUserStore().isLoggedIn === false || useAccountStore().adminWorkspacePreview)
    return;
  recoverRaySettlement();
  const stamp = generation; const currentOwner = owner; const session = getAuthSessionVersion();
  resumeRayContextMakeup(() => stamp === generation && owner === currentOwner
    && String(useUserStore().userId || "") === currentOwner && useUserStore().isLoggedIn !== false
    && isAuthSessionCurrent(session) && !useAccountStore().adminWorkspacePreview);
  for (const account of useAccountStore().accounts) {
    if (account.provider !== "RAY")
      continue;
    recoverAccount(account);
    pollAccount(account);
  }
}
function clearRuntime(): void {
  generation++; tasks.clear(); finished.clear(); polling.clear(); recovering.clear(); recoveredAt.clear(); polledAt.clear();
}
export function stopRaySettlement(): void { clearRuntime(); owner = ""; }
export function startRayOrderMonitoring(): void {
  if (timer)
    return;
  recoverRaySettlement();
  startRaySubmissionPreviewPolling();
  const stamp = generation;
  const tick = () => {
    if (stamp !== generation)
      return;
    pollRaySettlement();
    timer = setTimeout(tick, RAY_ORDER_POLL_MS);
  };
  tick();
}
export function stopRayOrderMonitoring(): void {
  clearTimeout(timer); timer = undefined;
  stopRaySubmissionPreviewPolling();
  stopRaySettlement(); resetRayOrderPolling(); resetRayMonitoring();
}

/** [changmen 扩展] RAY 提交后的只读订单预览；不保存、绑单或参与拒单/补单判定。 */
import type { BetOption } from "@changmen/client-core/models/betOption";
import type { BetResult } from "@changmen/client-core/models/betResult";
import type { PlatformAccount } from "@changmen/client-core/models/platformAccount";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { OrderRow } from "@/types/order";
import type { RayOrderContext } from "./types";
import { shallowReactive } from "vue";
import { getAuthSessionVersion, isAuthSessionCurrent } from "@/api/client";
import { useUserStore } from "@/stores/userStore";
import { useAccountStore } from "@/stores/accountStore";
import { useOrderStore } from "@/stores/orderStore";
import { observedRayOrders } from "@/runtime/orderMonitoring/rayOrders";
import { toOrderDateKeyLocal } from "@/shared/orderLink";
import { matchRayVenueOrder } from "./match";

interface Preview {
  account: PlatformAccount;
  current: () => boolean;
  acceptedAt: number;
  task: RayOrderContext;
  matchId: string;
  itemId: string;
  previousIds: Set<string>;
  order?: VenueOrder;
}
const previews = shallowReactive(new Map<string, Preview>());
let generation = 0;
let wake: ((account: PlatformAccount) => void) | undefined;
const binding = (account: PlatformAccount) => JSON.stringify([account.gateway, account.token, account.currency]);

export function setRaySubmissionPreviewWake(callback?: (account: PlatformAccount) => void): void { wake = callback; }
export function resetRaySubmissionPreviews(): void { generation++; previews.clear(); wake = undefined; }

/** 捕获提交前身份；成功回执只登记任务，不等待查询，不修改 option/result。 */
export function beginRaySubmissionPreview(account: PlatformAccount, option: BetOption): ((result: BetResult) => void) | undefined {
  const user = useUserStore();
  const accounts = useAccountStore();
  const owner = String(user.userId || "");
  const linkId = Number(option.diagnosticLinkId);
  if (account.provider !== "RAY" || !owner || user.isLoggedIn === false || accounts.adminWorkspacePreview
    || !linkId || !account.accountId || option.loseOrder)
    return;
  const session = getAuthSessionVersion();
  const stamp = generation;
  const credentials = binding(account);
  const current = () => generation === stamp && isAuthSessionCurrent(session) && String(user.userId || "") === owner
    && user.isLoggedIn !== false && !accounts.adminWorkspacePreview
    && accounts.findAccount(account.accountId) === account && binding(account) === credentials;
  const submittedAt = Date.now();
  const previousIds = new Set(observedRayOrders(account)?.orders.map(order => order.orderId) ?? []);
  for (const rows of useOrderStore().orders.values()) {
    for (const row of rows) {
      if (row.Type === "RAY" && row.PlayerID === account.accountId && row.OrderID != null)
        previousIds.add(String(row.OrderID));
    }
  }
  const task: RayOrderContext = {
    key: `${owner}:${linkId}:${account.accountId}:${option.itemId}`, userId: owner, linkId,
    accountId: account.accountId, matchId: Number(option.matchId) || 0, betId: Number(option.betId) || 0,
    side: option.orderIndex === 2 ? "B" : "A", submittedAt,
    match: String(option.match?.title || ""), bet: String(option.bet?.getBetName() || ""),
    item: String(option.target === "Home" ? option.bet?.homeName || "" : option.bet?.awayName || ""),
    target: option.target, odds: Number(option.odds) || 0, betMoney: Math.round(Number(option.betMoney) || 0),
    anchorConfirmed: false, anchorProvider: "", anchorAccountId: 0, anchorBetMoney: 0, anchorOdds: 0,
    status: "binding", candidateCount: 0, pollCount: 0, updatedAt: submittedAt,
  };
  const matchId = String(option.matchId ?? "");
  const itemId = String(option.itemId ?? "");
  return (result) => {
    if (!result.success || !current())
      return;
    previews.set(task.key, { account, current, task, matchId, itemId, previousIds, acceptedAt: Date.now() });
    // 不把网络请求或观察异常传回下注调用。
    void Promise.resolve().then(() => { if (current()) wake?.(account); }).catch(() => {});
  };
}

export function pendingRaySubmissionPreviewAccounts(): PlatformAccount[] {
  return [...new Set([...previews.values()].filter(preview => !preview.order && preview.current()).map(preview => preview.account))];
}

export function retireRaySubmissionPreviews(rows: readonly OrderRow[]): void {
  const known = new Set(rows.filter(row => row.Type === "RAY" && !row.DisplayOnly).map(row => `${row.PlayerID}:${row.OrderID}`));
  for (const [key, preview] of previews) {
    if (!preview.current() || (preview.order && known.has(`${preview.account.accountId}:${preview.order.orderId}`)))
      previews.delete(key);
  }
}

function sameText(left: string, right: string): boolean {
  const normalize = (value: string) => value.replace(/[^\p{L}\p{N}]/gu, "").toLowerCase();
  const a = normalize(left), b = normalize(right);
  return Boolean(a && b && (a === b || a.includes(b) || b.includes(a)));
}

export function observeRaySubmissionPreviews(account: PlatformAccount, orders: readonly VenueOrder[], startedAt: number): void {
  const owned = [...previews.values()].filter(preview => preview.account === account && preview.current());
  const claimed = new Set(owned.map(preview => preview.order?.orderId).filter(Boolean));
  for (const preview of owned) {
    if (preview.order || startedAt < preview.acceptedAt)
      continue;
    const candidates = orders.filter(order => !claimed.has(order.orderId) && !preview.previousIds.has(order.orderId)
      && order.createAt >= preview.task.submittedAt - 1000
      && (order.venueItemId ? order.venueItemId === preview.itemId : sameText(preview.task.item, order.item))
      && (order.venueMatchId ? order.venueMatchId === preview.matchId : sameText(preview.task.match, order.match)));
    const matched = matchRayVenueOrder(preview.task, candidates);
    if (matched.kind === "matched") {
      claimed.add(matched.candidate.order.orderId);
      previews.set(preview.task.key, { ...preview, order: { ...matched.candidate.order } });
    }
  }
}

/** 纯展示投影；正式订单同账号同单号出现后自动替代预览，统计及业务 store 不变。 */
export function projectRaySubmissionPreviews(
  entries: ReadonlyArray<readonly [number, OrderRow[]]>, date: string, accountId: number,
): ReadonlyArray<readonly [number, OrderRow[]]> {
  const result = new Map(entries.map(([link, rows]) => [link, [...rows]]));
  let added = false;
  const known = new Set(entries.flatMap(([, rows]) => rows.filter(row => row.Type === "RAY")
    .map(row => `${row.PlayerID}:${row.OrderID}`)));
  for (const preview of previews.values()) {
    const { account, task, order } = preview;
    if (!preview.current() || !order || known.has(`${account.accountId}:${order.orderId}`)
      || (accountId && account.accountId !== accountId) || toOrderDateKeyLocal(task.linkId) !== date)
      continue;
    const rows = result.get(task.linkId) ?? [];
    rows.push({ DisplayOnly: true, Type: "RAY", PlayerID: account.accountId, OrderID: order.orderId, Link: task.linkId,
      Match: order.match, Bet: order.bet, Item: order.item, Odds: order.odds, BetMoney: order.betMoney,
      Money: order.money, CreateAt: order.createAt, Status: "RayConfirming",
      Player: { Platform: account.platformName || "RAY", UserName: account.playerName } });
    result.set(task.linkId, rows);
    added = true;
  }
  return added ? [...result].sort(([a], [b]) => b - a) : entries;
}

import type { ObservationContext } from "@changmen/shared/order_observation";
import type { VenueOrder, VenueOrderStatus } from "@changmen/venue-adapter/contract";

export type RayOrderSide = "A" | "B";

export type RayOrderContextStatus
  = | "binding"
    | "watching"
    | "ambiguous"
    | "rejected"
    | "closed";

export type RayLateRejectMakeupStatus
  = | "disabled"
    | "enqueuing"
    | "enqueued"
    | "skipped"
    | "failed";

export interface RayOrderContext {
  observation?: ObservationContext;
  key: string;
  userId: string;
  linkId: number;
  matchId: number;
  betId: number;
  side: RayOrderSide;
  accountId: number;
  submittedAt: number;
  match: string;
  bet: string;
  item: string;
  target: "Home" | "Away";
