/**
 * 本机 PM 钱包会话：解锁后内存持钥；logout / 关页清空
 */

import { reactive, ref } from "vue";
import { getAuthSessionVersion, isAuthSessionCurrent } from "@/lib/authSession";
import { preparePolymarketAccountRuntimes } from "@changmen/venue-adapter/polymarket";
import type { PlatformAccount } from "@/models/platformAccount";
import { isPolymarketProvider, isVaultKeyProvider, tokenWalletAddress } from "./tokenStrip";
import { clearRetainedPmMemory, getRetainedPmSessionEpoch, getRetainedPmPrivateKey, prepareRetainedPmSession, registerRetainedPmCleanup, removeRetainedPmAccount, restoreRetainedPmSession, revokeRetainedPmSession, saveRetainedPmSession } from "./retainedPmSession";
import {
  base64ToBytes,
  bytesToBase64,
  createVerifier,
  decryptUtf8,
  deriveKek,
  encryptUtf8,
  randomBytes,
  verifyKek,
} from "./crypto";
import {
  defaultMetaIterations,
  defaultMetaVersion,
  getVaultKey,
  getVaultMeta,
  hasVault,
  listVaultKeys,
  putVaultKey,
  putVaultMeta,
  replaceVaultPasswordAtomic,
  vaultKeyId,
  type PmVaultMetaRecord,
} from "./store";

export interface PmVaultUiState {
  /** 需要弹出解锁框 */
  needUnlock: boolean;
  /** 需要首次设密 */
  needSetup: boolean;
  userId: string;
  busy: boolean;
  error: string;
}

export const pmVaultUi = reactive<PmVaultUiState>({
  needUnlock: false,
  needSetup: false,
  userId: "",
  busy: false,
  error: "",
});

type UnlockWaiter = {
  resolve: (ok: boolean) => void;
};

let unlockWaiter: UnlockWaiter | null = null;
let setupWaiter: UnlockWaiter | null = null;
/** 并发 ensureUnlock 共用同一个 Promise，避免 waiter 被覆盖 */
let unlockInFlight: Promise<boolean> | null = null;
let setupInFlight: Promise<boolean> | null = null;
/** lock 递增；异步 unlock/setup 完成后若 epoch 已变则丢弃 session */
let sessionEpoch = 0;

interface SessionState {
  userId: string;
  kek: CryptoKey;
  plainByAccountId: Map<number, string>;
  plainByWalletAddress: Map<string, string>;
  walletByAccountId: Map<number, string>;
  unlockedAt: number;
}

let session: SessionState | null = null;
registerRetainedPmCleanup((ids, wallets) => {
  for (const id of ids) {
    session?.plainByAccountId.delete(id);
    session?.walletByAccountId.delete(id);
  }
  for (const wallet of wallets) session?.plainByWalletAddress.delete(wallet);
  notifyPmVaultSessionChanged();
});

/** 供 Vue 订阅 session 变更（session 本身非响应式） */
export const pmVaultSessionRev = ref(0);

function notifyPmVaultSessionChanged(): void {
  pmVaultSessionRev.value += 1;
  void import("./accountUiStatus").then((m) => {
    m.touchPmVaultAccountUiSession(session?.userId);
    void m.refreshPmVaultAccountUiFromStore();
  });
}

/** 规范化 vault 用的 userId；未登录返回空串 */
export function normalizePmVaultUserId(userId: unknown): string {
  if (userId == null)
    return "";
  const s = String(userId).trim();
  if (!s || s === "0")
    return "";
  return s;
}

export function isPmVaultUnlocked(userId?: string): boolean {
  if (!session)
    return false;
  if (userId != null && session.userId !== String(userId))
    return false;
  return true;
}

export function getPmVaultSessionUserId(): string | null {
  return session?.userId ?? null;
}

export function lockPmVault(options: { preservePmSession?: boolean } = {}): void {
  const uid = session?.userId;
  if (options.preservePmSession) clearRetainedPmMemory();
  else void revokeRetainedPmSession(uid);
  sessionEpoch += 1;
  session = null;
  pmVaultUi.needUnlock = false;
  pmVaultUi.needSetup = false;
  pmVaultUi.error = "";
  pmVaultUi.busy = false;
  unlockInFlight = null;
  setupInFlight = null;
  if (unlockWaiter) {
    unlockWaiter.resolve(false);
    unlockWaiter = null;
  }
  if (setupWaiter) {
    setupWaiter.resolve(false);
    setupWaiter = null;
  }
  notifyPmVaultSessionChanged();
}

function normalizeVaultWalletAddress(walletAddress?: string): string {
  const s = String(walletAddress || "").trim().toLowerCase();
  return /^0x[0-9a-f]{40}$/.test(s) ? s : "";
}

export function getCachedPrivateKey(accountId: number, walletAddress?: string): string | undefined {
  const retained = getRetainedPmPrivateKey(accountId, session?.userId, walletAddress);
  if (retained) return retained;
  const byId = session?.plainByAccountId.get(Number(accountId));
  const boundWallet = session?.walletByAccountId.get(Number(accountId));
  if (walletAddress !== undefined && boundWallet && normalizeVaultWalletAddress(walletAddress) !== boundWallet)
    return undefined;
  if (byId)
    return byId;
  const wallet = normalizeVaultWalletAddress(walletAddress);
  return wallet ? session?.plainByWalletAddress.get(wallet) : undefined;
}

async function loadAllKeysIntoSession(kek: CryptoKey, userId: string): Promise<Pick<SessionState, "plainByAccountId" | "plainByWalletAddress" | "walletByAccountId">> {
  const byAccountId = new Map<number, string>();
  const byWalletAddress = new Map<string, string>();
  const walletByAccountId = new Map<number, string>();
  const rows = await listVaultKeys(userId);
  for (const row of rows) {
    try {
      const pk = await decryptUtf8(kek, row.cipher);
      byAccountId.set(Number(row.accountId), pk);
      const wallet = normalizeVaultWalletAddress(row.walletAddress);
      if (wallet) {
        byWalletAddress.set(wallet, pk);
        walletByAccountId.set(Number(row.accountId), wallet);
      }
    }
    catch {
      /* skip corrupt entry */
    }
  }
  return { plainByAccountId: byAccountId, plainByWalletAddress: byWalletAddress, walletByAccountId };
}

export async function setupPmVault(userId: string, password: string): Promise<void> {
  const uid = normalizePmVaultUserId(userId);
  if (!uid)
    throw new Error("缺少 userId");
  if (password.length < 8)
    throw new Error("本机钱包密码至少 8 位");
  if (await hasVault(uid))
    throw new Error("本机钱包已存在，请解锁而非重新设置");

  const epoch = sessionEpoch;
  const salt = randomBytes(16);
  await prepareRetainedPmSession(uid);
  const kek = await deriveKek(password, salt, defaultMetaIterations());
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  const verifier = await createVerifier(kek);
  const now = Date.now();
  const meta: PmVaultMetaRecord = {
    userId: uid,
    version: defaultMetaVersion(),
    saltB64: bytesToBase64(salt),
    kdf: "PBKDF2",
    iterations: defaultMetaIterations(),
    hash: "SHA-256",
    verifier,
    createdAt: now,
    updatedAt: now,
  };
  await putVaultMeta(meta);
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  session = {
    userId: uid,
    kek,
    plainByAccountId: new Map(),
    plainByWalletAddress: new Map(),
    walletByAccountId: new Map(),
    unlockedAt: now,
  };
  notifyPmVaultSessionChanged();
}

export async function unlockPmVault(userId: string, password: string): Promise<void> {
  const uid = normalizePmVaultUserId(userId);
  const epoch = sessionEpoch;
  await prepareRetainedPmSession(uid);
  const meta = await getVaultMeta(uid);
  if (!meta)
    throw new Error("本机尚未设置钱包密码");
  const saltBytes = base64ToBytes(meta.saltB64);
  const kek = await deriveKek(password, saltBytes, meta.iterations || defaultMetaIterations());
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  const ok = await verifyKek(kek, meta.verifier);
  if (!ok)
    throw new Error("本机钱包密码错误");
  const plain = await loadAllKeysIntoSession(kek, uid);
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  session = {
    userId: uid,
    kek,
    plainByAccountId: plain.plainByAccountId,
    plainByWalletAddress: plain.plainByWalletAddress,
    walletByAccountId: plain.walletByAccountId,
    unlockedAt: Date.now(),
  };
  notifyPmVaultSessionChanged();
}

export async function changePmVaultPassword(
  userId: string,
  oldPassword: string,
  newPassword: string,
): Promise<void> {
  await revokeRetainedPmSession(userId);
  await unlockPmVault(userId, oldPassword);
  if (newPassword.length < 8)
    throw new Error("新密码至少 8 位");
  const uid = normalizePmVaultUserId(userId);
  // 必须在任意后续 await 前快照：lock 竞态下 session 可能被清空
  if (!session || session.userId !== uid)
    throw new Error("本机钱包已锁定");
  const epoch = sessionEpoch;
  const entries = [...session.plainByAccountId.entries()];
  const existingBefore = await listVaultKeys(uid);
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  // 仓里本有钥，却读到空明文 → 说明解锁后被 lock，禁止用空列表覆盖
  if (existingBefore.length > 0 && entries.length === 0)
    throw new Error("本机钱包已锁定，改密已取消");
  const createdAt = (await getVaultMeta(uid))?.createdAt ?? Date.now();
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  const salt = randomBytes(16);
  const kek = await deriveKek(newPassword, salt, defaultMetaIterations());
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  const verifier = await createVerifier(kek);
  const now = Date.now();
  const keyRecords = [];
  for (const [accountId, pk] of entries) {
    const cipher = await encryptUtf8(kek, pk);
    const existing = existingBefore.find(row => Number(row.accountId) === Number(accountId));
    keyRecords.push({
      id: vaultKeyId(uid, accountId),
      userId: uid,
      accountId,
      walletAddress: existing?.walletAddress,
      cipher,
      updatedAt: now,
    });
  }
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  if (existingBefore.length > 0 && keyRecords.length === 0)
    throw new Error("本机钱包已锁定，改密已取消");
  await replaceVaultPasswordAtomic({
    userId: uid,
    version: defaultMetaVersion(),
    saltB64: bytesToBase64(salt),
    kdf: "PBKDF2",
    iterations: defaultMetaIterations(),
    hash: "SHA-256",
    verifier,
    createdAt,
    updatedAt: now,
  }, keyRecords);
  if (epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  session = {
    userId: uid,
    kek,
    plainByAccountId: new Map(entries),
    walletByAccountId: new Map(existingBefore.flatMap(row => {
      const wallet = normalizeVaultWalletAddress(row.walletAddress);
      return wallet ? [[Number(row.accountId), wallet] as const] : [];
    })),
    plainByWalletAddress: new Map(existingBefore
      .map((row) => {
        const wallet = normalizeVaultWalletAddress(row.walletAddress);
        const pk = entries.find(([accountId]) => Number(accountId) === Number(row.accountId))?.[1] || "";
        return wallet && pk ? [wallet, pk] as const : null;
      })
      .filter((row): row is readonly [string, string] => Boolean(row))),
    unlockedAt: now,
  };
  notifyPmVaultSessionChanged();
}

export async function putPrivateKeyInVault(
  userId: string,
  accountId: number,
  privateKey: string,
  walletAddress?: string,
): Promise<void> {
  const uid = normalizePmVaultUserId(userId);
  if (!session || session.userId !== uid)
    throw new Error("请先解锁本机钱包");
  const pk = privateKey.trim();
  if (!pk)
    throw new Error("私钥为空");
  const id = Number(accountId);
  if (!id)
    throw new Error("缺少 accountId");
  const epoch = sessionEpoch;
  const oldKey = getCachedPrivateKey(id);
  if (oldKey && oldKey !== pk) await removeRetainedPmAccount(uid, id);
  if (!session || session.userId !== uid || epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  const cipher = await encryptUtf8(session.kek, pk);
  await putVaultKey({
    id: vaultKeyId(uid, id),
    userId: uid,
    accountId: id,
    walletAddress: walletAddress?.trim() || undefined,
    cipher,
    updatedAt: Date.now(),
  });
  if (!session || session.userId !== uid || epoch !== sessionEpoch)
    throw new Error("本机钱包已锁定");
  session.plainByAccountId.set(id, pk);
  const wallet = normalizeVaultWalletAddress(walletAddress);
  session.walletByAccountId.delete(id);
  if (wallet) session.walletByAccountId.set(id, wallet);
  if (wallet)
    session.plainByWalletAddress.set(wallet, pk);
  notifyPmVaultSessionChanged();
  void syncUnlockedKeysIntoAccountStore();
}

/** [changmen 扩展] PM 恢复不伪装为共享 vault 完整解锁，导入/改密仍需密码。 */
export async function ensurePmVaultForAccounts(userId: string, accounts: PlatformAccount[]): Promise<boolean> {
  const epoch = sessionEpoch;
  const authVersion = getAuthSessionVersion();
  const current = () => epoch === sessionEpoch && isAuthSessionCurrent(authVersion);
  try { await restoreRetainedPmSession(accounts, userId); } catch { /* password fallback */ }
  const ids = new Set((await listVaultKeys(userId)).map(row => Number(row.accountId)));
  if (!current()) return false;
  const required = accounts.filter(a => isVaultKeyProvider(a.provider) && ids.has(Number(a.accountId)));
  const hasKey = (account: PlatformAccount) => Boolean(getCachedPrivateKey(account.accountId, tokenWalletAddress(account.token)));
  const finish = async () => current() && await syncUnlockedKeysIntoAccountStore(userId) && current() && required.every(hasKey);
  if (isPmVaultUnlocked(userId) && required.every(hasKey)) return finish();
  if (required.length && required.every(a => isPolymarketProvider(a.provider) && getRetainedPmPrivateKey(a.accountId, userId, tokenWalletAddress(a.token)))) {
    return finish();
  }
  const unlocked = await ensurePmVaultUnlocked(userId, { force: isPmVaultUnlocked(userId) && required.some(a => !hasKey(a)) });
  // A correct vault password cannot make an old wallet's key valid for a new address.
  if (!unlocked || !current() || !required.every(hasKey)) return false;
  return finish();
}

export async function vaultHasKey(userId: string, accountId: number): Promise<boolean> {
  const uid = normalizePmVaultUserId(userId);
  if (session?.userId === uid && session.plainByAccountId.has(Number(accountId)))
    return true;
  return Boolean(await getVaultKey(uid, accountId));
}

/**
 * 需要解锁时弹出 UI；无 vault 则直接 true（尚无私钥仓）。
 * 用户取消解锁返回 false。
 */
export async function ensurePmVaultUnlocked(userId: string, options: { force?: boolean } = {}): Promise<boolean> {
  const uid = normalizePmVaultUserId(userId);
  if (!uid)
    return true;
  if (isPmVaultUnlocked(uid) && !options.force)
    return true;
  if (!(await hasVault(uid)))
    return true;
  if (unlockInFlight)
    return unlockInFlight;
  pmVaultUi.userId = uid;
  pmVaultUi.error = "";
  pmVaultUi.needUnlock = true;
  unlockInFlight = new Promise<boolean>((resolve) => {
    unlockWaiter = {
      resolve: (ok) => {
        unlockInFlight = null;
        resolve(ok);
      },
    };
  });
  return unlockInFlight;
}

/** 首次设密：弹出设密框，成功后 session 已解锁 */
export async function ensurePmVaultSetup(userId: string): Promise<boolean> {
  const uid = normalizePmVaultUserId(userId);
  if (!uid)
    return false;
  if (await hasVault(uid))
    return ensurePmVaultUnlocked(uid);
  if (isPmVaultUnlocked(uid))
    return true;
  if (setupInFlight)
    return setupInFlight;
  pmVaultUi.userId = uid;
  pmVaultUi.error = "";
  pmVaultUi.needSetup = true;
  setupInFlight = new Promise<boolean>((resolve) => {
    setupWaiter = {
      resolve: (ok) => {
        setupInFlight = null;
        resolve(ok);
      },
    };
  });
  return setupInFlight;
}

/** 解锁成功后把本机钥合并进账号内存（供自动下注） */
export async function syncUnlockedKeysIntoAccountStore(userId?: string): Promise<boolean> {
  const epoch = sessionEpoch;
  const retainedEpoch = getRetainedPmSessionEpoch();
  const authVersion = getAuthSessionVersion();
  const uid = userId ?? session?.userId;
  const current = () => epoch === sessionEpoch && retainedEpoch === getRetainedPmSessionEpoch()
    && isAuthSessionCurrent(authVersion) && (!session || session.userId === uid);
  if (!uid) return false;
  try {
    const { useAccountStore } = await import("@/stores/accountStore");
    const { mergeVaultKeysIntoAccounts, migrateTokenPrivateKeysToVault } = await import("./accounts");
    if (!current()) return false;
    const store = useAccountStore();
    const accounts = store.accounts;
    if (!accounts.length) return true;
    mergeVaultKeysIntoAccounts(accounts, uid);
    if (!current()) return false;
    const migrated = await migrateTokenPrivateKeysToVault(accounts, uid);
    if (!current() || store.accounts !== accounts) return false;
    await preparePolymarketAccountRuntimes(accounts);
    if (!current() || store.accounts !== accounts) return false;
    if (migrated > 0)
      void store.saveAccounts();
    void saveRetainedPmSession(accounts, uid);
    return true;
  }
  catch {
    /* store 未就绪时忽略 */
    return false;
  }
}

export function completePmVaultUnlock(ok: boolean): void {
  // 忙碌中拒绝取消，防止 KDF 完成后 session 已解锁却被判失败
  if (!ok && pmVaultUi.busy)
    return;
  pmVaultUi.needUnlock = false;
  pmVaultUi.error = "";
  const w = unlockWaiter;
  unlockWaiter = null;
  const success = ok && isPmVaultUnlocked(pmVaultUi.userId);
  if (success)
    void syncUnlockedKeysIntoAccountStore();
  pmVaultSessionRev.value += 1;
  void import("./accountUiStatus").then(m => m.refreshPmVaultAccountUiFromStore());
  w?.resolve(success);
}

export function completePmVaultSetup(ok: boolean): void {
  if (!ok && pmVaultUi.busy)
    return;
  pmVaultUi.needSetup = false;
  pmVaultUi.error = "";
  const w = setupWaiter;
  setupWaiter = null;
  const success = ok && isPmVaultUnlocked(pmVaultUi.userId);
  if (success)
    void syncUnlockedKeysIntoAccountStore();
  pmVaultSessionRev.value += 1;
  void import("./accountUiStatus").then(m => m.refreshPmVaultAccountUiFromStore());
  w?.resolve(success);
}

export { hasVault };

if (typeof window !== "undefined") {
  window.addEventListener("changmen:auth-ending", () => lockPmVault());
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { BetResult } from "@changmen/client-core/models/betResult";
import type { VenueLegSettlement, VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import { saveUserLog } from "@/api/chat";
import { useAccountStore } from "@/stores/accountStore";
import { observeOption } from "./orderObservation";
import { rayRejectFailureEvidence } from "./orderObservationEvidence";
import { settlementEvidenceOrder, submissionVenueStatus } from "./venueSettlementEvidence";

function accountPlatformLabel(account: PlatformAccount): string {
  try {
    const store = useAccountStore();
    if (typeof store.getPlatformName === "function") {
      return store.getPlatformName(
        account.platformId,
        account.platformName,
      );
    }
  }
  catch {
    /* 诊断日志不能影响下注主链路 */
  }
  return account.platformName || account.provider;
}

/** [A8 可证实] bundle `Ap.saveLog` */
export function saveBetOptionLog(option: BetOption, account: PlatformAccount): void {
  const platformLabel = accountPlatformLabel(account);
  const title = `[${option.type}](${platformLabel},${account.playerName}) 请求盘口数据 => ${!!option.data} / 耗时${Date.now() - option.startTime}ms / ${option.odds}:${option.newOdds || "N/A"}`;
  void saveUserLog(title, {
    options: {
      type: option.type,
      match: option.match?.title,
      matchId: option.matchId,
      bet: option.bet?.getBetName(),
      betId: option.betId,
      target: option.target,
      itemId: option.itemId,
      odds: option.odds,
      newOdds: option.newOdds,
      betMoney: option.betMoney,
      planBetMoney: option.planBetMoney,
      stakeExchange: option.stakeExchange,
      stakeRate: option.stakeRate,
      stakeCurrency: option.stakeCurrency,
      linkId: option.diagnosticLinkId,
      attemptType: option.diagnosticAttempt,
      betCount: option.betCount,
      config: option.config,
      loseOrder: option.loseOrder,
    },
    checkError: option.checkError,
    response: option.response,
    request: option.request,
    data: option.data,
  });
}

/** [A8 可证实] bundle `uo.saveLog` */
export function saveBetResultLog(result: BetResult, account: PlatformAccount): void {
  const platformLabel = accountPlatformLabel(account);
  const title = `[${result.provider}](${platformLabel},${account.playerName}) 下注 => ${result.success} / 耗时:${Date.now() - result.beginTime}ms`;
  void saveUserLog(title, { accountId: account.accountId, result });
}

function settlementRejectReason(result: BetResult): string | null {
  const reject = result.reject;
  if (typeof reject === "string" && reject.trim() && reject !== "timeout")
    return reject.trim();
  if (reject && typeof reject === "object") {
    const row = reject as Record<string, unknown>;
    const reason = row.reason ?? row.message ?? row.error;
    if (reason != null && String(reason).trim())
      return String(reason).trim();
  }
  return null;
}

/**
 * [changmen 扩展] 记录 POST 受理后的场馆终态，供管理端准确区分即时失败与事后拒单。
 * 仅写诊断日志，不参与下注、补单或订单状态判断。
 */
export function saveVenueSettlementLog(params: {
  account: PlatformAccount;
  option: BetOption;
  result: BetResult;
  orders: VenueOrder[];
  settlement: VenueLegSettlement;
  linkId?: number;
}): void {
  // 任一日志字段异常都必须被隔离，不能改变下注/补单结果。
  try {
    const { account, option, result, orders, settlement, linkId } = params;
    let reason: string | undefined;
    try {
      const evidenceOrder = settlementEvidenceOrder(option, result, orders);
      const status = submissionVenueStatus(result);
      const mode = account.provider !== "Polymarket" || status === "delayed" || result.pmSubmitUnknown ? "reject_detection"
        : status === "matched" ? "direct_fill" : "confirmation";
      reason = evidenceOrder?.venueRejectReason;
      const reasonEvidence = settlement === "unfilled" && account.provider === "RAY" && reason
        ? rayRejectFailureEvidence(reason) : {};
      observeOption(option, account, "settlement_observed", {
        orderId: evidenceOrder?.orderId || result.orderId || undefined,
        outcome: settlement,
        source: settlement === "unfilled" && String(result.message).includes("超时策略判拒") ? "timeout_policy" : evidenceOrder ? "adapter" : "orchestration_result",
        phase: mode,
        observedStatus: evidenceOrder?.status,
        ...reasonEvidence,
      });
    }
    catch { /* 新观察异常不能跳过原有日志 */ }
    const exactOrderId = String(result.orderId ?? "").trim();
    const observedOrder = exactOrderId
      ? orders.find(order => String(order.orderId) === exactOrderId)
      : orders[0] ?? null;
    const orderId = String(observedOrder?.orderId ?? exactOrderId).trim() || null;
    const observedAt = Date.now();
    const placedAt = Number(observedOrder?.createAt || result.beginTime) || null;
    const rejectDelayMs = placedAt == null ? null : Math.max(0, observedAt - placedAt);
    const policyRejected = settlement === "unfilled" && String(result.message).includes("超时策略判拒");
    const stateLabel = settlement === "unfilled"
      ? policyRejected ? "超时策略判拒" : "确认拒单"
      : settlement === "timeout"
        ? "仍待确认"
        : "确认成交";
    const platformLabel = accountPlatformLabel(account);

    void saveUserLog(
      // [changmen 扩展] 保留管理端按“拒单”识别的历史日志格式；实时阶段由观察事件区分。
      `[${account.provider}](${platformLabel},${account.playerName}) 拒单检测 => ${stateLabel}`,
      {
        diagnosticVersion: 2,
        provider: account.provider,
        accountId: account.accountId,
        linkId: Number(linkId) || null,
        orderId,
        target: option.target,
        match: option.match?.title ?? null,
        bet: option.bet?.getBetName() ?? null,
        odds: option.newOdds || option.odds,
        betMoney: option.betMoney,
        planBetMoney: option.planBetMoney,
        stakeExchange: option.stakeExchange,
        stakeRate: option.stakeRate,
        stakeCurrency: option.stakeCurrency,
        attemptType: option.diagnosticAttempt,
        loseOrder: option.loseOrder,
        placedAt,
        observedAt,
        rejectDelayMs,
        settlement,
        settlementMessage: result.message,
        decisionBasis: policyRejected ? "timeout_policy" : null,
        observedStatus: observedOrder?.status ?? (orders.length ? "unknown" : "missing"),
        rejectReason: settlement === "unfilled" ? reason || settlementRejectReason(result) : null,
      },
    ).catch(() => {});
  }
  catch {
    /* 诊断日志不能影响下注、拒单判断或补单 */
  }
}

/** [changmen 扩展] 补单只入队但尚未真正下单，也要在诊断中留下证据。 */
export function saveMakeUpQueueLog(params: {
  linkId: number;
  target: string;
  match: string;
  bet: string;
  anchorBetMoney: number;
  anchorOdds: number;
  failedLegOdds: number;
  failedPlatformLabel: string;
}): void {
  try {
    void saveUserLog("补单入队", {
      diagnosticVersion: 2,
      attemptType: "makeup_queue",
      linkId: params.linkId,
      target: params.target,
      match: params.match,
      bet: params.bet,
      betMoney: params.anchorBetMoney,
      odds: params.anchorOdds,
      failedLegOdds: params.failedLegOdds,
      failedPlatformLabel: params.failedPlatformLabel,
      observedAt: Date.now(),
    }).catch(() => {});
  }
  catch {
    /* 诊断日志不能影响补单入队 */
  }
}

/** [changmen 扩展] 自动补单因锚腿确认拒单而撤销，持久化供管理端还原队列终态。 */
export function saveMakeUpCancelLog(params: {
  linkId: number;
  betId: number;
