import {
  PM_MAINTENANCE_CHANNEL,
  subscribeChangmenChannel,
} from "@changmen/venue-adapter/shared";
import { readonly, ref } from "vue";

/** PM 官网状态（server/realtime-hub/pm_maintenance.js 发布） */
export type PmOfficialState = "unknown" | "operational" | "maintenance" | "incident";

export interface PmMaintenancePayload {
  state?: PmOfficialState;
  pageStatus?: string;
  affected?: string[];
  checkedAt?: number;
  error?: string;
  source?: string;
}

const state = ref<PmOfficialState>("unknown");
const detail = ref<PmMaintenancePayload | null>(null);
let startPromise: Promise<() => void> | null = null;

function applyPayload(message: unknown) {
  const payload = (message ?? {}) as PmMaintenancePayload;
  const next = payload.state;
  state.value
    = next === "operational" || next === "maintenance" || next === "incident"
      ? next
      : "unknown";
  detail.value = payload;
}

/**
 * 启动 PM 官网维护状态订阅（幂等；未登录导致 hub 连不上时保持 unknown）。
 * 返回取消订阅函数。
 */
export function startPmMaintenanceFeed(): Promise<() => void> {
  if (!startPromise) {
    startPromise = subscribeChangmenChannel(PM_MAINTENANCE_CHANNEL, applyPayload);
    startPromise.catch((err) => {
      startPromise = null;
      throw err;
    });
  }
  return startPromise;
}

export function usePmMaintenance() {
  return { state: readonly(state), detail: readonly(detail) };
}

import type { PmSportSnapshot } from "@/types/esport";
import {
  PM_SPORT_CHANNEL,
  subscribeChangmenChannel,
} from "@changmen/venue-adapter/shared";

let unsub: (() => void) | null = null;

interface PmSportPushMessage {
  ClientMatchID?: number;
  PmSport?: PmSportSnapshot;
}

/** 启动 Polymarket pm_sport 实时推送（changmen Socket.IO，已服务端对齐 Reverse） */
export async function startPmSportRealtimeFeed(
  onUpdate: (clientMatchId: number, pmSport: PmSportSnapshot) => void,
): Promise<() => void> {
  if (unsub)
    return unsub;

  unsub = await subscribeChangmenChannel(PM_SPORT_CHANNEL, (msg) => {
    const row = msg as PmSportPushMessage;
    const id = Number(row?.ClientMatchID);
    const snap = row?.PmSport;
    if (!Number.isFinite(id) || !snap || typeof snap !== "object")
      return;
    onUpdate(id, snap);
  });

  return () => {
    stopPmSportRealtimeFeed();
  };
}

export function stopPmSportRealtimeFeed() {
  unsub?.();
  unsub = null;
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { BetResult } from "@changmen/client-core/models/betResult";
import type { VenueOrder } from "@changmen/venue-adapter/contract";

/** [changmen 扩展] RAY 无提交订单号时，按场馆身份、时间、金额和赔率唯一关联；不改业务判定或绑定。 */
export function settlementEvidenceOrder(option: BetOption, result: BetResult, orders: readonly VenueOrder[]): VenueOrder | undefined {
  if (result.orderId)
    return orders.find(order => String(order.orderId) === String(result.orderId));
  if (result.provider !== "RAY" || !Number.isFinite(result.beginTime) || !result.beginTime)
    return undefined;
  const matches = orders.filter(order => order.provider === "RAY" && Boolean(order.orderId)
    && order.venueMatchId === String(option.matchId) && order.venueItemId === String(option.itemId)
    && order.createAt >= result.beginTime - 10_000 && order.createAt <= result.beginTime + 120_000
    && Math.abs(order.betMoney - Math.round(option.betMoney)) < 0.01
    && Math.abs(order.odds - (option.newOdds || option.odds)) < 0.001);
  // A8 检测取首条；只有同一首条唯一匹配本次提交，才把检测结果关联成场馆证据。
  return matches.length === 1 && matches[0] === orders[0] ? matches[0] : undefined;
}

/** [changmen 扩展] 从提交结果读取阶段身份，避免 settle 修改 pending 后丢失 delayed 身份。 */
export function submissionVenueStatus(result: BetResult): string | undefined {
  if (result.provider !== "Polymarket")
    return undefined;
  const response = result.response && typeof result.response === "object" ? result.response as Record<string, unknown> : undefined;
  const status = typeof response?.status === "string" ? response.status.trim().toLowerCase() : "";
  if (status === "delayed" || result.pending)
    return "delayed";
  return result.success && status === "matched" ? "matched" : undefined;
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { PlatformAccount } from "@/models/platformAccount";
import type { ArbProgressLegMeta } from "@/stores/betting/autoBet/arbExecutionTrace";
import { buildPolymarketArbProgressMeta } from "@/domain/polymarket/arbProgressPmMeta";
import { formatLegAccount } from "@/shared/arbBetTraceFormat";
import { PLATFORMS } from "@changmen/venue-adapter/shared";

export function buildArbProgressLegMeta(
  side: ArbProgressLegMeta["side"],
  leg: BetOption,
  account?: PlatformAccount | null,
  precheck?: { ok: boolean; error?: string },
  prior?: ArbProgressLegMeta,
): ArbProgressLegMeta {
  const meta: ArbProgressLegMeta = {
    side,
    platform: leg.type,
    target: leg.target,
    odds: leg.odds,
    betMoney: leg.betMoney,
    planBetMoney: prior?.planBetMoney ?? leg.betMoney,
    planOdds: prior?.planOdds ?? leg.odds,
    account: account ? formatLegAccount(leg.type, account.playerName) : undefined,
  };
  if (!precheck)
    return meta;

  meta.precheck = {
    ok: precheck.ok,
    error: precheck.error,
  };
  if (leg.type === PLATFORMS.Polymarket) {
    meta.precheck.polymarket = buildPolymarketArbProgressMeta(leg);
  }
  return meta;
}

export function buildArbProgressLegPair(
  legA: BetOption,
  legB: BetOption,
  accountA?: PlatformAccount | null,
  accountB?: PlatformAccount | null,
  precheck?: {
    legA?: { ok: boolean; error?: string };
    legB?: { ok: boolean; error?: string };
  },
  priorLegs?: ArbProgressLegMeta[],
): ArbProgressLegMeta[] {
  const priorA = priorLegs?.find(l => l.side === "A");
  const priorB = priorLegs?.find(l => l.side === "B");
  return [
    buildArbProgressLegMeta("A", legA, accountA, precheck?.legA, priorA),
    buildArbProgressLegMeta("B", legB, accountB, precheck?.legB, priorB),
  ];
}

