async function warmPolymarketUserWsFromAccounts(accounts: PlatformAccount[]) {
  try {
    const { warmAllPolymarketUserWs } = await import("@changmen/venue-adapter/polymarket");
    warmAllPolymarketUserWs(accounts);
  }
  catch {
    /* 无扩展 / 无凭证时跳过 */
  }
}

