/**
 * [changmen 扩展] 订单栏 PM 卖出：对当前买单下 FOK，确认到终态后落库。
 * 平仓中（closing）为过渡态；出口只有已平仓 / 未成交可再卖。
 */
import { ElMessage } from "element-plus";
import { shallowRef } from "vue";
import type { PlatformAccount } from "@/models/platformAccount";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import {
  awaitPolymarketManualSellFinalOutcome,
  hasOpenPolymarketPosition,
  resolvePmRemainingShares,
  sellPolymarketBuyPosition,
} from "@changmen/venue-adapter/polymarket";
import { saveOrders, getPmSubmission } from "@/api/order";
import { validatePmSubmission } from "@changmen/shared/pm_submission";
import { groupOrdersByEffectiveLink } from "@/shared/orderLink";
import { formatPolymarketApiDecimal } from "@/shared/pmOrderDisplay";
import { useAccountStore } from "@/stores/accountStore";
import { useOrderStore } from "@/stores/orderStore";
import type { OrderRow } from "@/types/order";
import { finishPmSubmitAttempt, pmAccountSubmitAttempts, pmSubmitScope, pmSubmitMaker } from "@changmen/venue-adapter/polymarket";
import { getAuthSessionVersion, isAuthSessionCurrent } from "@/api/client";

type ClosingEntry = {
  pmScope?: string;
  accountId?: number;
  ordersToSave?: VenueOrder[];
  sellOrderId: string;
  at: number;
  fallbackPrice?: number;
  sharesWanted?: number;
};

/** 飞行中 / 确认框中：响应式，供按钮 disabled */
const sellingOrderIds = shallowRef(new Set<string>());
/** 平仓确认中：买单 → 卖单号（session 内跨刷新保留） */
const CLOSING_KEY = "pmManualSell.closing";
const closingByBuyId = shallowRef(loadClosing());
/** resume 防重入 */
let resumeInFlight = false;
let resumeTimer: ReturnType<typeof setTimeout> | null = null;

function scheduleResumePmManualSellClosings(delayMs = 5_000): void {
  if (resumeTimer)
    return;
  resumeTimer = setTimeout(() => {
    resumeTimer = null;
    void resumePmManualSellClosings();
  }, delayMs);
}

function loadClosing(): Map<string, ClosingEntry> {
  const map = new Map<string, ClosingEntry>();
  try {
    const raw = sessionStorage.getItem(CLOSING_KEY);
    if (raw) {
      const obj = JSON.parse(raw) as Record<string, ClosingEntry | string>;
      for (const [buyId, v] of Object.entries(obj)) {
        const id = String(buyId ?? "").trim();
        if (!id)
          continue;
        if (typeof v === "string") {
          const sellId = v.trim();
          if (sellId)
            map.set(id, { sellOrderId: sellId, at: Date.now() });
          continue;
        }
        const sellId = String(v?.sellOrderId ?? "").trim();
        if (sellId) {
          map.set(id, {
            sellOrderId: sellId,
            at: Number(v?.at) || Date.now(),
            fallbackPrice: Number(v?.fallbackPrice) > 0 ? Number(v.fallbackPrice) : undefined,
            sharesWanted: Number(v?.sharesWanted) > 0 ? Number(v.sharesWanted) : undefined,
            pmScope: typeof v.pmScope === "string" ? v.pmScope : undefined,
            accountId: Number(v.accountId) || undefined,
            ordersToSave: Array.isArray(v.ordersToSave) ? v.ordersToSave : undefined,
          });
        }
      }
    }
  }
  catch { /* ignore */ }

  return map;
}

function writeClosing(map: Map<string, ClosingEntry>): void {
  try {
    const obj: Record<string, ClosingEntry> = {};
    for (const [k, v] of map)
      obj[k] = v;
    sessionStorage.setItem(CLOSING_KEY, JSON.stringify(obj));
  }
  catch { /* ignore quota */ }
}

function setClosingMap(next: Map<string, ClosingEntry>): void {
  closingByBuyId.value = next;
  writeClosing(next);
}

function enterClosing(
  buyOrderId: string,
  sellOrderId: string,
  opts?: { fallbackPrice?: number; sharesWanted?: number; account?: PlatformAccount },
): void {
  const id = String(buyOrderId ?? "").trim();
  const sellId = String(sellOrderId ?? "").trim();
  if (!id)
    return;
  const next = new Map(closingByBuyId.value);
  next.set(id, {
    ...(opts?.account ? { pmScope: pmSubmitScope(opts.account), accountId: opts.account.accountId } : {}),
    sellOrderId: sellId,
    at: Date.now(),
    fallbackPrice: opts?.fallbackPrice,
    sharesWanted: opts?.sharesWanted,
  });
  setClosingMap(next);
}

function clearClosing(buyOrderId: string): void {
  const id = String(buyOrderId ?? "").trim();
  if (!id || !closingByBuyId.value.has(id))
    return;
  const sellId = closingByBuyId.value.get(id)?.sellOrderId;
  const scope = closingByBuyId.value.get(id)?.pmScope;
  if (sellId) {
    for (const account of useAccountStore().accounts ?? []) {
      if (account.provider !== "Polymarket") continue;
      try { if (!scope || pmSubmitScope(account) === scope) finishPmSubmitAttempt(account, sellId); } catch { /* 保留持久化锁 */ }
    }
  }
  const next = new Map(closingByBuyId.value);
  next.delete(id);
  setClosingMap(next);
}

function setHas(refSet: typeof sellingOrderIds, id: string): boolean {
  return refSet.value.has(id);
}

function addId(refSet: typeof sellingOrderIds, id: string): void {
  if (refSet.value.has(id))
    return;
  const next = new Set(refSet.value);
  next.add(id);
  refSet.value = next;
}

function removeId(refSet: typeof sellingOrderIds, id: string): void {
  if (!refSet.value.has(id))
    return;
  const next = new Set(refSet.value);
  next.delete(id);
  refSet.value = next;
}

function venueOrdersToLocalRows(buyRow: OrderRow, orders: VenueOrder[]): OrderRow[] {
  const playerId = Number(buyRow.PlayerID) || 0;
  const link = Number(buyRow.Link) || Number(orders.find(o => o.link)?.link) || 0;
  return orders.map((vo) => {
    if (vo.pmSide === "sell") {
      return {
        OrderID: vo.orderId,
        Link: vo.link ?? link,
        Type: "Polymarket",
        Match: vo.match,
        Bet: vo.bet,
        Item: vo.item,
        Odds: vo.odds,
        BetMoney: vo.betMoney,
        Money: vo.money,
        Status: "None",
        CreateAt: vo.createAt,
        PlayerID: playerId,
        PmTokenId: vo.pmTokenId,
        PmShares: vo.pmShares,
        PmFillPrice: vo.pmFillPrice,
        PmStakeUsdc: vo.pmStakeUsdc,
        PmConditionId: vo.pmConditionId,
        PmOrigin: vo.pmOrigin,
        PmRealizedPnlUsdc: vo.pmRealizedPnlUsdc,
        PmSide: "sell",
        PmBuyOrderId: vo.pmBuyOrderId ?? String(buyRow.OrderID ?? ""),
      } satisfies OrderRow;
    }
    return {
      ...buyRow,
      Money: vo.money,
      PmStakeUsdc: vo.pmStakeUsdc,
      PmAttributedSellShares: vo.pmAttributedSellShares,
      PmSellState: vo.pmSellState,
      PmRealizedPnlUsdc: vo.pmRealizedPnlUsdc,
      PmSellProceeds: vo.pmSellProceeds,
      PmLastSellOrderId: vo.pmLastSellOrderId,
      PmSide: "buy",
      PmOrigin: vo.pmOrigin ?? buyRow.PmOrigin,
      PositionEvents: mergePositionEventsLocal(buyRow.PositionEvents, vo.positionEvents),
    } satisfies OrderRow;
  });
}

type PositionSellEvent = NonNullable<NonNullable<OrderRow["PositionEvents"]>["sells"]>[number];

function mergePositionEventsLocal(
  prev: OrderRow["PositionEvents"] | undefined,
  incoming: VenueOrder["positionEvents"] | undefined,
): OrderRow["PositionEvents"] | undefined {
  const byId = new Map<string, PositionSellEvent>();
  for (const e of prev?.sells ?? []) {
    const id = String(e?.id ?? "").trim();
    if (!id)
      continue;
    byId.set(id.toLowerCase(), { ...e, id });
  }
  for (const e of incoming?.sells ?? []) {
    const id = String(e?.id ?? "").trim();
    if (!id)
      continue;
    const key = id.toLowerCase();
    byId.set(key, { ...byId.get(key), ...e, id });
  }
  if (!byId.size)
    return prev;
  return {
    sells: [...byId.values()].sort((a, b) => (Number(a.at) || 0) - (Number(b.at) || 0)),
  };
}

/** 落库失败时先改本地，避免按钮仍可卖 */
function applyManualSellOrdersLocally(buyRow: OrderRow, ordersToSave: VenueOrder[]): void {
  const orderStore = useOrderStore();
  const byId = new Map<string, OrderRow>();
  for (const rows of orderStore.orders.values()) {
    for (const row of rows)
      byId.set(String(row.OrderID ?? ""), row);
  }
  for (const local of venueOrdersToLocalRows(buyRow, ordersToSave)) {
    const id = String(local.OrderID ?? "").trim();
    if (!id)
      continue;
    byId.set(id, local);
  }
  orderStore.orders = groupOrdersByEffectiveLink([...byId.values()]);
}

async function persistFilledSell(
  account: PlatformAccount,
  buyRow: OrderRow,
  ordersToSave: VenueOrder[],
): Promise<boolean> {
  // [changmen 扩展] 只有带持久 GTC 身份的原单使用专用保存；普通卖出保留原函数体。
  if (buyRow.PmGtcExecutionId)
    return persistGtcFilledSell(account, buyRow, ordersToSave);
  const sessionVersion = getAuthSessionVersion();
  const scope = pmSubmitScope(account);
  const current = () => isAuthSessionCurrent(sessionVersion) && scope === pmSubmitScope(account);
  try {
    await saveOrders(account, ordersToSave);
    return current();
  }
  catch (saveErr) {
    if (!current()) return false;
    try {
      await saveOrders(account, ordersToSave);
      return current();
    }
    catch {
      if (!current()) return false;
      const id = String(buyRow.OrderID ?? "");
      const closing = closingByBuyId.value.get(id);
      if (closing) {
        const next = new Map(closingByBuyId.value);
        next.set(id, { ...closing, ordersToSave });
        setClosingMap(next);
      }
      // 勿立刻 fetchOrders：会冲掉本地乐观已平仓，导致按钮可再卖 → 双卖
      applyManualSellOrdersLocally(buyRow, ordersToSave);
      scheduleResumePmManualSellClosings();
      ElMessage.error(
        `链上已平仓，但订单落库失败：${saveErr instanceof Error ? saveErr.message : String(saveErr)}。已按已平仓展示，请稍后刷新。`,
      );
      return false;
    }
  }
}

async function persistGtcFilledSell(
  account: PlatformAccount,
  buyRow: OrderRow,
  ordersToSave: VenueOrder[],
): Promise<boolean> {
  const sessionVersion = getAuthSessionVersion();
  const scope = pmSubmitScope(account);
  const current = () => isAuthSessionCurrent(sessionVersion) && scope === pmSubmitScope(account);
  const persist = async () => {
    if (buyRow.PmGtcExecutionId) {
      // [changmen 扩展] 仅这张 GTC 原单的平仓核对净回款，FOK 保留原保存路径。
      const { saveOrders: saveGtcOrders } = await import("@/orderModes/gtc/ordersApi");
      await saveGtcOrders(account, ordersToSave.map(row => ({ ...row, pmGtcExecutionId: buyRow.PmGtcExecutionId })));
    }
    else {
      await saveOrders(account, ordersToSave);
    }
  };
  try {
    await persist();
    return current();
  }
  catch (saveErr) {
    if (!current()) return false;
    try {
      await persist();
      return current();
    }
    catch {
      if (!current()) return false;
      const id = String(buyRow.OrderID ?? "");
      const closing = closingByBuyId.value.get(id);
      if (closing) {
        const next = new Map(closingByBuyId.value);
        next.set(id, { ...closing, ordersToSave });
        setClosingMap(next);
      }
      // 勿立刻 fetchOrders：会冲掉本地乐观已平仓，导致按钮可再卖 → 双卖
      applyManualSellOrdersLocally(buyRow, ordersToSave);
      scheduleResumePmManualSellClosings();
      const reason = saveErr instanceof Error ? saveErr.message : String(saveErr);
      if (buyRow.PmGtcExecutionId) {
        // GTC 保存包含 CONFIRMED 成交及净回款核对；撮合回执不能证明链上结算已完成。
        ElMessage.warning(`卖单已返回成交，成交确认、净回款核对或订单保存尚未完成：${reason}。已保留原卖单并自动重试，请勿重复卖出。`);
      }
      else {
        ElMessage.error(`链上已平仓，但订单落库失败：${reason}。已按已平仓展示，请稍后刷新。`);
      }
      return false;
    }
  }
}

export function isPmManualSellClosing(orderId: string | number | undefined): boolean {
  return closingByBuyId.value.has(String(orderId ?? "").trim());
}

/** 供自动卖（arb）写入平仓中会话，落库失败时可 resume */
export function trackPmManualSellClosing(
  buyOrderId: string,
  info: { sellOrderId: string; fallbackPrice?: number; sharesWanted?: number },
  account?: PlatformAccount,
): void {
  enterClosing(buyOrderId, info.sellOrderId, {
    fallbackPrice: info.fallbackPrice,
    sharesWanted: info.sharesWanted,
    account,
  });
}

export function clearPmManualSellClosing(buyOrderId: string): void {
  clearClosing(buyOrderId);
}

export function canManualSellPmBuy(row: OrderRow): boolean {
  const orderId = String(row.OrderID ?? "").trim();
  if (!orderId)
    return false;
  if (isPmManualSellClosing(orderId))
    return false;
  if (String(row.Type ?? "").trim() !== "Polymarket")
    return false;
  if (row.PmSide === "sell")
    return false;
  if (!String(row.PmTokenId ?? "").trim())
    return false;
  if (resolvePmRemainingShares(row) <= 0.0001)
    return false;
  return hasOpenPolymarketPosition(row);
}

export function isPmManualSellInFlight(orderId: string | number | undefined): boolean {
  const id = String(orderId ?? "").trim();
  return setHas(sellingOrderIds, id) || isPmManualSellClosing(id);
}

async function applyFinalFilled(
  buyRow: OrderRow,
  account: PlatformAccount,
  ordersToSave: VenueOrder[],
  sharesSold: number,
  sharesWanted: number,
  partialFill: boolean,
): Promise<void> {
  const orderId = String(buyRow.OrderID ?? "").trim();
  const saved = await persistFilledSell(account, buyRow, ordersToSave);
  if (!saved) {
    // 落库失败：已 toast error + 本地乐观已平仓 + 保留 closing；勿再报成功
    return;
  }
  clearClosing(orderId);
  try {
    await useOrderStore().fetchOrders();
  }
  catch { /* ignore */ }
  const sharesText = formatPolymarketApiDecimal(sharesWanted);
  if (partialFill) {
    ElMessage.warning(
      `仅成交 ${formatPolymarketApiDecimal(sharesSold)} / ${sharesText} 份（已平仓写入）`,
    );
  }
  else {
    ElMessage.success(`已平仓 ${formatPolymarketApiDecimal(sharesSold)} 份`);
  }
}

/**
 * 刷新后恢复：对 session 内仍「平仓中」的买单跑完终态确认。
 */
export async function resumePmManualSellClosings(): Promise<void> {
  if (resumeInFlight)
    return;
  for (const account of useAccountStore().accounts ?? []) {
    if (account.provider !== "Polymarket") continue;
    try {
      for (const attempt of pmAccountSubmitAttempts(account)) {
        if (attempt.side === "SELL" && attempt.parentBuyId && !closingByBuyId.value.has(attempt.parentBuyId))
          enterClosing(attempt.parentBuyId, attempt.acceptedOrderId || attempt.orderHash,
            { sharesWanted: Number(attempt.makerAmount) / 1e6,
              fallbackPrice: Number(attempt.takerAmount) / Number(attempt.makerAmount), account });
      }
    } catch { /* 凭证尚未可用时不解除锁 */ }
  }
  const entries = [...closingByBuyId.value.entries()];
  if (!entries.length)
    return;

  resumeInFlight = true;
  const orderStore = useOrderStore();
  const accountStore = useAccountStore();
  try {
    const byId = new Map<string, OrderRow>();
    for (const rows of orderStore.orders.values()) {
      for (const row of rows)
        byId.set(String(row.OrderID ?? ""), row);
    }

    for (const [buyId, entry] of entries) {
      // 正在卖出流程中：勿并发 resume
      if (setHas(sellingOrderIds, buyId))
        continue;

      const row = byId.get(buyId);
      if (!row) {
        // 列表尚未加载或过滤掉父单，不能解除未决卖出。
        continue;
      }
      if (!entry.sellOrderId) {
        clearClosing(buyId);
        continue;
      }
      const account = accountStore.findAccount(Number(row.PlayerID));
      if (!account?.token || account.provider !== "Polymarket") continue;
      if (!entry.pmScope) {
        const original = pmAccountSubmitAttempts(account).find(attempt => attempt.parentBuyId === buyId
          && (attempt.orderHash === entry.sellOrderId || attempt.acceptedOrderId === entry.sellOrderId));
        if (!original) {
          const version = getAuthSessionVersion();
          const scope = pmSubmitScope(account);
          let snapshot;
          try { snapshot = validatePmSubmission(await getPmSubmission(account.accountId, buyId), buyId, account.accountId); }
          catch { continue; }
          if (!isAuthSessionCurrent(version) || scope !== pmSubmitScope(account)
            || !snapshot?.makerAddress || snapshot.makerAddress !== pmSubmitMaker(account)) continue;
        }
        entry.pmScope = pmSubmitScope(account);
        entry.accountId = account.accountId;
        writeClosing(closingByBuyId.value);
      }
      if (entry.pmScope !== pmSubmitScope(account) || entry.accountId !== account.accountId) continue;
      const sessionVersion = getAuthSessionVersion();
      // 乐观展示不能视为已落库：优先重放原补丁，避免再次计提盈亏。
      if (entry.ordersToSave?.length) {
        if (await persistFilledSell(account, row, entry.ordersToSave) && isAuthSessionCurrent(sessionVersion)) {
          clearClosing(buyId);
          try { await orderStore.fetchOrders(); } catch { /* 下次刷新 */ }
        } else scheduleResumePmManualSellClosings();
        continue;
      }
      const accountedSell = String(row.PmLastSellOrderId ?? "").toLowerCase() === entry.sellOrderId.toLowerCase()
        || row.PositionEvents?.sells?.some(event => String(event.id).toLowerCase() === entry.sellOrderId.toLowerCase());
      if (accountedSell) {
        clearClosing(buyId);
        continue;
      }
      // 父单被其它卖出关闭不能证明本次卖单已归账，保留资产锁。
      if (String(row.PmSellState ?? "").toLowerCase() === "closed"
        || resolvePmRemainingShares(row) <= 0.0001) {
        continue;
      }

      addId(sellingOrderIds, buyId);
      try {
        const final = await awaitPolymarketManualSellFinalOutcome({
          account,
          buyRow: row,
          sellOrderId: entry.sellOrderId,
          fallbackPrice: entry.fallbackPrice,
          sharesWanted: entry.sharesWanted,
        });
        if (!isAuthSessionCurrent(sessionVersion) || entry.pmScope !== pmSubmitScope(account)) continue;
        if (final.outcome === "filled") {
          const saved = await persistFilledSell(account, row, final.ordersToSave);
          if (saved) {
            clearClosing(buyId);
            try {
              await orderStore.fetchOrders();
            }
            catch { /* ignore */ }
          }
          else scheduleResumePmManualSellClosings();
          // 落库失败：保留 closing 下次再试
        }
        else if (final.outcome === "unfilled") {
          clearClosing(buyId);
        }
        else {
          // pending：保留 closing，并退避续查；绝不重新开放卖出。
          scheduleResumePmManualSellClosings();
        }
      }
      catch {
        // 网络/异常：保留平仓中，下次 fetchOrders 再试（勿清会话以免双卖）
      }
      finally {
        removeId(sellingOrderIds, buyId);
      }
    }
  }
  finally {
    resumeInFlight = false;
  }
}

export async function confirmAndSellPmBuyOrder(row: OrderRow): Promise<boolean> {
  const orderId = String(row.OrderID ?? "").trim();
  if (!orderId || !canManualSellPmBuy(row))
    return false;
  if (setHas(sellingOrderIds, orderId))
    return false;

  addId(sellingOrderIds, orderId);
  try {
    const shares = resolvePmRemainingShares(row);
    const sharesText = formatPolymarketApiDecimal(shares);
    const { ElMessageBox } = await import("element-plus");
    try {
      await ElMessageBox.confirm(
        `市价全卖该买单对应份额 ${sharesText}？`,
        "PM 卖出",
        { type: "warning", confirmButtonText: "卖出", cancelButtonText: "取消" },
      );
    }
    catch {
      return false;
    }

    const accountStore = useAccountStore();
    const account = accountStore.findAccount(Number(row.PlayerID));
    if (!account?.token) {
      ElMessage.error("找不到对应 Polymarket 账号");
      return false;
    }
    const sessionVersion = getAuthSessionVersion();
    const scope = pmSubmitScope(account);
    const current = () => isAuthSessionCurrent(sessionVersion) && scope === pmSubmitScope(account);

    const result = await sellPolymarketBuyPosition({
      account,
      buyRow: row,
      onSubmitted: (info) => {
        if (!current()) return;
        enterClosing(orderId, info.sellOrderId, {
          fallbackPrice: info.fallbackPrice,
          sharesWanted: info.sharesWanted,
          account,
        });
      },
    });
    if (!current()) return false;

    if (result.ok && result.ordersToSave?.length) {
      await applyFinalFilled(
        row,
        account,
        result.ordersToSave,
        result.sharesSold ?? shares,
        shares,
        Boolean(result.partialFill),
      );
      return true;
    }

    if (result.unfilled) {
      clearClosing(orderId);
      ElMessage.warning(result.error ?? "未成交，可重新卖出");
      return false;
    }

    if (result.pending && result.sellOrderId) {
      ElMessage.warning(result.error ?? "卖单仍待场馆确认，已保持平仓中");
      scheduleResumePmManualSellClosings();
      return false;
    }

    // 异常仍带 sellOrderId：再跑终态，保证离开平仓中
    if (result.sellOrderId) {
      const closing = closingByBuyId.value.get(orderId);
      enterClosing(orderId, result.sellOrderId, {
        fallbackPrice: closing?.fallbackPrice,
        sharesWanted: closing?.sharesWanted ?? shares,
        account,
      });
      const final = await awaitPolymarketManualSellFinalOutcome({
        account,
        buyRow: row,
        sellOrderId: result.sellOrderId,
        fallbackPrice: closing?.fallbackPrice,
        sharesWanted: closing?.sharesWanted ?? shares,
      });
      if (final.outcome === "filled") {
        await applyFinalFilled(
          row,
          account,
          final.ordersToSave,
          final.sharesSold,
          shares,
          final.partialFill,
        );
        return true;
      }
      if (final.outcome === "pending") {
        ElMessage.warning(final.reason || "卖单仍待场馆确认，已保持平仓中");
        scheduleResumePmManualSellClosings();
        return false;
      }
      clearClosing(orderId);
      ElMessage.warning(final.reason || "未成交，可重新卖出");
      return false;
    }

    clearClosing(orderId);
    ElMessage.error(result.error ?? "卖出失败");
    return false;
  }
  catch (err) {
    // 若已进入 closing（有卖单号），保留会话等 resume；否则清掉
    const closing = closingByBuyId.value.get(orderId);
    if (!closing?.sellOrderId)
      clearClosing(orderId);
    ElMessage.error(err instanceof Error ? err.message : String(err));
    return false;
  }
  finally {
    removeId(sellingOrderIds, orderId);
  }
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { BetResult } from "@changmen/client-core/models/betResult";
import type { PlatformAccount } from "@/models/platformAccount";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import { buildPolymarketMatchedBuyVenueOrderFromBet } from "@changmen/venue-adapter/polymarket";
import { saveOrders } from "@/api/order";

/**
 * [changmen 扩展] PM FOK matched：用 POST 成交金额立刻 saveOrders，
 * 侧栏不依赖 `/data/trades` 索引（官方 Place Order 语义）。
 * delayed / 非 PM / 解析失败返回 null，不影响下单成功。
 */
export async function persistPolymarketMatchedBuyOrder(
  account: PlatformAccount,
  option: BetOption,
  result: BetResult,
): Promise<VenueOrder | null> {
  if (String(account.provider ?? "") !== "Polymarket")
    return null;
  const order = await buildPolymarketMatchedBuyVenueOrderFromBet(option, result);
  if (!order)
    return null;
  await saveOrders(account, [order]);
  return order;
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { BetResult } from "@changmen/client-core/models/betResult";
import type { PlatformAccount } from "@/models/platformAccount";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import {
  buildPolymarketExecutionRejectVenueOrder,
  isPolymarketPostedApiFailure,
  type PolymarketExecutionRejectReason,
  type PolymarketRejectOrderContext,
} from "@changmen/venue-adapter/polymarket";
import { saveOrders } from "@/api/order";
import { pmMakerAmountUsdc, pmSubmissionFromResult } from "@changmen/shared/pm_submission";
import { scaleUsdtToCnyDisplay } from "@changmen/shared/currency";
import { resolveOrderItemLabel } from "@/shared/orderItemDisplay";
import { refreshOrderListAfterBind } from "@/stores/betting/arbOrderBind";

/** Reject 落库选项：队名优先，避免管理端只看到 Home/Away */
function itemLabelFromBetOption(option: BetOption): string {
  const target = String(option.target ?? "").trim();
  const named = option.target === "Away"
    ? String(option.bet?.awayName ?? "").trim()
    : String(option.bet?.homeName ?? "").trim();
  if (named)
    return named;
  const matchTitle = String(option.match?.title ?? "");
  const fromMatch = resolveOrderItemLabel(target, matchTitle);
  if (fromMatch && fromMatch !== target)
    return fromMatch;
  return target;
}

function contextFromBetOption(
  option: BetOption | undefined,
  linkId?: number,
): PolymarketRejectOrderContext {
  const link = Number(linkId) || 0;
  if (!option) {
    return link ? { link } : {};
  }
  // [changmen 扩展] option 可能来自旧队列，不能用它推断原单申请金额。
  return {
    betMoney: 0,
    odds: Number(option.odds) || 0,
    game: String(option.match?.game ?? ""),
    match: String(option.match?.title ?? ""),
    bet: String(option.bet?.getBetName?.() ?? ""),
    item: itemLabelFromBetOption(option),
    ...(link ? { link } : {}),
  };
}

/**
 * [changmen 扩展] 已执行 PM 下单但未成交 → 落库 Reject，供平台拒单率统计。
 * - unfilled：settle 确认 FOK/取消，或用户授权的买入超时判拒（result.message 保留依据）
 * - api_failed：已 POST 但未成交（常无官方 orderId，用合成 id）
 * - 金额：对齐成交单（pmStakeUsdc=U，betMoney=CNY）；勿把场馆 U 直接写入 betMoney
 * 不改补单/判定；timeout 勿调用。预检 / POST 前失败勿调用。
 */
export async function persistPolymarketExecutionReject(
  account: PlatformAccount,
  result: BetResult,
  reason: PolymarketExecutionRejectReason,
  opts?: { betOption?: BetOption; linkId?: number },
): Promise<VenueOrder | null> {
  if (String(account.provider ?? "").trim() !== "Polymarket")
    return null;
  if (reason !== "unfilled" && reason !== "api_failed")
    return null;
  // api_failed 仅统计已 POST；unfilled 已由买入收尾层作出业务决定
  if (reason === "api_failed" && !isPolymarketPostedApiFailure(result))
    return null;
  const request = result.request as { order?: { makerAmount?: unknown; side?: unknown } } | undefined;
  const stakeUsdc = String(request?.order?.side).toUpperCase() === "BUY"
    ? pmMakerAmountUsdc(request?.order?.makerAmount) : null;
  // [changmen 扩展] 缺少原始提交记录是读取失败，禁止生成零金额/推算金额的正式订单。
  if (stakeUsdc == null)
    throw new Error("PM 原始提交记录缺失，拒绝写入订单");
  const order = buildPolymarketExecutionRejectVenueOrder(
    account,
    result,
    reason,
    contextFromBetOption(opts?.betOption, opts?.linkId),
  );
  order.pmStakeUsdc = stakeUsdc;
  order.betMoney = scaleUsdtToCnyDisplay(stakeUsdc);
  order.pmSubmission = pmSubmissionFromResult(result, account.accountId) ?? undefined;
  if (!String(order.orderId ?? "").trim())
    return null;
  try {
    await saveOrders(account, [order]);
    // Reject 已经是可展示终态，不应继续等待另一腿的拒单检测才出现在侧栏。
    refreshOrderListAfterBind();
    return order;
  }
  catch (err) {
    console.warn("[Polymarket] persist execution reject failed", err);
    return null;
  }
}

export { isPolymarketPostedApiFailure };

/**
 * Polymarket RDS 订单加载器注册（须在 sessionBoot 前 import）。
 * 对齐 A8：updateOrders → provider.getOrders → saveOrders；PM 在 getOrders 内合并 RDS。
 *
 * [changmen 扩展] 不拉全历史 + 不拉 money logs：
 * 窗口对齐 PM_ORDER_FULL_LOOKBACK_MS（3 天），后端额外保留未结/未 settled 买单。
 */
import type { PlatformAccount } from "@changmen/client-core/models/platformAccount";
import { getPlayerOrder } from "@/api/chat";
import {
  PM_ORDER_FULL_LOOKBACK_MS,
  registerPolymarketStoredVenueOrdersLoader,
  stripPolymarketSellOrders,
  venueOrderFromOrderRow,
} from "@changmen/venue-adapter/polymarket";

async function loadStoredPmVenueOrders(account: PlatformAccount) {
  const sinceCreateAt = Date.now() - PM_ORDER_FULL_LOOKBACK_MS;
  const info = await getPlayerOrder({
    playerId: account.accountId,
    sinceCreateAt,
    includeLogs: false,
  });
  return stripPolymarketSellOrders(
    (info.orders ?? [])
      .filter(o => String(o.Type ?? "") === "Polymarket")
      .map(o => venueOrderFromOrderRow(o)),
  );
}

registerPolymarketStoredVenueOrdersLoader(loadStoredPmVenueOrders);

/** [changmen 扩展] 普通订单同步保存成功后，持久化 RAY 用户端已确认的原单关联。 */
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import { getActivePinia } from "pinia";
import { getAuthSessionVersion, isAuthSessionCurrent } from "@/api/client";
import { useRayOrderContextStore } from "@/runtime/rayOrderMonitor/contextStore";
import { bindArbOrderId } from "@/stores/betting/arbOrderBind";
import { useAccountStore } from "@/stores/accountStore";
import { useOrderStore } from "@/stores/orderStore";
import { useUserStore } from "@/stores/userStore";

export async function syncRayOrderBindings(account: PlatformAccount, orders: readonly VenueOrder[]): Promise<void> {
  if (!getActivePinia())
    return;
  const user = useUserStore();
  const accountStore = useAccountStore();
  const owner = String(user.userId || "");
  if (!owner || user.isLoggedIn === false || accountStore.adminWorkspacePreview)
    return;
  const contexts = useRayOrderContextStore();
  contexts.restore(owner);
  const session = getAuthSessionVersion();
  const binding = JSON.stringify([account.gateway, account.token, account.currency]);
  const current = () => isAuthSessionCurrent(session) && String(user.userId || "") === owner
    && user.isLoggedIn !== false && !accountStore.adminWorkspacePreview
    && accountStore.findAccount(account.accountId) === account
    && binding === JSON.stringify([account.gateway, account.token, account.currency]);
  const ids = new Set(orders.filter(order => order.provider === "RAY").map(order => String(order.orderId)));
  for (const task of [...contexts.tasks.values()]) {
    if (!current())
      return;
    if (task.accountId !== account.accountId || !task.boundOrderId || !task.monitorBound || task.bindingSaved || !ids.has(task.boundOrderId))
      continue;
    const known = [...useOrderStore().orders.values()].flat().find(row => row.Type === "RAY"
      && row.PlayerID === account.accountId && String(row.OrderID) === task.boundOrderId);
    if (known?.Link && known.Link !== task.linkId && known.Link !== known.CreateAt && known.Link !== Number(known.CreateAt) - 1) {
      contexts.patch(task.key, { lastError: "场馆原单已属于其他 Link，未自动改绑" });
      continue;
    }
    contexts.patch(task.key, { orderSaved: true });
    try {
      if (known?.Link !== task.linkId && !await bindArbOrderId(task.linkId, "RAY", account.accountId, task.boundOrderId))
        throw new Error("RAY 原单关联保存失败，等待订单同步重试");
      if (current())
        contexts.patch(task.key, { bindingSaved: true, lastError: undefined });
    }
    catch (error) {
      if (current())
        contexts.patch(task.key, { lastError: error instanceof Error ? error.message : String(error) });
    }
  }
}

import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import { sortVenueOrdersNewestFirst } from "@changmen/venue-adapter/contract";
import { hasOpenPolymarketPosition, resolvePmRemainingShares } from "@changmen/venue-adapter/polymarket";
import { wait } from "@changmen/client-core/shared/wait";
import { Currency, getExchange } from "@changmen/shared/currency";
import { truncateShareUsdtAmount } from "@/shared/pfOrderDisplay";
import { saveOrders } from "@/api/order";
import { getProvider } from "@/runtime/providers";
import { isObSportBetToken, sportObSessionFromAccount } from "@/runtime/obSportBetAccount";

/** PM 下单后等 CLOB trades 索引：最多尝试次数 / 间隔 */
const WAIT_FOR_ORDER_ATTEMPTS_DEFAULT = 5;
const WAIT_FOR_ORDER_GAP_MS_DEFAULT = 500;

function isOpenUnsettledVenueOrder(o: VenueOrder): boolean {
  if (o.status !== "none")
    return false;
  if (o.provider === "Polymarket")
    return hasOpenPolymarketPosition(o);
  if (o.provider === "PredictFun") {
    if (o.pfSide === "sell" || o.pfSellState === "closed" || o.pfSellState === "settled")
      return false;
  }
  return true;
}

/** 未结敞口 CNY：PM/PF 用份额×$1×汇率；其它场馆仍 bet×odds */
function unsettledExposureCny(o: VenueOrder): number {
  const fx = getExchange(Currency.USDT);
  if (o.provider === "Polymarket" && o.pmSide !== "sell") {
    const rem = resolvePmRemainingShares(o);
    if (rem > 0.0001)
      return rem * fx;
    const fill = Number(o.pmShares) || 0;
    if (fill > 0.0001)
      return fill * fx;
    const stakeUsdc = Number(o.pmStakeUsdc) || 0;
    const price = Number(o.pmFillPrice);
    if (stakeUsdc > 0 && price > 0 && price < 1)
      return (stakeUsdc / price) * fx;
    return 0;
  }
  if (o.provider === "PredictFun" && o.pfSide !== "sell") {
    const hold = Number(o.pfHoldShares) || 0;
    const fill = Number(o.pfShares) || 0;
    const shares = hold > 0 ? hold : fill;
    if (shares > 0)
      return truncateShareUsdtAmount(shares) * fx;
    const notional = Number(o.pfNotionalUsdt) || Number(o.betMoney) || 0;
    const book = Number(o.pfBookPrice);
    if (notional > 0 && book > 0 && book < 1)
      return truncateShareUsdtAmount(notional / book) * fx;
    return 0;
  }
  const odds = Number(o.odds) || 0;
  return odds * (Number(o.betMoney) || 0);
}

export function applyUnsettledStats(account: PlatformAccount, orders: VenueOrder[]) {
  const open = orders.filter(isOpenUnsettledVenueOrder);
  account.unsettle = open.length;
  const unsettledExposure = open.reduce((sum, o) => sum + unsettledExposureCny(o), 0);
  account.winBalance = (account.balance ?? 0) + unsettledExposure;
}

/** [changmen 扩展] 拉单入库时附带最终套利 Link，缩短占位窗口（见 docs/ARB_LINK_ID.md） */
export interface SyncVenueOrdersOpts {
  pendingBindLinkId?: number;
  pendingBindOrderId?: string;
  /**
   * [changmen 扩展] 下单后等待 getOrders 出现该 orderId 再 save。
   * 缓解 PM getPlayerOrder 变快后、CLOB trades 尚未索引导致首轮漏单。
   */
  waitForOrderId?: string;
  /** 下单成功但场馆不回 orderId（RAY）：短重试到出现本次提交后的订单。 */
  waitForRecentOrderAfterMs?: number;
  waitForOrderAttempts?: number;
  waitForOrderGapMs?: number;
}

function ordersIncludeId(orders: VenueOrder[], orderId: string): boolean {
  const id = String(orderId ?? "").trim();
  if (!id)
    return true;
  return orders.some(o => String(o.orderId ?? "").trim() === id);
}

function stampPendingBindLink(orders: VenueOrder[], opts?: SyncVenueOrdersOpts): void {
  const linkId = Number(opts?.pendingBindLinkId);
  if (!Number.isFinite(linkId) || linkId === 0)
    return;
  const targetId = String(opts?.pendingBindOrderId ?? "").trim();
  if (targetId) {
    const hit = orders.find(o => String(o.orderId ?? "").trim() === targetId);
    if (hit)
      hit.link = linkId;
    return;
  }
  // 无明确 orderId 时只标最新一条（与 A8 绑 orders[0] 一致）
  if (orders[0])
    orders[0].link = linkId;
}

function ordersIncludeRecent(orders: VenueOrder[], submittedAt: number): boolean {
  if (!Number.isFinite(submittedAt) || submittedAt <= 0)
    return true;
  // 场馆 create_time 可能只有秒精度，给 10 秒时钟/解析容差。
  const threshold = submittedAt - 10_000;
  return orders.some(order => Number(order.createAt) >= threshold);
}

function isSportsWorkspacePath(pathname = globalThis.location?.pathname): boolean {
  return String(pathname || "").startsWith("/sports");
}

async function syncSportsWorkspaceOrders(account: PlatformAccount): Promise<VenueOrder[] | undefined | null> {
  const providerId = String(account.provider ?? "").trim().toLowerCase();
  if (providerId === "ob") {
    if (!sportObSessionFromAccount(account))
      return undefined;
    const { useFootballOrderStore } = await import("@/stores/footballOrderStore");
    const footballOrders = useFootballOrderStore();
    if (!footballOrders.loaded && !footballOrders.loading)
      await footballOrders.load();
    // 与电竞 getOrders -> saveOrders 一致：账号刷新主动拉场馆完整近期列表，缺失单由体育 store upsert。
    await footballOrders.syncVenueAccountOrders(account.accountId);
    // 近期窗口之外的历史待结订单继续走已知 orderId 补结算。
    await footballOrders.syncVenueSettlement();
    return [];
  }

  // 体育页只允许体育/预测类账号沿用通用拉单；其他电竞馆避免写入电竞订单。
  if (providerId !== "polymarket" && providerId !== "predictfun")
    return undefined;
  return null;
}

/**
 * 对齐 A8 `uv.updateOrders` + `Vt.saveOrders`（全场馆统一 provider.getOrders）。
 * [changmen 扩展] PredictFun：只拉单更新本地统计，不 Client_SaveOrder（RDS 仅 Pf_* 写）。
 * [changmen 扩展] waitForOrderId：可重试 getOrders，只在最终结果上 save 一次。
 */
export async function syncVenueOrders(
  account: PlatformAccount,
  opts?: SyncVenueOrdersOpts,
  onFetchedOrders?: (orders: VenueOrder[]) => void,
): Promise<VenueOrder[] | undefined> {
  if (isSportsWorkspacePath()) {
    const handled = await syncSportsWorkspaceOrders(account);
    if (handled !== null)
      return handled;
  }

  // [changmen 扩展] 体育专用 OB 卡没有电竞会话，不能用外层残留网关拉电竞订单。
  if (account.provider === "OB") {
    const token = String(account.token || "").trim();
    if (!token || isObSportBetToken(token))
      return undefined;
  }

  const provider = getProvider(account);
  if (!provider?.getOrders)
    return undefined;

  const waitId = String(opts?.waitForOrderId ?? "").trim();
  const waitRecentAfter = Number(opts?.waitForRecentOrderAfterMs) || 0;
  const attempts = waitId || waitRecentAfter > 0
    ? Math.max(1, Number(opts?.waitForOrderAttempts) || WAIT_FOR_ORDER_ATTEMPTS_DEFAULT)
    : 1;
  const gapMs = Math.max(0, Number(opts?.waitForOrderGapMs) || WAIT_FOR_ORDER_GAP_MS_DEFAULT);

  let orders: VenueOrder[] | undefined;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    const raw = await provider.getOrders(account);
    if (raw == null) {
      // 保留上一轮成功结果；首轮失败则整体失败
      if (orders)
        break;
      return undefined;
    }
    orders = sortVenueOrdersNewestFirst(raw);
    const targetVisible = waitId
      ? ordersIncludeId(orders, waitId)
      : ordersIncludeRecent(orders, waitRecentAfter);
    if (targetVisible)
      break;
    if (attempt < attempts)
      await wait(gapMs);
  }
  if (!orders)
    return undefined;

  // [A8 可证实] uv.updateOrders 在保存之前持有 e；底层同步仍保留失败抛错的约定。
  onFetchedOrders?.(orders);
  stampPendingBindLink(orders, opts);
  applyUnsettledStats(account, orders);
  if (String(account.provider ?? "").trim() !== "PredictFun")
    await saveOrders(account, orders);
  // [changmen 扩展] RAY 监控只确认客户端身份；持久化关联跟随本次正常订单同步。
  if (account.provider === "RAY") {
    void import("./rayOrderBindings")
      .then(({ syncRayOrderBindings }) => syncRayOrderBindings(account, orders))
      .catch(error => console.error("[RAY] 订单关联同步失败", error));
  }
  return orders;
}

/** 对齐 A8 `uv.updateOrders`：拉场馆订单并返回（拒单检测用） */
export async function updateVenueOrders(
  account: PlatformAccount,
  opts?: SyncVenueOrdersOpts,
): Promise<VenueOrder[] | undefined> {
  let fetchedOrders: VenueOrder[] | undefined;
  account.loadingBalance = true;
  try {
    return await syncVenueOrders(account, opts, (orders) => { fetchedOrders = orders; });
  }
  catch (err) {
    console.error(`[${account.provider}]${account.playerName} 加载订单出错`, err);
    // [A8 可证实] return e 在 catch 之后；上报失败不能抹去已查到的拒单结果。
    return fetchedOrders;
  }
  finally {
    account.loadingBalance = false;
  }
}

import type { BetResult } from "@changmen/client-core/models/betResult";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import { wait } from "@changmen/client-core/shared/wait";
import { saveOrderBind } from "@/api/esport";
import { observeOrder } from "@/services/orderObservation";

const BIND_RETRY_TIMES = 3;
const BIND_RETRY_GAP_MS = 400;

/** [A8 可证实] 列表非空时绑 orders[0].orderId */
function resolveA8VenueBindOrderId(orders: VenueOrder[]): string | undefined {
  if (orders.length === 0)
    return undefined;
  const id = String(orders[0].orderId ?? "").trim();
  return id || undefined;
}

/** 绑单 orderId：拒单腿优先绑本次检测到的拒单；成单腿优先 result.orderId，否则 orders[0] */
export function resolveArbBindOrderId(
  orders: VenueOrder[],
  result: BetResult | undefined,
  rejected = false,
): string | undefined {
  const fromResult = String(result?.orderId ?? "").trim();
  if (rejected) {
    if (fromResult) {
      const ours = orders.find(o => String(o.orderId ?? "") === fromResult);
      if (ours)
        return fromResult;
    }
    return resolveA8VenueBindOrderId(orders);
  }
  if (fromResult)
    return fromResult;
  return resolveA8VenueBindOrderId(orders);
}

/**
 * 套利/补单：把场馆订单绑到同一 LinkID。
 * [changmen 扩展] 失败重试；不抛错，返回是否成功。
 */
export async function bindArbLegOrder(
  linkId: number,
  account: PlatformAccount,
  result: BetResult,
  orders: VenueOrder[],
  rejected: boolean,
): Promise<boolean> {
  if (!linkId || !result?.success)
    return false;
  const orderId = resolveArbBindOrderId(orders, result, rejected);
  if (!orderId)
    return false;

  const bound = await bindArbOrderId(linkId, result.provider, account.accountId, orderId);
  try {
    observeOrder(result.observation, linkId, "bind_result", { provider: result.provider, accountId: account.accountId, orderId, outcome: bound ? "saved" : "failed", source: "bind_api_ack" });
  }
  catch { /* 观察异常不改变实际绑定回执 */ }
  return bound;
}

/** 已知场馆 orderId 的 Link 绑定；供延迟发现订单的旁路监控复用。 */
export async function bindArbOrderId(
  linkId: number,
  provider: string,
  accountId: number,
  orderId: string,
): Promise<boolean> {
  if (!linkId || !accountId || !String(orderId).trim())
    return false;

  const payload = {
    orders: JSON.stringify([
      {
        LinkID: linkId,
        Provider: provider,
        PlayerID: accountId,
        OrderID: orderId,
      },
    ]),
  };

  for (let attempt = 1; attempt <= BIND_RETRY_TIMES; attempt++) {
    try {
      const ok = await saveOrderBind(payload);
      if (ok)
        return true;
      console.warn(
        `[arbOrderBind] SaveOrderBind failed attempt ${attempt}/${BIND_RETRY_TIMES}`,
        { linkId, provider, orderId },
      );
    }
    catch (e) {
      console.warn(
        `[arbOrderBind] SaveOrderBind error attempt ${attempt}/${BIND_RETRY_TIMES}`,
        e,
      );
    }
    if (attempt < BIND_RETRY_TIMES)
      await wait(BIND_RETRY_GAP_MS);
  }
  return false;
}

/** 绑单后刷新侧栏订单列表（合并组可见） */
export function refreshOrderListAfterBind(): void {
  void import("@/stores/orderStore")
    .then(({ useOrderStore }) => useOrderStore().fetchOrders())
    .catch(() => {});
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { PlatformAccount } from "@/models/platformAccount";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import { sortVenueOrdersNewestFirst } from "@changmen/venue-adapter/contract";
import { wait } from "@changmen/client-core/shared/wait";
import { getProvider } from "@/runtime/providers";
import { refreshOrderListAfterBind } from "@/stores/betting/arbOrderBind";
import { canAppearArbOrderDuringRejectWait } from "@/stores/betting/autoBet/appearArbOrderGate";

export { canAppearArbOrderDuringRejectWait } from "@/stores/betting/autoBet/appearArbOrderGate";

/** 拒单等待期间对单轮询间隔。首轮立即拉，不空等。 */
export const ARB_EARLY_APPEAR_INTERVAL_MS = 500;
/** 另一腿还在 POST 时多给几秒，避免 poller 先于场馆出单结束 */
export const ARB_EARLY_APPEAR_PLACE_SLACK_MS = 4_000;
const ARB_EARLY_APPEAR_MAX_MS = 12_000;
const ODDS_EPS = 0.02;
const STAKE_EPS = 0.51;
const CREATE_AT_SLACK_MS = 15_000;

const inflight = new Map<string, Promise<boolean>>();

export interface AppearArbOrderOpts {
  account: PlatformAccount;
  option: BetOption;
  linkId: number;
  rejectWaitSec?: number;
  placedAt?: number;
}

export function appearArbOrderInflightKey(
  accountId: number,
  linkId: number,
  itemId: string,
): string {
  return `${accountId}:${linkId}:${itemId}`;
}

/** 用本腿金额/赔率/下单时间对上最新场馆单，避免误标 orders[0] */
export function findMatchingArbVenueOrder(
  orders: VenueOrder[],
  option: BetOption,
  placedAt: number,
): VenueOrder | undefined {
  const stake = Number(option.betMoney) || 0;
  const odds = Number(option.odds) || 0;
  const newestFirst = sortVenueOrdersNewestFirst(orders);
  return newestFirst.find((order) => {
    const orderId = String(order.orderId ?? "").trim();
    if (!orderId)
      return false;
    if (Math.abs((Number(order.betMoney) || 0) - stake) > STAKE_EPS)
      return false;
    if (odds > 0 && Math.abs((Number(order.odds) || 0) - odds) > ODDS_EPS)
      return false;
    const created = Number(order.createAt) || 0;
    if (created > 0 && created < placedAt - CREATE_AT_SLACK_MS)
      return false;
    return true;
  });
}

export function appearArbOrderBudgetMs(rejectWaitSec?: number): number {
  const waitMs = Math.max(0, Number(rejectWaitSec) || 0) * 1000;
  return Math.min(ARB_EARLY_APPEAR_MAX_MS, Math.max(waitMs + ARB_EARLY_APPEAR_PLACE_SLACK_MS, ARB_EARLY_APPEAR_PLACE_SLACK_MS));
}

/**
 * [A8 可证实] 拒单等待是空等。本函数保留对单逻辑，入口 `canAppearArbOrderDuringRejectWait` 恒为 false。
 */
export function appearArbOrderDuringRejectWait(opts: AppearArbOrderOpts): Promise<boolean> {
  const linkId = Number(opts.linkId);
  const itemId = String(opts.option?.itemId ?? "").trim();
  if (!Number.isFinite(linkId) || linkId === 0 || !opts.option)
    return Promise.resolve(false);
  if (!canAppearArbOrderDuringRejectWait(opts.account.provider))
    return Promise.resolve(false);

  const key = appearArbOrderInflightKey(Number(opts.account.accountId) || 0, linkId, itemId);
  const running = inflight.get(key);
  if (running)
    return running;

  const task = runAppearArbOrderDuringRejectWait(opts).finally(() => {
    inflight.delete(key);
  });
  inflight.set(key, task);
  return task;
}

async function runAppearArbOrderDuringRejectWait(opts: AppearArbOrderOpts): Promise<boolean> {
  const provider = getProvider(opts.account);
  if (!provider?.getOrders)
    return false;

  const placedAt = Number(opts.placedAt) || Date.now();
  const budgetMs = appearArbOrderBudgetMs(opts.rejectWaitSec);
  const maxAttempts = Math.max(1, Math.ceil(budgetMs / ARB_EARLY_APPEAR_INTERVAL_MS));

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const raw = await provider.getOrders(opts.account);
      const orders = sortVenueOrdersNewestFirst(raw ?? []);
      const hit = findMatchingArbVenueOrder(orders, opts.option, placedAt);
      const orderId = String(hit?.orderId ?? "").trim();
      if (orderId) {
        const { useAccountStore } = await import("@/stores/accountStore");
        await useAccountStore().updateVenueOrders(opts.account, {
          pendingBindLinkId: opts.linkId,
          pendingBindOrderId: orderId,
        });
        refreshOrderListAfterBind();
        return true;
      }
    }
    catch {
      /* 提前露单失败不挡拒单检测 */
    }
    if (attempt < maxAttempts)
      await wait(ARB_EARLY_APPEAR_INTERVAL_MS);
  }
  return false;
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { BetResult } from "@changmen/client-core/models/betResult";
import type { PlatformAccount } from "@/models/platformAccount";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import {
  isVenueLegConfirmedUnfilled,
  isVenueLegPendingConfirm,
} from "@changmen/venue-adapter/contract";
import { resolveVenueLegOutcome } from "@/domain/betting/resolveVenueLegOutcome";
import { refreshOrderListAfterBind } from "@/stores/betting/arbOrderBind";
import { useAccountStore } from "@/stores/accountStore";
import { isPendingConfirmVenueProvider, isPolymarketProvider, isPredictFunProvider } from "@changmen/shared/account_multiply";
import { persistPolymarketExecutionReject } from "@/stores/account/pmRejectOrder";
import { wait } from "@changmen/client-core/shared/wait";

export interface ArbLegSettleResult {
  orders: VenueOrder[];
  /** 未成交或 PM 已授权超时判拒（可补单） */
  rejected: boolean;
  /** 场馆仍待确认；不能作为补单锚腿或补单目标 */
  pendingConfirm: boolean;
}

export interface SettleArbLegOpts {
  rejectWaitSec?: number;
  /** [changmen 扩展] SaveOrder 直写最终 Link，缩短占位窗口 */
  pendingBindLinkId?: number;
  /** [changmen 扩展] PM 未成交落库用（stake/盘口） */
  betOption?: BetOption;
}

/** 本地一轮 timeout 后续跟。PF 挂单可能仍 OPEN；PM 由 settlement job 持续确认原单。 */
export const PENDING_CONFIRM_FOLLOW_ROUNDS = 6;
export const PENDING_CONFIRM_FOLLOW_GAP_MS = 2_000;

/** 套利单腿：场馆 resolveLegOutcome（wait → 拉单 / PM settle） */
export async function settleArbLeg(
  account: PlatformAccount,
  result?: BetResult,
  rejectWaitSecOrOpts?: number | SettleArbLegOpts,
): Promise<ArbLegSettleResult> {
  const opts: SettleArbLegOpts = typeof rejectWaitSecOrOpts === "number"
    || rejectWaitSecOrOpts == null
    ? { rejectWaitSec: rejectWaitSecOrOpts }
    : rejectWaitSecOrOpts;
  const pendingBindOrderId = String(result?.orderId ?? "").trim() || undefined;
  // [changmen 扩展] 首轮拉单已带最终 Link 落库（venueOrders.stampPendingBindLink），
  // 侧栏无需等不确定重拉 / 另一腿 settle。PF 不经 Client_SaveOrder，跳过。
  const canRefreshEarly = Boolean(opts.pendingBindLinkId)
    && !isPredictFunProvider(account.provider);
  let refreshedSidebar = false;
  const outcome = await resolveVenueLegOutcome(
    account,
    result,
    async () => {
      const orders = await useAccountStore().updateVenueOrders(account, {
        pendingBindLinkId: opts.pendingBindLinkId,
        pendingBindOrderId,
        // 官方 delayed：matched 后 trades 可能滞后；等 orderId 出现再 save
        waitForOrderId: pendingBindOrderId,
        // RAY 成功响应不返回 orderId；首轮列表尚未索引时短重试，避免漏单后等全局轮询。
        waitForRecentOrderAfterMs: String(account.provider).toUpperCase() === "RAY"
          ? Number(result?.beginTime) || undefined
          : undefined,
      });
      if (canRefreshEarly && !refreshedSidebar && orders?.length) {
        refreshedSidebar = true;
        refreshOrderListAfterBind();
      }
      return orders;
    },
    {
      confirmPostAccepted: isPendingConfirmVenueProvider(account.provider) && Boolean(result),
      rejectWaitSec: opts.rejectWaitSec,
      pmConditionId: String(opts.betOption?.betId ?? "").trim() || undefined,
    },
  );
  const rejected = isVenueLegConfirmedUnfilled(outcome);
  const pendingConfirm = isVenueLegPendingConfirm(outcome);
  // PM 买入层已区分官方未成交和授权超时策略；两者均按现有拒单流程处理。
  if (rejected && result && isPolymarketProvider(account.provider)) {
    try {
      await persistPolymarketExecutionReject(account, result, "unfilled", {
        betOption: opts.betOption,
        linkId: opts.pendingBindLinkId,
      });
    }
    catch {
      /* 拒单落库失败不阻断 settle 回传 */
    }
  }
  return {
    orders: outcome.orders,
    rejected,
    pendingConfirm,
  };
}

/**
 * 跟到已成交 / 未成交。
 * PF：timeout / 仍 pending → 续跟；耗尽仍未知则保持 pendingConfirm。
 * PM：核验耗尽按授权策略退出；已有成交证据但数量矛盾的异常保留续查。
 * 非 pending-confirm 馆：一轮即返回。
 */
export async function settleArbLegUntilTerminal(
  account: PlatformAccount,
  result?: BetResult,
  rejectWaitSecOrOpts?: number | SettleArbLegOpts,
): Promise<ArbLegSettleResult> {
  const needFollow = isPredictFunProvider(account.provider) && Boolean(result);
  const rounds = needFollow ? PENDING_CONFIRM_FOLLOW_ROUNDS : 1;
  let last: ArbLegSettleResult = { orders: [], rejected: false, pendingConfirm: false };
  for (let round = 0; round < rounds; round++) {
    last = await settleArbLeg(account, result, rejectWaitSecOrOpts);
    if (!last.pendingConfirm)
      return last;
    if (round < rounds - 1)
      await wait(PENDING_CONFIRM_FOLLOW_GAP_MS * (round + 1));
  }
  return last;
}

import type { BetOption } from "@changmen/client-core/models/betOption";
import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import type { ArbBetAttemptParams, ArbBetPlaced } from "@/stores/betting/autoBet/phases/types";
import { isPendingConfirmVenueProvider, isPolymarketProvider } from "@changmen/shared/account_multiply";
import { pmSubmissionFromResult } from "@changmen/shared/pm_submission";
import { LoseOrder } from "@/models/loseOrder";
import { arbMakeUpSides } from "@/stores/betting/autoBet/arbMakeUpPair";
import { enqueueMakeUpOrder } from "@/stores/betting/autoBet/makeUp";
import { resolveMakeUpSuccessReference } from "@/stores/betting/makeUpReference";
import { useLoseOrderStore } from "@/stores/loseOrderStore";

/** [A8 可证实] LoseOrder 用成功腿 option 的 betMoney/odds，不用场馆实单 */
function a8SuccessLegRef(leg: BetOption): { betMoney: number; betOdds: number } {
  return {
    betMoney: Math.round(Number(leg.betMoney) || 0),
    betOdds: Number(leg.odds) || 0,
  };
}

/** 成功腿锚点的唯一解析口径；旁路延迟拒单也复用，避免产生第二套补单计算。 */
export function resolveArbMakeUpSuccessRef(
  leg: BetOption,
  orders: VenueOrder[],
  rejected: boolean,
  account?: PlatformAccount,
  orderId?: string | null,
): { betMoney: number; betOdds: number } {
  if (account && isPendingConfirmVenueProvider(account.provider))
    return resolveMakeUpSuccessReference(leg, orders, rejected, account, orderId);
  return a8SuccessLegRef(leg);
}

export interface ArbMakeUpVenueContext {
  ordersA: VenueOrder[];
  ordersB: VenueOrder[];
}

export interface ArbMakeUpEnqueueResult {
  enqueuedForLegA: boolean;
  enqueuedForLegB: boolean;
}

export interface ArbMakeUpPendingConfirm {
  pendingConfirmA?: boolean;
  pendingConfirmB?: boolean;
}

/** 编排层判定需补单后入队（不看 makeUp 开关）；赔率/初赔阈值在 enqueue 内按败腿价走 A8 `B()` */
export async function applyArbMakeUpFromRejects(
  params: ArbBetAttemptParams,
  placed: ArbBetPlaced,
  rejectA: boolean,
  rejectB: boolean,
  venue: ArbMakeUpVenueContext = { ordersA: [], ordersB: [] },
  pending: ArbMakeUpPendingConfirm = {},
): Promise<ArbMakeUpEnqueueResult> {
  const { match, bet, config, setMessage } = params;
  // [A8 可证实] 入队不看 makeUp；消费段 `orders && config.makeUp` 才 jb
  const loseStore = useLoseOrderStore();
  const {
    legA,
    legB,
    accountA,
    accountB,
    betBothLegs,
    linkId,
    resultA,
    resultB,
  } = placed;
  const result: ArbMakeUpEnqueueResult = {
    enqueuedForLegA: false,
    enqueuedForLegB: false,
  };

  if (!betBothLegs)
    return result;

  const pendingConfirmA = Boolean(pending.pendingConfirmA);
  const pendingConfirmB = Boolean(pending.pendingConfirmB);

  // pending target：另一腿已成交，pending 未成交后补 pending 腿。
  // pending anchor：另一腿已失败，pending 成交后补另一腿；pending 未成交则无敞口结束。
  const resumePending = async (
    pendingSide: "A" | "B",
    role: "target" | "anchor",
  ): Promise<boolean> => {
    const pendingResult = pendingSide === "A" ? resultA : resultB;
    const pendingAccount = pendingSide === "A" ? accountA : accountB;
    const pendingLeg = pendingSide === "A" ? legA : legB;
    const otherLeg = pendingSide === "A" ? legB : legA;
    const otherOrders = pendingSide === "A" ? venue.ordersB : venue.ordersA;
    const otherReject = pendingSide === "A" ? rejectB : rejectA;
    const otherAccount = pendingSide === "A" ? accountB : accountA;
    const otherResult = pendingSide === "A" ? resultB : resultA;
    const orderId = String(pendingResult?.orderId ?? "").trim();
    if (!pendingAccount || !orderId)
      return false;
    if (!isPendingConfirmVenueProvider(pendingAccount.provider))
      return false;
    const makeupTargetLeg = role === "target" ? pendingLeg : otherLeg;
    const successLeg = role === "target" ? otherLeg : pendingLeg;
    const successOrders = role === "target"
      ? otherOrders
      : (pendingSide === "A" ? venue.ordersA : venue.ordersB);
    const successRejected = role === "target" ? otherReject : false;
    const successAccount = role === "target" ? otherAccount : pendingAccount;
    const successResult = role === "target" ? otherResult : pendingResult;
    if (!successAccount)
      return false;
    if (loseStore.orders.has(bet.id)) {
      loseStore.setPendingVenueOrder(bet.id, orderId, pendingAccount.accountId, {
        role,
        observation: pendingLeg.observation,
        pendingTarget: pendingLeg.target,
        conditionId: pendingLeg.betId,
        submittedAt: pendingResult?.beginTime,
        pmSubmission: isPolymarketProvider(pendingAccount.provider) ? pmSubmissionFromResult(pendingResult, pendingAccount.accountId) : null,
        odds: pendingLeg.newOdds || pendingLeg.odds,
        betMoney: pendingLeg.betMoney,
        error: isPolymarketProvider(pendingAccount.provider) ? pendingResult?.message || "PM 核验窗口结束，未取得终态" : undefined,
      });
      return true;
    }
    const successRef = resolveMakeUpSuccessReference(
      successLeg,
      successOrders,
      successRejected,
      successAccount,
      successResult?.orderId,
    );
    const enqueued = await enqueueMakeUpOrder({
      loseStore,
      match,
      bet,
      config,
      setMessage,
      linkId,
      accountId: successAccount.accountId,
      target: makeupTargetLeg.target,
      betMoney: successRef.betMoney,
      betOdds: successRef.betOdds,
      failedLegOdds: makeupTargetLeg.odds,
      failedPlatformLabel: `${makeupTargetLeg.type}(待确认续查)`,
      observation: { executionId: successLeg.observation?.executionId, parentAttemptId: successLeg.observation?.attemptId, ownerUserId: successLeg.observation?.ownerUserId, anchorAttemptId: successLeg.observation?.attemptId, anchorOrderId: successResult?.orderId || undefined },
    });
    // delayed 原单必须继续观察，即使补单赔率门槛不允许后续补单。
    if (!enqueued) {
      loseStore.createOrder(new LoseOrder({
        accountId: successAccount.accountId,
        matchId: match.id,
        betId: bet.id,
        target: makeupTargetLeg.target,
        betMoney: successRef.betMoney,
        betOdds: successRef.betOdds,
        match: match.title,
        bet: bet.getBetName(),
        linkId,
        createAt: Date.now(),
        isCreateOrder: false,
        betCount: 1,
      }));
    }
    loseStore.setPendingVenueOrder(bet.id, orderId, pendingAccount.accountId, {
      role,
      observation: pendingLeg.observation,
      pendingTarget: pendingLeg.target,
      conditionId: pendingLeg.betId,
      submittedAt: pendingResult?.beginTime,
      pmSubmission: isPolymarketProvider(pendingAccount.provider) ? pmSubmissionFromResult(pendingResult, pendingAccount.accountId) : null,
      odds: pendingLeg.newOdds || pendingLeg.odds,
      betMoney: pendingLeg.betMoney,
      error: isPolymarketProvider(pendingAccount.provider) ? pendingResult?.message || "PM 核验窗口结束，未取得终态" : undefined,
      makeUpEligible: enqueued,
    });
    return true;
  };

  if (pendingConfirmA && !pendingConfirmB) {
    const role = resultB?.success && !rejectB ? "target" : "anchor";
    const queued = await resumePending("A", role);
    if (role === "target")
      result.enqueuedForLegA = queued;
    else
      result.enqueuedForLegB = queued;
    return result;
  }
  if (pendingConfirmB && !pendingConfirmA) {
    const role = resultA?.success && !rejectA ? "target" : "anchor";
    const queued = await resumePending("B", role);
    if (role === "target")
      result.enqueuedForLegB = queued;
    else
      result.enqueuedForLegA = queued;
    return result;
  }

  const side = arbMakeUpSides(
    resultA,
    rejectA,
    resultB,
    rejectB,
    pendingConfirmA,
    pendingConfirmB,
  );

  if (side === "enqueueB" && accountA) {
    const successRef = resolveArbMakeUpSuccessRef(
      legA,
      venue.ordersA,
      rejectA,
      accountA,
      resultA?.orderId,
    );
    result.enqueuedForLegB = await enqueueMakeUpOrder({
      loseStore,
      match,
      bet,
      config,
      setMessage,
      linkId,
      accountId: accountA.accountId,
      target: legB.target,
      betMoney: successRef.betMoney,
      betOdds: successRef.betOdds,
      failedLegOdds: legB.odds,
      failedPlatformLabel: legB.type,
      observation: { executionId: legA.observation?.executionId, parentAttemptId: legA.observation?.attemptId, ownerUserId: legA.observation?.ownerUserId, anchorAttemptId: legA.observation?.attemptId, anchorOrderId: resultA?.orderId || undefined },
    });
  }
  else if (side === "enqueueA" && accountB) {
    const successRef = resolveArbMakeUpSuccessRef(
      legB,
      venue.ordersB,
      rejectB,
      accountB,
      resultB?.orderId,
    );
    result.enqueuedForLegA = await enqueueMakeUpOrder({
      loseStore,
      match,
      bet,
      config,
      setMessage,
      linkId,
      accountId: accountB.accountId,
      target: legA.target,
      betMoney: successRef.betMoney,
      betOdds: successRef.betOdds,
      failedLegOdds: legA.odds,
      failedPlatformLabel: legA.type,
      observation: { executionId: legB.observation?.executionId, parentAttemptId: legB.observation?.attemptId, ownerUserId: legB.observation?.ownerUserId, anchorAttemptId: legB.observation?.attemptId, anchorOrderId: resultB?.orderId || undefined },
    });
  }

  return result;
}

import type { BetOption } from "@changmen/client-core/models/betOption";
