import { recordPmExecutionMetric } from "@changmen/venue-adapter/polymarket";
import { capturePmFokPreflightMode, prepareOptimizedFokExecution } from "@changmen/venue-adapter/polymarket";
import type { BetOption } from "@changmen/client-core/models/betOption";
import type {
  ArbBetAttemptParams,
  ArbBetChecked,
  ArbBetReady,
} from "@/stores/betting/autoBet/phases/types";
import { wait } from "@changmen/client-core/shared/wait";
import { getPolymarketPmSportBlockReasonFromOption } from "@changmen/venue-adapter/polymarket";
import { PLATFORMS } from "@changmen/venue-adapter/shared";
import { isSingleLegPrecheckOnly } from "@/domain/betting/singleLegRate";
import { shouldSkipAccountRateOnStakeScale } from "@/extensions/arbBet/stakeScaleByProfit";
import { createObservationContext, observeOption } from "@/services/orderObservation";
import { observeArbSubmissionBlocked } from "@/services/orderExecutionObservation";
import { a8Tip } from "@/shared/a8Notify";
import { buildArbProgressLegPair } from "@/shared/arbProgressLegMeta";
import { arbBetToastSeconds } from "@/shared/betTiming";
import { useAccountStore } from "@/stores/accountStore";
import {
  scheduleActiveBetRunRemoval,
  syncActiveBetFail,
  syncActiveBetPhase,
  syncActiveBetPrecheckResults,
} from "@/stores/betting/activeBetRunSync";
import { setArbExecutionTraceMeta } from "@/stores/betting/autoBet/arbProgressTrace";
import { useLoseOrderStore } from "@/stores/loseOrderStore";
import { useUserStore } from "@/stores/userStore";

function stripPrecheckError(raw?: string): string {
  if (!raw)
    return "";
  return raw.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
}

function resolveSkipAccountRate(
  side: "A" | "B",
  ready: ArbBetReady,
): boolean {
  if (isSingleLegPrecheckOnly(
    side,
    ready.accountA,
    ready.accountB,
    ready.checkAccountA,
    ready.checkAccountB,
  )) {
    return true;
  }
  return shouldSkipAccountRateOnStakeScale(
    ready.stakeScale,
    useUserStore().extensionPrefs.stakeScaleByProfit,
  );
}

/** 预检双腿；失败时 trace.finish 并返回 null */
export async function checkArbLegs(
  params: ArbBetAttemptParams,
  ready: ArbBetReady,
): Promise<ArbBetChecked | null> {
  const { bet, config, setMessage, trace } = params;
  const accountStore = useAccountStore();
  let {
    legA,
    legB,
    accountA,
    accountB,
    checkAccountA,
    checkAccountB,
    betBothLegs,
  } = ready;
  checkAccountA = checkAccountA ?? accountA;
  checkAccountB = checkAccountB ?? accountB;
  for (const leg of [legA, legB]) {
    leg.diagnosticLinkId = ready.linkId;
    leg.diagnosticAttempt = "initial";
    leg.observation ??= createObservationContext();
  }

  // [changmen 扩展] 原单核验异常时阻止该账号继续积累未知敞口；恢复后自动解除。
  const blocked = [...useLoseOrderStore().orders.values()].some(order =>
    order.pendingVenueOrderId && order.pendingVenueError
    && [checkAccountA, checkAccountB].some(account => account?.accountId === order.pendingVenueAccountId));
  if (blocked) {
    const reason = "PM 原单确认异常，暂停该账号新增套利";
    observeOption(legA, checkAccountA, "decision", { outcome: "blocked", reasonCode: "pending_anchor_error" });
    observeOption(legB, checkAccountB, "decision", { outcome: "blocked", reasonCode: "pending_anchor_error" });
    trace?.finish("fail", reason);
    setMessage(reason);
    syncActiveBetFail(bet.id, reason);
    return null;
  }

  // [changmen 扩展] 只为动态 FOK 的真实执行腿准备；此时传统腿尚未检查，不占用其报价有效窗口。
  const preparing = ready.pmOrderMode === "GTC" ? [] : [[accountA, legA], [accountB, legB]] as const;
  const dynamicAccounts = preparing.flatMap(([account, leg]) => account?.provider === "Polymarket"
    && capturePmFokPreflightMode(leg) === "optimized" ? [account] : []);
  if (dynamicAccounts.length) {
    syncActiveBetPhase(bet.id, "checking", "准备 PM 提交环境");
    try { await Promise.all(dynamicAccounts.map(account => prepareOptimizedFokExecution(account, ready.linkId))); }
    catch (error) {
      const reason = error instanceof Error ? error.message : "PM 提交准备失败";
      observeArbSubmissionBlocked(ready, "pm_preparation_failed", reason);
      setMessage(reason); trace?.finish("fail", reason); syncActiveBetFail(bet.id, reason);
      return null;
    }
  }
  syncActiveBetPhase(bet.id, "checking", "正在预检");

  if (checkAccountA)
    checkAccountA.active = true;
  if (checkAccountB)
    checkAccountB.active = true;

  for (const [account, leg, side] of [
    [checkAccountA, legA, "A"] as const,
    [checkAccountB, legB, "B"] as const,
  ]) {
    if (!account || leg.type !== PLATFORMS.Polymarket)
      continue;
    const pmBlock = getPolymarketPmSportBlockReasonFromOption(leg);
    if (pmBlock) {
      observeOption(leg, account, "decision", { outcome: "blocked", reasonCode: "pm_market_gate" });
      trace?.finish("fail", `${leg.type} ${leg.target}: ${pmBlock}`);
      syncActiveBetPrecheckResults(bet.id, {
        hasA: side === "A",
        okA: false,
        detailA: side === "A" ? pmBlock : undefined,
        hasB: side === "B",
        okB: false,
        detailB: side === "B" ? pmBlock : undefined,
      });
      scheduleActiveBetRunRemoval(bet.id);
      await wait(1000);
      return null;
    }
  }

  const checkStart = Date.now();
  const pairStart = performance.now();
  const scanOddsA = Number(legA.odds) || 0;
  const scanOddsB = Number(legB.odds) || 0;
  legA.diagnosticLinkId = ready.linkId;
  legB.diagnosticLinkId = ready.linkId;
  legA.diagnosticAttempt = "initial";
  legB.diagnosticAttempt = "initial";

  const taskA = checkAccountA
    ? accountStore.checkBetting(checkAccountA, legA, {
        ...(legA.type === "Polymarket" ? { requireClobConfirmation: true } : {}),
        ...(dynamicAccounts.includes(checkAccountA) ? { pmDynamicPrepared: true as const } : {}),
        role: isSingleLegPrecheckOnly("A", accountA, accountB, checkAccountA, checkAccountB) ? "precheckOnly" : "execute",
        skipAccountRate: resolveSkipAccountRate("A", ready),
        ...(legA.type === "Polymarket" && ready.pmOrderMode === "GTC" ? { pmOrderMode: ready.pmOrderMode } : {}),
      })
    : undefined;
  const taskB = checkAccountB
    ? accountStore.checkBetting(checkAccountB, legB, {
        ...(legB.type === "Polymarket" ? { requireClobConfirmation: true } : {}),
        ...(dynamicAccounts.includes(checkAccountB) ? { pmDynamicPrepared: true as const } : {}),
        role: isSingleLegPrecheckOnly("B", accountA, accountB, checkAccountA, checkAccountB) ? "precheckOnly" : "execute",
        skipAccountRate: resolveSkipAccountRate("B", ready),
        ...(legB.type === "Polymarket" && ready.pmOrderMode === "GTC" ? { pmOrderMode: ready.pmOrderMode } : {}),
      })
    : undefined;

  const checked = await Promise.all([taskA, taskB].filter(Boolean) as Promise<BetOption>[]);
  if ([legA.type, legB.type].includes("Polymarket")) recordPmExecutionMetric({
    kind: "pair_check", ms: performance.now() - pairStart, success: checked.every(leg => Boolean(leg.data) && !leg.checkError),
  });
  let checkIdx = 0;
  if (checkAccountA)
    legA = checked[checkIdx++];
  if (checkAccountB)
    legB = checked[checkIdx++];

  const precheckLegs = buildArbProgressLegPair(
    legA,
    legB,
    checkAccountA,
    checkAccountB,
    {
      legA: checkAccountA
        ? { ok: Boolean(legA.data), error: legA.checkError }
        : undefined,
      legB: checkAccountB
        ? { ok: Boolean(legB.data), error: legB.checkError }
        : undefined,
    },
    trace?.getMeta()?.legs,
  );
  setArbExecutionTraceMeta(trace, { legs: precheckLegs });
  trace?.event("预检", "见下方对冲腿详情");

  function legPrecheckFailLabel(side: "A" | "B"): string | null {
    const leg = side === "A" ? legA : legB;
    const checkAccount = side === "A" ? checkAccountA : checkAccountB;
    if (!checkAccount || leg.data)
      return null;
    const base = `${leg.type} ${leg.target}: ${leg.checkError || "无盘口数据"}`;
    if (isSingleLegPrecheckOnly(side, accountA, accountB, checkAccountA, checkAccountB))
      return `${base}（9999仅预检）`;
    return base;
  }

  const dualPrecheckFailed = (checkAccountA && !legA.data) || (checkAccountB && !legB.data);

  if (dualPrecheckFailed) {
    const parts = [
      legPrecheckFailLabel("A"),
      legPrecheckFailLabel("B"),
    ].filter(Boolean);
    syncActiveBetPrecheckResults(bet.id, {
      hasA: Boolean(checkAccountA),
      okA: Boolean(checkAccountA && legA.data),
      detailA: checkAccountA && !legA.data
        ? (stripPrecheckError(legA.checkError) || "无盘口数据")
        : undefined,
      hasB: Boolean(checkAccountB),
      okB: Boolean(checkAccountB && legB.data),
      detailB: checkAccountB && !legB.data
        ? (stripPrecheckError(legB.checkError) || "无盘口数据")
        : undefined,
    });
    trace?.finish("fail", parts.join(" · ") || "预检未通过");
    scheduleActiveBetRunRemoval(bet.id);
    await wait(1000);
    return null;
  }

  // [changmen 扩展] 历史在选号前恢复；GTC 签单、利润及执行准备完成后才报告双腿通过。
  if (ready.pmOrderMode === "GTC" && [legA.type, legB.type].includes("Polymarket")) {
    try {
      const { prepareGtcLegExecution } = await import("@/orderModes/gtc/arbLeg");
      ready.originalExecution = params.originalExecution = await prepareGtcLegExecution(params, {
        ...ready, legA, legB, accountA, accountB, scanOddsA, scanOddsB,
        precheckCompletedAt: performance.now(),
        waitSec: arbBetToastSeconds(config, [accountA?.provider, accountB?.provider].filter(Boolean) as string[]),
      });
      for (const execution of ready.originalExecution.legs.values()) execution.validate();
    }
    catch (error) {
      const reason = error instanceof Error ? error.message : "GTC 发送准备失败";
      observeArbSubmissionBlocked({ ...ready, legA, legB }, "pair_preparation_failed", reason);
      setMessage(reason); trace?.finish("fail", reason); syncActiveBetFail(bet.id, reason);
      return null;
    }
  }

  syncActiveBetPrecheckResults(bet.id, {
    hasA: Boolean(checkAccountA),
    okA: true,
    hasB: Boolean(checkAccountB),
    okB: true,
  });

  // [A8 可证实] 预检通过后不再改 betMoney（PM 同：计划额 + 场馆跌价拒单）；orderIndex 在 checkTimeout 之前赋值
  if (accountA)
    legA.orderIndex = 1;
  if (accountB)
    legB.orderIndex = betBothLegs ? 2 : 1;
  if (config.checkTimeout && Date.now() - checkStart > config.checkTimeout) {
    const elapsed = Date.now() - checkStart;
    const msg = `超时时间：${elapsed}ms，大于设定值：${config.checkTimeout}ms`;
    observeArbSubmissionBlocked({ ...ready, legA, legB }, "precheck_timeout", msg);
    setMessage(`前置检查超时 ${elapsed}ms`);
    a8Tip("前置检查超时", msg, 3000);
    trace?.finish("fail", msg);
    syncActiveBetFail(bet.id, msg);
    return null;
  }

  const waitSec = arbBetToastSeconds(
    config,
    [accountA?.provider, accountB?.provider].filter(Boolean) as string[],
  );

  return {
    ...ready,
    precheckCompletedAt: performance.now(),
    legA,
    legB,
    accountA,
    accountB,
    implied: ready.implied,
    waitSec,
    scanOddsA,
    scanOddsB,
  };
}

