    const fixture = makeFixture(["Polymarket", "RAY"], "GTC", history);
    seedHistory(fixture, history, true);
    const alternatives = fixture.accounts.map(account => {
      const other = new PlatformAccount({ provider: account.provider, accountId: account.accountId + 10, playerName: "alternative", currency: "CNY", maxBetCount: account.maxBetCount, lastOdds: account.lastOdds });
      other.balance = 1000; return other;
    });
    state.store.accounts.push(...alternatives);
    const ready = await prepareArbAttempt(fixture.params);
    expect(ready?.accountA).toBe(alternatives[0]);
    expect(ready?.accountB).toBe(alternatives[1]);
  });
  it("skips selection while recovery is pending, then uses newly scanned odds", async () => {
    const fixture = makeFixture(["Polymarket", "RAY"], "GTC", "odds");
    state.historyStatus.mockReturnValueOnce("GTC 本盘口历史恢复中，等待重新选号");
    expect(await prepareArbAttempt(fixture.params)).toBeNull();
    expect(state.store.providerPickIndex.size).toBe(0);
    fixture.legs[0]!.odds = 2.5;
    markGtcSuccess("owner", 1, fixture.params.bet.id, "Home", 2.1);
    expect((await prepareArbAttempt(fixture.params))?.legA.odds).toBe(2.5);
  });
});

function makeFixture(providers: readonly PlatformId[], mode: "FOK" | "GTC", history: typeof histories[number]) {
  const accounts = providers.map((provider, index) => {
    const account = new PlatformAccount({ provider, accountId: index + 1, playerName: `p${index}`, currency: "CNY" });
    account.balance = 1000;
    account.maxBetCount = history === "count" ? 1 : 0;
    account.lastOdds = history === "odds";
    return account;
  });
  state.store = { accounts, loaded: true, providerPickIndex: new Map() } as AccountStoreContext;
  const legs = providers.map((type, index) => ({ type, target: index === 0 ? "Home" : "Away", odds: 2, betMoney: 100 })) as BetOption[];
  const bet = { id: ++betId, items: [], getOrderOptions: () => legs } as unknown as ViewBet;
  const config = { ...createDefaultUserConfig(), minMoney: 0, maxMoney: 0, betMoney: 100, profit: 1, noSameBet: history === "opposite" };
  const params = { match: { id: 1, gameId: 1, title: "A vs B", game: "英雄联盟" } as ViewMatch, bet, config, pmOrderMode: mode, setMessage: vi.fn() };
  return { accounts, legs, params };
}

function seedHistory(fixture: ReturnType<typeof makeFixture>, history: typeof histories[number], gtc: boolean) {
  fixture.accounts.forEach((account, index) => {
    const side = fixture.legs[index]!.target;
    const historicalSide = history === "opposite" ? (side === "Home" ? "Away" : "Home") : side;
    if (gtc) markGtcSuccess("owner", account.accountId, fixture.params.bet.id, historicalSide, 2.1);
    else markSuccessfulBet(account, fixture.params.bet.id, historicalSide, 2.1);
  });
}

import type { ArbBetAttemptParams, ArbBetReady } from "@/stores/betting/autoBet/phases/types";
import { prewarmPmSportForCandidate } from "@changmen/venue-adapter/polymarket";
import { capturePmFokPreflightMode } from "@changmen/venue-adapter/polymarket";
import type { PlatformId } from "@/types/esport";
import {
  allowArbBetExecution,
  arbAccountPickerFilter,
  createArbLinkId,
  explainAllowArbRejection,
  explainMissingLegAccount,
  resolveSingleLegByRate,
  resolveSingleLegCheckAccounts,
} from "@/domain/betting/singleLegRate";
import { opponentSide } from "@changmen/client-core/models/betOption";
import { applyStakeScaleByProfit } from "@/extensions/arbBet/stakeScaleByProfit";
import {
  applyValueBetMoneyTo9999LiveLeg,
  resolve9999LiveSide,
} from "@/extensions/arbBet/singleLeg9999Stake";
import {
  getSingleLeg9999MapCountForKeys,
  hasSingleLeg9999OppositeSourceSide,
  releaseSingleLeg9999MapFillKeys,
  reserveSingleLeg9999MapFillKeys,
  singleLeg9999MapKey,
  singleLeg9999SourceMarketKey,
  singleLeg9999SourceSideKey,
} from "@/extensions/arbBet/singleLeg9999MapCount";
import { formatLegAccount } from "@/shared/arbBetTraceFormat";
import { buildArbProgressLegPair } from "@/shared/arbProgressLegMeta";
import { accountsFundingReady } from "@/stores/account/accountPicker";
import { useAccountStore } from "@/stores/accountStore";
import { ensureArbExecutionTrace, setArbExecutionTraceMeta } from "@/stores/betting/autoBet/arbProgressTrace";
import { syncActiveBetBegin } from "@/stores/betting/activeBetRunSync";
import { readUsedAccounts } from "@/stores/betting/successMarkers";
import { useLoseOrderStore } from "@/stores/loseOrderStore";
import { useMatchStore } from "@/stores/matchStore";
import { filterArbProviderKeys } from "@/types/extensionPrefs";
import { useUserStore } from "@/stores/userStore";

/** 选腿、选号、比例 9999 单边 / linkId；失败时 return null（A8 静默 continue） */
export async function prepareArbAttempt(
  params: ArbBetAttemptParams,
): Promise<ArbBetReady | null> {
  const { match, bet, config } = params;
  const matchStore = useMatchStore();
  const accountStore = useAccountStore();
  const loseStore = useLoseOrderStore();
  const userStore = useUserStore();

  bet.items.forEach(item => item.updateOdds());

  const accounts = accountStore.accounts;

  if (!accountsFundingReady(accountStore)) {
    return null;
  }

  if (loseStore.orders.has(bet.id)) {
    return null;
  }

  // [A8 可证实] 每个 bet 循环内 roll（非每轮一次）
  if (config.minMoney !== 0 && config.maxMoney !== 0) {
    config.betMoney
      = Math.floor(Math.random() * (config.maxMoney - config.minMoney + 1)) + config.minMoney;
  }

  const funded = [...accountStore.getProviders(config.betMoneyMode === "total" ? 0 : config.betMoney).keys()] as PlatformId[];
  // [changmen 扩展] 扩展 Tab 套利场馆白名单；null = 不限制（现网）
  const providerKeys = filterArbProviderKeys(funded, userStore.extensionPrefs.arbAllowedPlatforms);

  const options = bet.getOrderOptions(match, config, accounts, providerKeys);
  if (!options || options.length !== 2) {
    return null;
  }

  ensureArbExecutionTrace(params);
  const trace = params.trace;

  const legA = options[0];
  const legB = options[1];
  // [changmen 扩展] FOK 冻结方式；只有 GTC 仍需 Gamma 候选预热。
  for (const leg of options) {
    if (leg.type !== "Polymarket") continue;
    if (params.pmOrderMode === "GTC") prewarmPmSportForCandidate(leg);
    else capturePmFokPreflightMode(leg);
  }
  const pmOrderMode = params.pmOrderMode === "GTC" && options.some(leg => leg.type === "Polymarket") ? "GTC" : undefined;
  // [changmen 扩展] 仅 PM GTC 读取独立历史；原选号过滤和 FOK 状态保持不变。
  let gtcHistoryFilter: ((account: typeof accounts[number], leg: typeof legA) => boolean) | undefined;
  if (pmOrderMode === "GTC") {
    const { gtcSelectionHistoryStatus, gtcHistoryAllowsAccount } = await import("@/orderModes/gtc/selectionHistory");
    const owner = String(userStore.userId);
    const candidates = accounts.filter(account => options.some(leg => leg.type === account.provider));
    const historyStatus = gtcSelectionHistoryStatus(owner, bet.id, candidates, config.noSameBet);
    if (historyStatus) {
      params.setMessage(historyStatus);
      trace?.finish("skip", historyStatus);
      return null;
    }
    gtcHistoryFilter = (account, leg) => gtcHistoryAllowsAccount(owner, account, bet.id, leg.target, leg.odds, config.noSameBet);
  }
  // [changmen 扩展] 模式只影响 PM；保留现有 GTC 双腿支持范围，不扩大 9999 组合。
  const implied = 1 / options.reduce((sum, o) => sum + 1 / o.odds, 0);
  // [changmen 扩展] 高利润加仓：仅放大两腿注码，不改 config.betMoney / 对冲比例
  const stakeScale = applyStakeScaleByProfit(
    legA,
    legB,
    implied,
    userStore.extensionPrefs.stakeScaleByProfit,
  );
  const detectionLegs = buildArbProgressLegPair(legA, legB);
  setArbExecutionTraceMeta(trace, {
    implied,
    homeLine: `${legA.type}@${legA.odds}`,
    awayLine: `${legB.type}@${legB.odds}`,
    legs: detectionLegs,
  });
  trace?.event("检测", `平台 ${providerKeys.join("、")}`);
  if (stakeScale !== 1) {
    const scalePrefs = userStore.extensionPrefs.stakeScaleByProfit;
    const scaleDetail = scalePrefs.skipAccountRateOnScale
      ? `利润达阈值，注码 ×${stakeScale}（忽略账号比例）`
      : `利润达阈值，注码 ×${stakeScale}`;
    trace?.event("加仓", scaleDetail);
  }

  // [A8 可证实] `lBe`：GetOrderOptions 后立即 `linkId=Date.now()`（9999 扩展再取负）
  const linkTs = Date.now();

  const accountA = accountStore.getAccount(
    legA.type,
    legA.betMoney,
    config.noSameBet ? readUsedAccounts(bet.id, opponentSide(legA.target)) : [],
    acc => arbAccountPickerFilter(acc, bet, match, legA, matchStore, implied) && (!gtcHistoryFilter || gtcHistoryFilter(acc, legA)),
    options,
  );
  const accountB = accountStore.getAccount(
    legB.type,
    legB.betMoney,
    config.noSameBet ? readUsedAccounts(bet.id, opponentSide(legB.target)) : [],
    acc => arbAccountPickerFilter(acc, bet, match, legB, matchStore, implied) && (!gtcHistoryFilter || gtcHistoryFilter(acc, legB)),
    options,
  );
  if (!accountA && !accountB) {
    trace?.finish("fail", "无可用账号");
    return null;
  }

  if (accountA) {
    trace?.event("选号", `${legA.target} ${formatLegAccount(legA.type, accountA.playerName)}`);
  }
  if (accountB) {
    trace?.event("选号", `${legB.target} ${formatLegAccount(legB.type, accountB.playerName)}`);
  }
  setArbExecutionTraceMeta(trace, {
    legs: buildArbProgressLegPair(legA, legB, accountA, accountB, undefined, detectionLegs),
  });

  const betBothLegs = Boolean(accountA) && Boolean(accountB);
  if (pmOrderMode === "GTC" && (!betBothLegs || options.filter(leg => leg.type === "Polymarket").length !== 1)) {
    trace?.finish("skip", "PM GTC 当前只支持一条 PM 腿的双边套利");
    return null;
  }
  const excludeA = config.noSameBet ? readUsedAccounts(bet.id, opponentSide(legA.target)) : [];
  const excludeB = config.noSameBet ? readUsedAccounts(bet.id, opponentSide(legB.target)) : [];
  const singleLegByRate = resolveSingleLegByRate({
    betBothLegs,
    accountA,
    accountB,
    legA,
    legB,
    bet,
    match,
    accounts: accountStore.accounts,
    excludeA,
    excludeB,
    matchStore,
    implied,
  });

  if (!allowArbBetExecution(betBothLegs, singleLegByRate)) {
    const missingAReason = accountA
      ? undefined
      : explainMissingLegAccount(
          legA,
          bet,
          match,
          accounts,
          excludeA,
          matchStore,
          implied,
        );
    const missingBReason = accountB
      ? undefined
      : explainMissingLegAccount(
          legB,
          bet,
          match,
          accounts,
          excludeB,
          matchStore,
          implied,
        );
    trace?.finish(
      "skip",
      explainAllowArbRejection({
        betBothLegs,
        singleLegByRate,
        accountA,
        accountB,
        legA,
        legB,
        missingAReason,
        missingBReason,
      }),
    );
    return null;
  }

  let singleLeg9999MapReserved = false;
  let singleLeg9999MapKeys: string[] | undefined;
  if (singleLegByRate) {
    trace?.event("模式", "比例 9999 单边（本侧仅预检不下单）");
    const prefs = userStore.extensionPrefs;
    const maxPerMap = Number(prefs.singleLeg9999MaxPerMap) || 1;
    const liveSide = resolve9999LiveSide(accountA, accountB);
    const liveLeg = liveSide === "A" ? legA : liveSide === "B" ? legB : undefined;
    const liveSourceKey = liveLeg
      ? singleLeg9999SourceMarketKey(liveLeg.type, liveLeg.matchId, liveLeg.betId)
      : null;
    const liveSideKey = singleLeg9999SourceSideKey(liveSourceKey, liveLeg?.target ?? "");
    if (liveLeg && hasSingleLeg9999OppositeSourceSide(liveSourceKey, liveLeg.target)) {
      trace?.finish("skip", "9999 同盘口已下过对侧");
      return null;
    }
    singleLeg9999MapKeys = [
      singleLeg9999MapKey(match.id, bet.round),
      singleLeg9999SourceMarketKey(legA.type, legA.matchId, legA.betId),
      singleLeg9999SourceMarketKey(legB.type, legB.matchId, legB.betId),
      liveSideKey,
    ].filter(Boolean) as string[];
    const mapCount = getSingleLeg9999MapCountForKeys(singleLeg9999MapKeys);
    if (mapCount >= maxPerMap) {
      trace?.finish("skip", `9999 同图次数已满（${mapCount}/${maxPerMap}）`);
      return null;
    }
    singleLeg9999MapReserved = reserveSingleLeg9999MapFillKeys(singleLeg9999MapKeys, maxPerMap);
    if (!singleLeg9999MapReserved) {
      trace?.finish("skip", `9999 同图次数已满（${maxPerMap}/${maxPerMap}）`);
      return null;
    }
    const stake = applyValueBetMoneyTo9999LiveLeg({
      singleLegByRate,
      enabled: prefs.singleLeg9999UseValueBetMoney === true,
      config,
      legA,
      legB,
      liveSide,
    });
    if (stake != null) {
      trace?.event("注码", `9999 真下单腿改用正EV金额 ¥${stake}`);
      const liveAcc = liveSide === "A" ? accountA : accountB;
      const bal = liveAcc?.getBalance();
      if (bal !== undefined && liveLeg && bal < liveLeg.betMoney) {
        releaseSingleLeg9999MapFillKeys(singleLeg9999MapKeys);
        trace?.finish(
          "fail",
          `正EV金额余额不足（${Math.floor(bal)} < ${Math.ceil(liveLeg.betMoney)}）`,
        );
        return null;
      }
    }
  }

  const { checkAccountA, checkAccountB } = resolveSingleLegCheckAccounts({
    singleLegByRate,
    precheck9999Leg: userStore.extensionPrefs.singleLeg9999Precheck,
    accountA,
    accountB,
    legA,
    legB,
    bet,
    match,
    accounts: accountStore.accounts,
    excludeA,
    excludeB,
    matchStore,
    implied,
  });

  const linkId = createArbLinkId(singleLegByRate, linkTs);
  syncActiveBetBegin({
    match,
    bet,
    legA,
    legB,
    accountA,
    accountB,
    checkAccountA,
    checkAccountB,
    linkId,
    betBothLegs,
  });

  return {
    ...(pmOrderMode ? { pmOrderMode } : {}),
    legA,
    legB,
    accountA,
    accountB,
    checkAccountA,
    checkAccountB,
    implied,
    betBothLegs,
    singleLegByRate,
    singleLeg9999MapReserved,
    singleLeg9999MapKeys,
    linkId,
    stakeScale,
  };
}

import type { VenueOrder } from "@changmen/venue-adapter/contract";
import type { PlatformAccount } from "@/models/platformAccount";
import type { OriginalLegFacts } from "@/domain/betting/originalLegExecution";
import type {
  ArbBetAttemptParams,
  ArbBetPlaced,
  ArbLegPlaceOutcome,
} from "@/stores/betting/autoBet/phases/types";
import { wait } from "@changmen/client-core/shared/wait";
import { isPendingConfirmVenueProvider } from "@changmen/shared/account_multiply";
import { saveVenueSettlementLog } from "@/services/bettingLog";
import { useAccountStore } from "@/stores/accountStore";
import { syncActiveBetLegSettleResult, syncActiveBetPhase } from "@/stores/betting/activeBetRunSync";
import { bindArbLegOrder, resolveArbBindOrderId } from "@/stores/betting/arbOrderBind";
import { settleArbLegUntilTerminal } from "@/stores/betting/autoBet/arbLegSettle";
import { isArbLegPlaceNeedsSettle } from "@/stores/betting/autoBet/phases/types";
import {
  maxLegRejectWaitSec,
  showRejectDetectionTip,
} from "@/stores/betting/autoBet/rejectWait";
import { enqueuePendingOrderBind } from "@/stores/betting/pendingOrderBind";

export interface ArbLegSettleSnapshot {
  factsA?: OriginalLegFacts;
  factsB?: OriginalLegFacts;
  ordersA: VenueOrder[];
  ordersB: VenueOrder[];
  rejectA: boolean;
  rejectB: boolean;
  pendingConfirmA: boolean;
  pendingConfirmB: boolean;
  /** place 回传；编排用，场馆层不改写 */
  placeOutcomeA: ArbLegPlaceOutcome;
  placeOutcomeB: ArbLegPlaceOutcome;
  boundLegLabels: string[];
  /** [changmen 扩展] Bind 最终失败的腿（已重试；有 orderId 可绑却失败） */
  bindFailedLegLabels: string[];
  bindFailedSides: Array<"A" | "B">;
}

function emptySettleSnapshot(
  placeOutcomeA: ArbLegPlaceOutcome,
  placeOutcomeB: ArbLegPlaceOutcome,
): ArbLegSettleSnapshot {
  return {
    ordersA: [],
    ordersB: [],
    rejectA: false,
    rejectB: false,
    pendingConfirmA: false,
    pendingConfirmB: false,
    placeOutcomeA,
    placeOutcomeB,
    boundLegLabels: [],
    bindFailedLegLabels: [],
    bindFailedSides: [],
  };
}

/** 成功腿：刷余额、空等 max(waitTime??5)、依次 updateOrders（对齐 A8） */
export async function settleBothArbLegs(
  params: ArbBetAttemptParams,
  placed: ArbBetPlaced,
): Promise<ArbLegSettleSnapshot> {
  const { bet, config, trace } = params;
  const accountStore = useAccountStore();
  const {
    legA,
    legB,
    accountA,
    accountB,
    linkId,
    waitSec,
    resultA,
    resultB,
    placeOutcomeA,
    placeOutcomeB,
  } = placed;

  const successAccounts: PlatformAccount[] = [];
  if (resultA?.success && accountA) {
    successAccounts.push(accountA);
    // delayed：CLOB 尚未扣款；早刷若慢于 settle 后补刷，会把旧余额盖回去
    if (!resultA.pending)
      void accountStore.refreshBalance(accountA);
  }
  if (resultB?.success && accountB) {
    successAccounts.push(accountB);
    if (!resultB.pending)
      void accountStore.refreshBalance(accountB);
  }

  if (!successAccounts.length && !resultA?.pmSubmitUnknown && !resultB?.pmSubmitUnknown) {
    // 无 API 成功腿：不进场馆 settle；编排层仍用 placeOutcome 收尾
    if (accountA && !isArbLegPlaceNeedsSettle(placeOutcomeA))
      syncActiveBetLegSettleResult(bet.id, "A", false, false);
    if (accountB && !isArbLegPlaceNeedsSettle(placeOutcomeB))
      syncActiveBetLegSettleResult(bet.id, "B", false, false);
    return emptySettleSnapshot(placeOutcomeA, placeOutcomeB);
  }

  const snapshot = emptySettleSnapshot(placeOutcomeA, placeOutcomeB);
  const original = placed.originalExecution;
  const maxWait = original
    ? Math.max(0, ...[placed.legA, placed.legB].map((leg, index) => (index === 0 ? resultA : resultB)?.success ? original.legs.get(leg)?.rejectWaitSec ?? 0 : 0))
    : maxLegRejectWaitSec(config, successAccounts);
  // [A8 可证实] 普通场馆只要有 API 成功腿就弹 tip，检测等待为 0 也保留原有提示。
  const hasA8Success = successAccounts.some(account => !isPendingConfirmVenueProvider(account.provider));
  if (hasA8Success)
    void showRejectDetectionTip(waitSec);
  // wait=0（含纯 PM）：相位用「确认场馆结果」，不改变 A8 tip 的展示条件。
  if (maxWait > 0) {
    trace?.event("拒单", `空等 ${maxWait}s 后依次拉单`);
    syncActiveBetPhase(bet.id, "settling", "拒单检测", maxWait);
  }
  else {
    trace?.event("拒单", "确认场馆结果（无拒单等待）");
    syncActiveBetPhase(bet.id, "settling", "确认场馆结果");
  }

  // API 失败 / 未下单腿：不上场馆 settle，只回编排态（避免误标「未拒单」）
  if (accountA && !isArbLegPlaceNeedsSettle(placeOutcomeA))
    syncActiveBetLegSettleResult(bet.id, "A", false, false);
  if (accountB && !isArbLegPlaceNeedsSettle(placeOutcomeB))
    syncActiveBetLegSettleResult(bet.id, "B", false, false);

  const settleOne = async (side: "A" | "B"): Promise<void> => {
    const account = side === "A" ? accountA : accountB;
    const result = side === "A" ? resultA : resultB;
    const leg = side === "A" ? legA : legB;
    const placeOutcome = side === "A" ? placeOutcomeA : placeOutcomeB;
    if (!account || !result)
      return;
    const execution = original?.legs.get(leg);
    const synced = execution ? await execution.confirm(result) : await settleArbLegUntilTerminal(account, result, {
      // 编排层已空等 max；场馆层不再 sleep（A8 一次 wait 后立刻 updateOrders）
      rejectWaitSec: 0,
      pendingBindLinkId: linkId,
      betOption: leg,
    });
    if (side === "A") {
      snapshot.ordersA = synced.orders;
      snapshot.rejectA = synced.rejected;
      snapshot.pendingConfirmA = synced.pendingConfirm;
    }
    else {
      snapshot.ordersB = synced.orders;
      snapshot.rejectB = synced.rejected;
      snapshot.pendingConfirmB = synced.pendingConfirm;
    }
    const rejected = synced.rejected;
    saveVenueSettlementLog({
      account,
      option: leg,
      result,
      orders: synced.orders,
      settlement: synced.pendingConfirm ? "timeout" : rejected ? "unfilled" : "filled",
      linkId,
    });
    syncActiveBetLegSettleResult(bet.id, side, true, rejected, {
      pendingConfirm: synced.pendingConfirm,
      provider: account.provider,
      pendingDetail: placeOutcome === "accepted_pending_confirm" ? "已挂单待确认" : "delayed 待确认",
    });
    // [changmen 扩展] RAY 始终使用公共绑单及失败重试；PM 执行副本只记录配对事实。
    if (execution) {
      if (side === "A") snapshot.factsA = execution.facts();
      else snapshot.factsB = execution.facts();
      if (account.provider !== "RAY") {
        if (synced.orders.length) snapshot.boundLegLabels.push(leg.type);
        return;
      }
    }
    if (result.pmSubmitUnknown) return;
    const orderId = resolveArbBindOrderId(synced.orders, result, rejected);
    if (await bindArbLegOrder(linkId, account, result, synced.orders, rejected)) {
      snapshot.boundLegLabels.push(leg.type);
    }
    else if (orderId) {
      snapshot.bindFailedLegLabels.push(leg.type);
      snapshot.bindFailedSides.push(side);
      enqueuePendingOrderBind({
        observation: result.observation,
        target: leg.target,
        linkId,
        provider: result.provider,
        accountId: account.accountId,
        orderId,
        betId: bet.id,
        side,
      });
    }
    if (
      isPendingConfirmVenueProvider(account.provider)
      && result.pending
      && !synced.pendingConfirm
    ) {
      void accountStore.refreshBalance(account);
    }
  };

  const settleA = Boolean((resultA?.success || resultA?.pmSubmitUnknown) && accountA);
  const settleB = Boolean((resultB?.success || resultB?.pmSubmitUnknown) && accountB);
  // [changmen 扩展] 原腿的等待由公共流程完成；含 PF 等确认型场馆，不能提前核对后跳过原等待。
  const pendingA = settleA && isPendingConfirmVenueProvider(accountA!.provider)
    && (!original || (original.legs.get(legA)?.rejectWaitSec ?? 0) === 0);
  const pendingB = settleB && isPendingConfirmVenueProvider(accountB!.provider)
    && (!original || (original.legs.get(legB)?.rejectWaitSec ?? 0) === 0);
  const a8A = settleA && !pendingA;
  const a8B = settleB && !pendingB;

  const pendingTasks: Promise<void>[] = [];
  if (pendingA)
    pendingTasks.push(settleOne("A"));
  if (pendingB)
    pendingTasks.push(settleOne("B"));

  // [A8 可证实] 成功腿 waitTime??5 取 max，空等后再依次 updateOrders
  if (maxWait > 0 && (a8A || a8B))
    await wait(maxWait * 1000);
  if (a8A)
    await settleOne("A");
  if (a8B)
    await settleOne("B");
  await Promise.all(pendingTasks);

  // 仅对已交场馆 settle 的腿报告拒单结果；API 失败/未下单不伪造成「未拒单」
  const rejectLine = (side: "A" | "B") => {
    const account = side === "A" ? accountA : accountB;
    const result = side === "A" ? resultA : resultB;
    const leg = side === "A" ? legA : legB;
    const outcome = side === "A" ? placed.placeOutcomeA : placed.placeOutcomeB;
    const rejected = side === "A" ? snapshot.rejectA : snapshot.rejectB;
    const pending = side === "A" ? snapshot.pendingConfirmA : snapshot.pendingConfirmB;
    if (!account)
      return null;
    if (result?.success) {
      if (pending) {
        return `${leg.type} 待确认`;
      }
      if (rejected)
        return `${leg.type} 🔴拒单`;
      // A8「否」= 未拒单；PM/PF filled 直接报成交
      if (isPendingConfirmVenueProvider(account.provider))
        return `${leg.type} 已成交`;
      return `${leg.type} 否`;
    }
    if (outcome === "not_attempted")
      return `${leg.type} 未下单`;
    const failMsg = String(result?.message ?? "").trim();
    return failMsg || `${leg.type} 下单失败`;
  };

  trace?.event(
    "拒单",
    [rejectLine("A"), rejectLine("B")].filter(Boolean).join(" · "),
  );

  return snapshot;
}

