export type PlaceValueBetFailCode =
  | "gone"
  | "no_account"
  | "rate_9999"
  | "filter"
  | "balance"
  | "check_fail"
  | "place_fail"
  | "busy"
  | "muted"
  | "map_limit";

export type PlaceValueBetResult =
  | {
    ok: true;
    pending: boolean;
    bound: boolean;
    edge: number;
    odds: number;
    type: string;
  }
  | {
    ok: false;
    code: PlaceValueBetFailCode;
    message?: string;
    snap?: ValueBetEdgeSnapshot;
    amount?: number;
  };

let placeInFlight = false;

export function isValueBetPlaceInFlight(): boolean {
  return placeInFlight;
}

export interface ValueBetAutoPlaceGate {
  minEdge: number;
  maxEdge: number;
  minOdds: number;
  maxOdds: number;
  maxPerMap: number;
}

export interface PlaceValueBetParams {
  match: ViewMatch;
  bet: ViewBet;
  item: ViewBetItem;
  side: BetSide;
  amount: number;
  calcOpts: Pick<ValueBetCalcOpts, "sharp" | "softPlatforms">;
  minEdge: number;
  /** 自动下单无 toast；确认下单沿用手动 toast 秒数 */
  silent?: boolean;
  /** 自动：预检前后再核 EV 区间、基准赔率区间、同图次数 */
  autoGate?: ValueBetAutoPlaceGate;
  /** 确认：自动已开时传入同图上限，避免弹窗期间自动先下、确认再下一笔 */
  mapLimit?: number;
}

/**
 * [changmen 扩展] 正 EV 单边落单（确认 / 自动共用）。
 * 不弹窗；调用方按 code 提示。成功后记同图次数并绑 💎。
 */
const PLACE_LOCK_NAME = "changmen-valueBetPlace";

export async function placeValueBetOrder(params: PlaceValueBetParams): Promise<PlaceValueBetResult> {
  const locks = typeof navigator !== "undefined" ? navigator.locks : undefined;
  if (locks?.request) {
    try {
      return await locks.request(PLACE_LOCK_NAME, () => placeValueBetOrderLocked(params));
    }
    catch {
      return placeValueBetOrderLocked(params);
    }
  }
  return placeValueBetOrderLocked(params);
}

async function placeValueBetOrderLocked(params: PlaceValueBetParams): Promise<PlaceValueBetResult> {
  if (placeInFlight)
    return { ok: false, code: "busy", message: "正 EV 下单进行中" };
  placeInFlight = true;
  try {
    return await placeValueBetOrderUnlocked(params);
  }
  finally {
    placeInFlight = false;
  }
}

function failCodeForPlaceBlock(block: ValueBetPlaceBlock): PlaceValueBetFailCode {
  if (block === "muted")
    return "muted";
  if (block === "map_limit")
    return "map_limit";
  if (block === "amount")
    return "place_fail";
  return "gone";
}

function evaluateLivePlaceSafety(
  params: PlaceValueBetParams,
  snap: ValueBetEdgeSnapshot,
): ValueBetPlaceBlock | null {
  const { match, bet, side, amount, minEdge, autoGate, mapLimit } = params;
  const maxPerMap = autoGate?.maxPerMap ?? mapLimit;
  return evaluateValueBetPlaceSafety({
    amount,
    edge: snap.edge,
    minEdge: autoGate?.minEdge ?? minEdge,
    maxEdge: autoGate?.maxEdge,
    muted: isMapMuteActive(match.id, bet.round, match.liveRound)
      || !isPrematchFullMarketAllowed(match, bet),
    checkMute: true,
    mapCount: getValueBetMapCount(match.id, bet.round),
    maxPerMap,
    checkMapLimit: Number.isFinite(maxPerMap),
    sharpOdds: side === "Home" ? snap.sharpHome : snap.sharpAway,
    minOdds: autoGate?.minOdds,
    maxOdds: autoGate?.maxOdds,
    checkOddsRange: autoGate != null,
  });
}

async function placeValueBetOrderUnlocked(params: PlaceValueBetParams): Promise<PlaceValueBetResult> {
  const { match, bet, item, side, amount, calcOpts, minEdge, silent } = params;
  if (!(Number.isFinite(amount) && amount > 0))
    return { ok: false, code: "place_fail", message: "金额无效", amount };

  let snap = computeValueBetEdge(bet, item, side, calcOpts);
  if (!snap || !isValueBetPositiveEdge(snap.edge, minEdge))
    return { ok: false, code: "gone", snap: snap ?? undefined, amount };

  const blocked = evaluateLivePlaceSafety(params, snap);
  if (blocked)
    return { ok: false, code: failCodeForPlaceBlock(blocked), snap, amount };

  const accountStore = useAccountStore();
  const matchStore = useMatchStore();
  const account = accountStore.getAccount(item.type, amount)
    ?? accountStore.getAccount(item.type, 0);
  if (!account)
    return { ok: false, code: "no_account" };
  const bal = account.getBalance();
  if (bal === undefined || bal < amount)
    return { ok: false, code: "balance", message: String(bal) };

  if (isSingleLegRateAtOdds(account, snap.softOdds))
    return { ok: false, code: "rate_9999" };

  let option = new BetOption(match, bet, item, side, amount);
  option.odds = snap.softOdds;
  if (!accountPassesMainBetFilter(account, bet, match, option, matchStore))
    return { ok: false, code: "filter" };

  const toastSec = silent ? 0 : manualBetToastSeconds();
  option = await accountStore.checkBetting(account, option);
  if (!option.data) {
    return {
      ok: false,
      code: "check_fail",
      message: option.checkError ? String(option.checkError) : undefined,
      snap,
      amount,
    };
  }

  const liveSnap = computeValueBetEdge(bet, item, side, calcOpts);
  if (!liveSnap)
    return { ok: false, code: "gone", snap, amount };
  const placeOdds = Number(option.odds);
  const softNow = item.getOdds(side);
  if (!softNow || !Number.isFinite(placeOdds) || placeOdds <= 1)
    return { ok: false, code: "gone", snap: liveSnap, amount };
  const edgeNow = calcEdge(placeOdds, liveSnap.fairOdds);
  snap = { ...liveSnap, softOdds: placeOdds, edge: edgeNow };
  const blockedAfterCheck = evaluateLivePlaceSafety(params, snap);
  if (blockedAfterCheck)
    return { ok: false, code: failCodeForPlaceBlock(blockedAfterCheck), snap, amount };
  if (isSingleLegRateAtOdds(account, placeOdds))
    return { ok: false, code: "rate_9999" };
  option.odds = placeOdds;
  if (!accountPassesMainBetFilter(account, bet, match, option, matchStore))
    return { ok: false, code: "filter" };

  const linkId = createValueBetLinkId();
  const result = await accountStore.betting(account, option, toastSec);
  if (!result?.success) {
    return {
      ok: false,
      code: "place_fail",
      message: result?.message || "下单失败",
      snap,
      amount,
    };
  }

  recordValueBetMapFill(match.id, bet.round);

  const skipMark = isPendingConfirmVenueProvider(account.provider) && result.pending;
  if (!skipMark)
    markSuccessfulBet(account, bet.id, side, option.odds);

  let bound = false;
  try {
    let orders: Awaited<ReturnType<typeof accountStore.updateVenueOrders>> = [];
    const provider = String(account.provider ?? "");
    const optimisticOk = Boolean(
      (result.tip as { pmOptimisticSaved?: boolean } | null | undefined)?.pmOptimisticSaved,
    );
    if (result.pending || provider !== "Polymarket") {
      await wait(result.orderId ? 400 : 1500);
      orders = (await accountStore.updateVenueOrders(account)) ?? [];
    }
    else if (!optimisticOk) {
      await wait(400);
      orders = (await accountStore.updateVenueOrders(account, {
        waitForOrderId: String(result.orderId ?? "").trim() || undefined,
      })) ?? [];
    }
    else {
      orders = (await accountStore.updateVenueOrders(account)) ?? [];
      const oid = String(result.orderId ?? "").trim();
      if (oid && !orders.some(o => String(o.orderId ?? "").trim() === oid)) {
        const synthetic = await buildPolymarketMatchedBuyVenueOrderFromBet(option, result);
        if (synthetic)
          orders = [synthetic, ...orders];
      }
    }
    bound = await bindArbLegOrder(linkId, account, result, orders, false);
    refreshOrderListAfterBind();
  }
  catch {
    bound = false;
  }

  if (!result.pending)
    void accountStore.refreshBalance(account);

  return {
    ok: true,
    pending: Boolean(result.pending),
    bound,
    edge: snap.edge,
    odds: option.odds,
    type: String(item.type),
  };
}

import type { CollectBetDto, CollectConfigDto, CollectMatchDto } from "@changmen/client-core/types/collect";
import type { PlatformId } from "@/types/esport";
import { isVpsOwnedPlatformCollect } from "@changmen/venue-adapter/registry";
import { defineStore } from "pinia";
import { getClientData, saveBetSource, saveClientData, saveMatchSource, saveUserLog } from "@/api/esport";
import { ALL_PLATFORMS } from "@/types/userConfig";

const CONFIG_KEY = "CollectConfig";

/**
 * 对齐 A8 Pinia `Tf`：`collect` 开关只控制是否调用后端 SaveMatch/SaveBets（数据回传），
 * 不控制前端是否向场馆拉数或写入 oddsStore。各采集器应常驻运行，经本 store 上报时才检查开关。
 */
export const useCollectStore = defineStore("collect", {
  state: () => ({
    log: false,
    collect: new Map<PlatformId, boolean>(),
    ready: false,
  }),

  getters: {
    isEnabled: s => (platform: PlatformId) => Boolean(s.collect.get(platform)),
  },

  actions: {
    async init() {
      const raw = await getClientData<CollectConfigDto>(CONFIG_KEY);
      const merged = new Map<PlatformId, boolean>();
      for (const id of ALL_PLATFORMS) {
        merged.set(id, false);
      }
      if (raw?.collect) {
        for (const [id, on] of raw.collect as [PlatformId, boolean][]) {
          merged.set(id, Boolean(on));
        }
      }
      // 无 collect 字段：与 A8 空 Map 一致，全平台 false（不本地默认开 OB/RAY）
      this.collect = merged;
      this.log = Boolean(raw?.log);
      this.ready = true;
    },

    async saveConfig(patch: Partial<{ log: boolean; collect: Map<PlatformId, boolean> }>) {
      if (patch.log !== undefined)
        this.log = patch.log;
      if (patch.collect)
        this.collect = patch.collect;
      const payload: CollectConfigDto = {
        log: this.log,
        collect: [...this.collect.entries()],
      };
      await saveClientData(CONFIG_KEY, JSON.stringify(payload));
    },

    async saveMatch(platform: PlatformId, matchs: CollectMatchDto[]): Promise<boolean> {
      if (isVpsOwnedPlatformCollect(platform))
        return false;
      if (!this.collect.get(platform))
        return false;
      // [A8 可证实] Pinia Af.saveMatch：仅 collect 开关门控，空数组仍 POST API_SaveMatch
      const ok = await saveMatchSource(platform, matchs);
      void this.logCollect(
        `${platform}赛事采集${matchs.length}场 => ${ok}`,
        matchs.map(m => ({ matchId: m.SourceMatchID, game: m.SourceGameID, startTime: m.StartTime, title: `${m.Home} VS ${m.Away}` })),
      );
      return ok;
    },

    async saveBets(
      platform: PlatformId,
      matchId: string | number,
      bets: CollectBetDto[],
      matchResult?: Record<string, unknown>,
    ): Promise<boolean> {
      if (isVpsOwnedPlatformCollect(platform))
        return false;
      if (!this.collect.get(platform))
        return false;
      const ok = matchResult === undefined
        ? await saveBetSource(platform, matchId, bets)
        : await saveBetSource(platform, matchId, bets, matchResult);
      void this.logCollect(
        `${platform}盘口采集${matchId}/${bets.length} => ${ok}`,
        bets.map(b => ({ matchId: b.SourceMatchID, betId: b.SourceBetID, betName: b.BetName, team: `${b.HomeName} vs ${b.AwayName}` })),
      );
      return ok;
    },

    async logCollect(title: string, rows: unknown[]) {
      if (!this.log)
        return;
      await saveUserLog(title, rows).catch(() => {});
    },
  },
});

import { defineStore } from "pinia";
import type { VenueOrder, VenueOrderStatus } from "@changmen/venue-adapter/contract";
import {
  getFootballOrders,
  getOpenFootballOrders,
  saveObFootballOrder,
  type FootballOrderDto,
} from "@/api/footballOrder";
import { saveOrders } from "@/api/order";
import {
  fetchObSportAccountOrderPatches,
  fetchObSportPendingOrderPatches,
  waitObSportVenueOrderHydration,
} from "@/runtime/obSportBetRecord";
import { pickObSportBetAccount } from "@/runtime/obSportBetAccount";
import { isPlaceholderTeam, type ObSportOrderStatusPatch } from "@/runtime/obSportOrderStatus";
import { readPodBetSettings } from "@/runtime/podBetSettings";
import {
  footballOrderSettledProfit,
  isFootballOrderPending,
  mergePodSportOrder,
  parsePodSportOrders,
  type PodSportOrder,
} from "@/runtime/podSportOrders";
import { accountOrderDisplayName } from "@/shared/accountDisplayName";
import { todayKey } from "@/shared/dateKey";
import { useAccountStore } from "@/stores/accountStore";

function asDto(row: PodSportOrder | FootballOrderDto): FootballOrderDto {
  return row;
}

function dateOf(row: Pick<FootballOrderDto, "at">): string {
  const at = Number(row.at) || 0;
  return todayKey(at > 0 ? new Date(at) : new Date());
}

function normalizeVenueKey(venue: unknown): string {
  return String(venue || "OB").trim() || "OB";
}

function isObFootballVenue(venue: unknown): boolean {
  return normalizeVenueKey(venue).toUpperCase() === "OB";
}

function toVenueOrderStatus(status: unknown): VenueOrderStatus {
  const s = String(status || "").trim().toLowerCase();
  if (s === "win")
    return "win";
  if (s === "lose")
    return "lose";
  if (s === "reject" || s === "rejected")
    return "reject";
  if (s === "return" || s === "void")
    return "return";
  if (s === "pending")
    return "pending";
  return "none";
}

function footballVenueOrderFromDto(row: FootballOrderDto, venue: string, source?: string): VenueOrder {
  const title = [row.home, row.away].map(v => String(v || "").trim()).filter(Boolean).join(" vs ");
  const stake = Number(row.stake) || 0;
  const odds = Number(row.odds) || 0;
  const orderSource = String(source || "").trim() || (row.auto ? "football-pod-auto" : "football-pod");
  return {
    provider: venue as VenueOrder["provider"],
    orderId: String(row.orderId || row.id || `${venue}-${Number(row.at) || Date.now()}`),
    odds,
    createAt: Number(row.at) || Date.now(),
    betMoney: stake,
    reward: stake > 0 && odds > 0 ? Math.round(stake * odds * 10000) / 10000 : 0,
    money: Number(row.profit) || 0,
    status: toVenueOrderStatus(row.status),
    game: "football",
    match: title || "足球",
    bet: String(row.marketLabel || "").trim(),
    item: String(row.sideLabel || "").trim(),
    domain: "sports",
    sport: "football",
    source: orderSource,
    podClientId: String(row.id || "").split("#PM#")[0].trim() || undefined,
    podPmMatchId: String(row.pmMatchId || "").trim() || undefined,
    ...(venue === "Polymarket" ? {
      pmTokenId: String(row.oid || "").trim() || undefined,
      pmConditionId: String(row.obMid || "").trim() || undefined,
      pmOrigin: "changmen" as const,
      pmSide: "buy" as const,
    } : {}),
  };
}

let loadSeq = 0;
let syncing = false;
let settleTimer: ReturnType<typeof setTimeout> | null = null;
const pendingPersists = new Map<string, FootballOrderDto>();

function persistKey(row: FootballOrderDto): string {
  return String(row.orderId || row.id || "").trim();
}

type FootballOrderAccount = {
  accountId?: number;
  playerName?: string;
  provider?: string;
};

type SaveOrderAccount = Parameters<typeof saveOrders>[0];

export function stopFootballOrderRuntime() {
  if (settleTimer) {
    clearTimeout(settleTimer);
    settleTimer = null;
  }
  syncing = false;
  pendingPersists.clear();
}

/**
 * 足球订单：对齐电竞 orderStore（Pinia 内存 + 按日 RDS），不写 localStorage。
 * OB 足球写 football_orders；非 OB 足球按 orders 兼容存储，但必须带 domain=sports/sport=football。
 * 禁止写 PlatformAccount.today / unsettle / orderCount / winBalance（电竞账号条字段）。
 */
export const useFootballOrderStore = defineStore("footballOrders", {
  state: () => ({
    rows: [] as FootballOrderDto[],
    todayRows: [] as FootballOrderDto[],
    settlementRows: [] as FootballOrderDto[],
    loaded: false,
    loading: false,
    persistError: "",
    orderDate: todayKey(),
    filterAccountId: 0,
  }),
  getters: {
    count(): number {
      return this.todayRows.length;
    },
    todayStake(): number {
      let sum = 0;
      for (const row of this.todayRows)
        sum += Number(row.stake) || 0;
      return sum;
    },
    todayProfit(): number {
      let sum = 0;
      for (const row of this.todayRows)
        sum += footballOrderSettledProfit(row);
      return sum;
    },
    todayOpenStake(): number {
      let sum = 0;
      for (const row of this.todayRows) {
        if (isFootballOrderPending(row.status))
          sum += Number(row.stake) || 0;
      }
      return sum;
    },
    filteredRows(): FootballOrderDto[] {
      if (!this.filterAccountId)
        return this.rows;
      return this.rows.filter(row => Number(row.playerId) === this.filterAccountId);
    },
    accountOptions(): { value: number; label: string }[] {
      const accounts = useAccountStore().accounts;
      const seen = new Set(accounts.map(a => a.accountId));
      const opts = accounts.map(a => ({
        value: a.accountId,
        label: `${a.platformName || a.provider}/${accountOrderDisplayName(a)}`,
      }));
      for (const row of this.rows) {
        const pid = Number(row.playerId) || 0;
        if (!pid || seen.has(pid))
          continue;
        seen.add(pid);
        const name = String(row.accountName || "").trim() || `#${pid}`;
        const venue = String(row.venue || "OB").trim();
        opts.push({ value: pid, label: `${venue}/${name}` });
      }
      return [{ value: 0, label: "全部" }, ...opts];
    },
  },
  actions: {
    playerLabel(row: FootballOrderDto): string {
      const pid = Number(row.playerId) || 0;
      const acc = pid ? useAccountStore().findAccount(pid) : null;
      if (acc) {
        const platform = acc.platformName || acc.provider || row.venue || "OB";
        return `${platform} / ${accountOrderDisplayName(acc)}`;
      }
      const venue = String(row.venue || "OB").trim();
      const name = String(row.accountName || "").trim();
      if (name)
        return `${venue} / ${name}`;
      return pid ? `${venue} / #${pid}` : venue;
    },
    platformClass(row: FootballOrderDto): string | undefined {
      const pid = Number(row.playerId) || 0;
      const acc = pid ? useAccountStore().findAccount(pid) : null;
      if (acc?.active)
        return "Stop";
      return undefined;
    },
    mergeLocal(row: FootballOrderDto) {
      const next = asDto(row);
      if (!isObFootballVenue(next.venue))
        return;
      if (dateOf(next) === this.orderDate)
        this.rows = mergePodSportOrder(this.rows, next) as FootballOrderDto[];
      if (dateOf(next) === todayKey())
        this.todayRows = this.orderDate === todayKey()
          ? this.rows
          : mergePodSportOrder(this.todayRows, next) as FootballOrderDto[];
    },
    async load(date?: string) {
      const seq = ++loadSeq;
      this.loading = true;
      try {
        const nextDate = date || this.orderDate || todayKey();
        this.orderDate = nextDate;
        const today = todayKey();
        const [server, todayServer, openServer] = await Promise.all([
          getFootballOrders({ date: nextDate }),
          nextDate === today ? Promise.resolve(null) : getFootballOrders({ date: today }),
          // 兼容前端先于后端发布：旧后端不认识该增强 action 时，当天订单仍须正常显示。
          getOpenFootballOrders({ days: 7 }).catch(() => [] as FootballOrderDto[]),
        ]);
        if (seq !== loadSeq)
          return;
        this.rows = parsePodSportOrders(server) as FootballOrderDto[];
        this.todayRows = todayServer == null
          ? this.rows
          : parsePodSportOrders(todayServer) as FootballOrderDto[];
        this.settlementRows = parsePodSportOrders(openServer) as FootballOrderDto[];
        this.loaded = true;
        this.persistError = "";
        this.syncVenueSettlementSoon(100);
      }
      catch (err) {
        if (seq !== loadSeq)
          return;
        this.persistError = err instanceof Error ? err.message : String(err);
      }
      finally {
        if (seq === loadSeq)
          this.loading = false;
      }
    },
    async persist(row: FootballOrderDto) {
      const key = persistKey(row);
      try {
        const saved = await saveObFootballOrder(row);
        if (!saved || typeof saved !== "object")
          throw new Error("保存未返回订单");
        const next = asDto({ ...row, ...saved, id: saved.id || row.id });
        if (key)
          pendingPersists.delete(key);
        this.mergeLocal(next);
        this.persistError = "";
        return next;
      }
      catch (err) {
        this.persistError = err instanceof Error ? err.message : String(err);
        this.mergeLocal(row);
        if (key)
          pendingPersists.set(key, row);
        this.loading = false;
        return row;
      }
    },
    async flushPendingPersists() {
      for (const row of [...pendingPersists.values()])
        await this.persist(row);
    },
    async appendPlaced(
      row: PodSportOrder,
      account?: FootballOrderAccount | null,
    ) {
      return this.appendVenuePlaced(row, account, { venue: "OB", hydrateOb: true });
    },
    async appendVenuePlaced(
      row: PodSportOrder,
      account?: FootballOrderAccount | null,
      opts: { venue?: string; hydrateOb?: boolean; source?: string } = {},
    ) {
      const venue = normalizeVenueKey(opts.venue || row.venue || "OB");
      const picked = account || pickObSportBetAccount(
        useAccountStore().accounts,
        readPodBetSettings().followAccountIds[0] || readPodBetSettings().followAccountId,
      ) as FootballOrderAccount | null;
      const playerId = Number(row.playerId) || Number(picked?.accountId) || 0;
      // 对齐电竞：本地只作占位；队名/赔率等以官网注单为准，占位队名不落库
      const home = isPlaceholderTeam(row.home) ? "" : String(row.home || "").trim();
      const away = isPlaceholderTeam(row.away) ? "" : String(row.away || "").trim();
      const dto: FootballOrderDto = {
        ...row,
        home,
        away,
        status: row.status || "None",
        profit: Number(row.profit) || 0,
        venue,
        playerId,
        accountName: String(row.accountName || picked?.playerName || ""),
      };
      const orderId = String(dto.orderId || "").trim();
      if (isObFootballVenue(venue)) {
        // P0：下注接口成功后先落最小占位，不能等待场馆注单列表（最多约 4.8 秒）后才保存。
        const saved = await this.persist(dto);
        if (orderId && opts.hydrateOb !== false) {
          void waitObSportVenueOrderHydration({ orderId, playerId })
            .then(patches => this.applyVenueStatus(patches))
            .catch((err) => {
              if (import.meta.env?.DEV)
                console.warn("[football] wait venue order skipped", err);
            });
        }
        this.syncVenueSettlementSoon();
        return saved;
      }

      try {
        if (picked) {
          const saveAccount = picked as SaveOrderAccount;
          await saveOrders(saveAccount, [footballVenueOrderFromDto(dto, venue, opts.source)]);
        }
        this.persistError = "";
      }
      catch (err) {
        this.persistError = err instanceof Error ? err.message : String(err);
      }
      return dto;
    },
    async applyVenueStatus(
      patches: ObSportOrderStatusPatch[],
      opts: { discoverMissing?: boolean; playerId?: number } = {},
    ) {
      if (!patches.length)
        return;
      for (const patch of patches) {
        const orderId = String(patch.orderId || "").trim();
        if (!orderId)
          continue;
        const row = this.rows.find(item => item.orderId === orderId)
          || this.todayRows.find(item => item.orderId === orderId)
          || this.settlementRows.find(item => item.orderId === orderId);
        if (!row && !opts.discoverMissing)
          continue;
        const account = opts.playerId
          ? useAccountStore().findAccount(opts.playerId)
          : null;
        const nextStatus = patch.status || row?.status || "None";
        const nextProfit = patch.status && !isFootballOrderPending(patch.status)
          ? Number(patch.profit) || 0
          : (row ? Number(row.profit) || 0 : Number(patch.profit) || 0);
        const venueHome = patch.home && !isPlaceholderTeam(patch.home) ? patch.home : "";
        const venueAway = patch.away && !isPlaceholderTeam(patch.away) ? patch.away : "";
        const keepHome = row?.home && !isPlaceholderTeam(row.home) ? row.home : "";
        const keepAway = row?.away && !isPlaceholderTeam(row.away) ? row.away : "";
        const merged: FootballOrderDto = {
          ...(row || {
            id: `venue:OB:${orderId}`,
            orderId,
            at: Number(patch.at) || Date.now(),
            home: "",
            away: "",
            sideLabel: "",
            marketLabel: "",
            odds: 0,
            stake: 0,
            oid: "",
            obMid: "",
            auto: false,
            status: "None",
            profit: 0,
            venue: "OB",
            playerId: Number(opts.playerId) || 0,
            accountName: String(account?.playerName || ""),
          }),
          orderId,
          status: nextStatus,
          profit: nextProfit,
          home: venueHome || keepHome,
          away: venueAway || keepAway,
          ...(patch.odds && patch.odds > 1 ? { odds: patch.odds } : {}),
          ...(patch.stake && patch.stake > 0 ? { stake: patch.stake } : {}),
          ...(patch.sideLabel ? { sideLabel: patch.sideLabel } : {}),
          ...(patch.marketLabel ? { marketLabel: patch.marketLabel } : {}),
          ...(patch.oid ? { oid: patch.oid } : {}),
          ...(patch.obMid ? { obMid: patch.obMid } : {}),
          ...(patch.at && patch.at > 0 ? { at: patch.at } : {}),
        };
        if (
          row
          && row.status === merged.status
          && Number(row.profit) === Number(merged.profit)
          && Number(row.odds) === Number(merged.odds)
          && Number(row.stake) === Number(merged.stake)
          && row.home === merged.home
          && row.away === merged.away
          && row.sideLabel === merged.sideLabel
          && row.marketLabel === merged.marketLabel
        )
          continue;
        try {
          const saved = await saveObFootballOrder(merged);
          if (!saved || typeof saved !== "object")
            continue;
          const next = asDto({ ...merged, ...saved, id: saved.id || merged.id || orderId });
          if (!next.id)
            continue;
          this.mergeLocal(next);
          this.settlementRows = isFootballOrderPending(next.status)
            ? mergePodSportOrder(this.settlementRows, next) as FootballOrderDto[]
            : this.settlementRows.filter(item => String(item.orderId || "") !== orderId);
          this.persistError = "";
        }
        catch (err) {
          this.persistError = err instanceof Error ? err.message : String(err);
        }
      }
    },
    async syncVenueAccountOrders(playerId: number) {
      const pid = Math.round(Number(playerId) || 0);
      if (pid <= 0)
        return;
      await this.flushPendingPersists();
      try {
        const patches = await fetchObSportAccountOrderPatches(pid);
        await this.applyVenueStatus(patches, { discoverMissing: true, playerId: pid });
      }
      catch (err) {
        if (import.meta.env?.DEV)
          console.warn("[football] venue account orders skipped", err);
      }
    },
    async syncVenueSettlement() {
      if (syncing)
        return;
      const seen = new Set<string>();
      const pending: { orderId: string; playerId: number; at: number }[] = [];
      // 对齐电竞：持续扫未结算单；足球额外带最近历史未结，避免旧单停在 None。
      for (const row of [...this.todayRows, ...this.rows, ...this.settlementRows]) {
        if (String(row.venue || "OB").trim() !== "OB")
          continue;
        if (!isFootballOrderPending(row.status))
          continue;
        const orderId = String(row.orderId || "").trim();
        if (!orderId || seen.has(orderId))
          continue;
        seen.add(orderId);
        pending.push({ orderId, playerId: Number(row.playerId) || 0, at: Number(row.at) || 0 });
      }
      if (!pending.length)
        return;
      syncing = true;
      try {
        await this.flushPendingPersists();
        const patches = await fetchObSportPendingOrderPatches(pending);
        await this.applyVenueStatus(patches);
      }
      catch (err) {
        if (import.meta.env?.DEV)
          console.warn("[football] venue settlement skipped", err);
      }
      finally {
        syncing = false;
      }
    },
    syncVenueSettlementSoon(delayMs = 800) {
      if (settleTimer)
        clearTimeout(settleTimer);
      settleTimer = setTimeout(() => {
        settleTimer = null;
        void this.syncVenueSettlement();
      }, delayMs);
    },
  },
});

import type { ClientMatchDto } from "@/types/esport";
