import type { PlatformId } from "@/types/esport";
import type { LimitEntry } from "@changmen/client-core/types/limit";
/**
 * 实时赔率缓存（对齐 A8 `Qn()` / match store 内 `p=Qn()`；Pinia id `"counter"`）。
 * changmen Pinia id 为 `"odds"`。勿与 A8 `fo()`（账号 store）混淆。
 *
 * 与 ViewMatch 的分工：
 * - `Client_GetMatchs` → matchStore → ViewMatch / ViewBetItem：赛事结构、盘口 ID（betId）、选项 ID（homeId/awayId）
 * - 各平台采集器（HTTP 灌盘 + MQTT/WS 增量）→ 本 store `save()`：按 **oddId** 存最新赔率与锁盘
 *
 * 本 store **不存 matchId**；UI 只通过 ViewBetItem 持有的 id 来查赔率缓存。
 * 缓存里可能出现 ViewMatch 未引用的 oddId（多盘口、列表已下架残留、采集先于合并等）。
 */
import { defineStore } from "pinia";
import { truncateOddsTo3 } from "@changmen/shared/odds_format";
import { formatDisplayOdds } from "@changmen/client-core/shared/format";
import { PLATFORMS } from "@changmen/venue-adapter/shared";
import {
  isPmArbPriceBufferActive,
  pmEffectiveOddsFromFoEntry,
  isPmTickBufferActive,
  resolvePmDisplayQuote,
} from "@changmen/venue-adapter/polymarket/pmArbPriceBufferMode";
import {
  isPfArbPriceBufferActive,
  pfEffectiveOddsFromFoEntry,
} from "@changmen/venue-adapter/predictfun/pfArbPriceBufferMode";

/** 写入赔率缓存的数据来源，便于排查 HTTP 初值 vs 推送覆盖 */
export type OddsSaveSource = "mqtt" | "http";

/**
 * 单条赔率缓存条目（key = `OddsEntry.id`，即平台侧的 **选项/odd id**，不是赛事 id）。
 *
 * 与 GetMatchs `Sources` 的对应关系（以 OB 为例）：
 * - `id`     ↔ `HomeID` / `AwayID`（下注时 itemId）
 * - `betId`  ↔ `BetID`（盘口/market id）
 */
export interface OddsEntry {
  /** 平台选项 ID（odd id / selection id），本 store 主键，全局唯一于该平台 bucket 内 */
  id: string;
  /** 原始赔率数值；锁盘时 UI 显示 0，不读 fallback */
  odds: number;
  /** [changmen 扩展] Polymarket / PredictFun CLOB best_ask（0~1）；预检限价用，其它平台不填 */
  clobPrice?: number;
  /** [changmen 扩展] Predict.fun market id */
  marketId?: string;
  /** 是否锁盘/不可下注（HTTP 灌盘公式或 MQTT 增量） */
  isLock: boolean;
  /** 所属盘口 ID（market / bet group id），用于 betIndex 按盘锁盘 */
  betId?: string;
  /** 该选项对应主/客侧（HTTP 灌盘写入；MQTT 增量时从已有条目保留） */
  side?: "home" | "away";
  /** 最后一次写入时间戳（ms）；`clean()` 无 platform 参数时按 1h 过期删条目 */
  time: number;
  /** 本条最后一次 save 的来源 */
  source?: OddsSaveSource;
}

/** 赔率相对上一条数值的涨跌方向；UI 样式见 `extensions/arbBet/ui` */
export type OddsFlashDir = "up" | "down";

/** 赔率涨跌高亮保持时长（与 arbBetUi.css 动画配合） */
const ODDS_FLASH_MS = 4_000;
/** OB MQTT `/odd/statusUpdate/`：status === 6 表示盘口开放，否则视为锁盘 */
const OB_MARKET_OPEN = 6;

/** 对齐 A8 `Qn()`（Pinia `"counter"`）— 实时赔率缓存 */
export const useOddsStore = defineStore("odds", {
  state: () => ({
    /**
     * 主表：`platform → oddId → OddsEntry`。
     * 扁平存储，不按赛事分组；读赔用 `getOdds`。
     */
    data: new Map<PlatformId, Map<string, OddsEntry>>(),

    /**
     * [changmen 扩展] PM 缓存重建时保留完整原始行情，报价仍由同一转换模块生成。
     * null 表示已按原有 1h 规则清理，防止 ViewBetItem 的旧数字复活该报价。
     * 不回写 data，不改变采集器的 isOdds/getEntry 语义。
     */
    pmQuoteSnapshots: new Map<string, Readonly<OddsEntry> | null>(),

    /**
     * 盘口索引：`platform → betId → oddId[]`。
     * 用于 MQTT 盘口级锁盘推送时，批量更新该盘口下所有 oddId 的锁盘状态。
     */
    betIndex: new Map<PlatformId, Map<string, string[]>>(),

    /**
     * 调试：各平台最近一条 WS/MQTT 原始 payload 字符串（非业务主路径）。
     */
    messages: new Map<PlatformId, string>(),

    /**
     * 限红缓存：`platform → oddId → LimitEntry`。
     * 下注前 checkBet / stake 等写入；带 TTL，过期由 `cleanExpiredLimits` 清理。
     */
    limits: new Map<PlatformId, Map<string, LimitEntry>>(),

    /**
     * 涨跌闪烁：`"platform:oddId" → { dir, until, source }`。
     * `until` 为毫秒时间戳，过期后 `getFlash` 自动删除。
     */
    flash: new Map<string, { dir: OddsFlashDir; until: number; source: OddsSaveSource }>(),

    _limitsCleanedAt: 0,
    /** [changmen 扩展] 报价规则/元数据的显示失效通知，不重写原始赔率。 */
    pmTickBufferEnabled: false,
    pmTickBufferVersion: 0,
  }),

  actions: {
    /**
     * 写入或覆盖一条赔率（对齐 A8 `Qn().save` / `p.save`）。
     * HTTP 灌盘与 MQTT 增量均直接覆盖，**不做**“旧 time 拒绝新数据”挡板。
     * 盘口 UI 靠 Pinia reactive Map 按 oddId 追踪；旁路盯盘用 `$subscribe`；
     * 订单现价由 OrderList 按挂单 token `$onAction` 局部刷新（不再全局 quoteTick）。
     */
    save(platform: PlatformId, entry: OddsEntry, source: OddsSaveSource = "http") {
      const id = String(entry.id);
      if (!this.data.has(platform))
        this.data.set(platform, new Map());
      const bucket = this.data.get(platform)!;
      const prev = bucket.get(id);
      const nextOdds = entry.odds;

      if (
        prev
        && !entry.isLock
        && !prev.isLock
        && prev.odds > 0
        && nextOdds > 0
        && prev.odds !== nextOdds
      ) {
        this.flash.set(`${platform}:${id}`, {
          dir: nextOdds > prev.odds ? "up" : "down",
          until: Date.now() + ODDS_FLASH_MS,
          source,
        });
      }
      const next: OddsEntry = { ...entry, id, source };
      if (next.marketId != null)
        next.marketId = String(next.marketId).trim() || undefined;
      // PredictFun：增量/writeVenueOdds 若漏传 marketId，保留已有值，避免 checkBet 丢 fo 缓存
      if (!next.marketId && prev?.marketId)
        next.marketId = prev.marketId;
      bucket.set(id, next);

      if (entry.betId) {
        const betId = String(entry.betId);
        if (!this.betIndex.has(platform))
          this.betIndex.set(platform, new Map());
        const idx = this.betIndex.get(platform)!;
        const list = idx.get(betId) ?? [];
        if (!list.includes(id)) {
          list.push(id);
          idx.set(betId, list);
        }
      }
    },

    /** 取某 oddId 的涨跌方向及来源；已过期则返回 undefined 并删 flash 条目 */
    getFlash(platform: PlatformId, oddsId: string): { dir: OddsFlashDir; source: OddsSaveSource } | undefined {
      const key = `${platform}:${String(oddsId)}`;
      const row = this.flash.get(key);
      if (!row)
        return undefined;
      if (row.until < Date.now()) {
        this.flash.delete(key);
        return undefined;
      }
      return { dir: row.dir, source: row.source };
    },

    /** 赔率缓存中是否已有该 oddId（MQTT 增量门闩：未灌盘过的 id 通常不处理推送） */
    isOdds(platform: PlatformId, oddsId: string): boolean {
      return Boolean(this.data.get(platform)?.has(String(oddsId)));
    },

    /** 原始条目；未命中返回 undefined（不格式化、不处理锁盘显示逻辑） */
    getEntry(platform: PlatformId, oddsId: string): OddsEntry | undefined {
      return this.data.get(platform)?.get(String(oddsId));
    },

    /** [changmen 扩展] 报价消费者共用的原始卖一入口；实时行情优先于重建快照。 */
    getPmQuoteEntry(oddsId: string): Readonly<OddsEntry> | undefined {
      const id = String(oddsId);
      return this.getEntry(PLATFORMS.Polymarket, id) ?? this.pmQuoteSnapshots.get(id) ?? undefined;
    },

    /**
     * 按 oddId 取展示赔率（对齐 A8 `Qn().getOdds` / `p.getOdds`）。
     * - 无缓存：返回 fallback（经平台格式化）
     * - 有缓存且 isLock：返回 0（**不用** fallback 顶替锁盘）
     * - 有缓存且未锁：返回格式化后的 row.odds
     * - Polymarket / PredictFun：truncateOddsTo3（1/price 截断）；其它馆 formatDisplayOdds（四舍五入）
     * - [changmen 扩展] PM 可读缓存重建前的完整卖一快照，再按当前规则转换；写入仍是真价。
     */
    getOdds(platform: PlatformId, oddsId: string, fallback = 0): number {
      if (platform === PLATFORMS.Polymarket) void this.pmTickBufferVersion;
      const row = platform === PLATFORMS.Polymarket
        ? this.getPmQuoteEntry(oddsId) : this.getEntry(platform, oddsId);
      if (platform === PLATFORMS.Polymarket && (this.pmTickBufferEnabled || isPmTickBufferActive())) {
        const result = resolvePmDisplayQuote(String(oddsId), row);
        return result.status === "ready" ? result.quote.displayOdds : 0;
      }
      const useTrunc = platform === PLATFORMS.Polymarket || platform === PLATFORMS.PredictFun;
      if (!row && platform === PLATFORMS.Polymarket && this.pmQuoteSnapshots.get(String(oddsId)) === null)
        return 0;
      if (row === undefined)
        return useTrunc ? truncateOddsTo3(fallback) : formatDisplayOdds(fallback);
      if (row.isLock)
        return 0;
      if (platform === PLATFORMS.Polymarket && isPmArbPriceBufferActive())
        return pmEffectiveOddsFromFoEntry(row);
      if (platform === PLATFORMS.PredictFun && isPfArbPriceBufferActive())
        return pfEffectiveOddsFromFoEntry(row);
      return useTrunc ? truncateOddsTo3(row.odds) : formatDisplayOdds(row.odds);
    },

    /** [changmen 扩展] 行情正常但报价尚未就绪；UI 不将其误标为场馆封盘。 */
    isQuotePending(platform: PlatformId, oddsId: string): boolean {
      if (platform !== PLATFORMS.Polymarket || !isPmTickBufferActive()) return false;
      void this.pmTickBufferVersion;
      return resolvePmDisplayQuote(String(oddsId), this.getPmQuoteEntry(oddsId)).status === "waiting-tick";
    },

    /** 更新单条 odd 锁盘（对齐 A8 `updateOddsLock`：仅改已有行） */
    updateOddsLock(platform: PlatformId, oddsId: string, locked: boolean) {
      const key = String(oddsId);
      const row = this.data.get(platform)?.get(key);
      if (row && row.isLock !== locked) {
        row.isLock = locked;
      }
      if (!row && platform === PLATFORMS.Polymarket) {
        const snapshot = this.pmQuoteSnapshots.get(key);
        if (snapshot && snapshot.isLock !== locked)
          this.pmQuoteSnapshots.set(key, Object.freeze({ ...snapshot, isLock: locked }));
      }
    },

    /** 更新整盘锁盘（对齐 A8 `updateBetLock`：betIndex 下所有 odd） */
    updateBetLock(platform: PlatformId, betId: string, locked: boolean) {
      const key = String(betId);

      const indexed = this.betIndex.get(platform)?.get(key);
      if (platform === PLATFORMS.Polymarket) {
        const ids = new Set(indexed ?? []);
        for (const row of this.data.get(platform)?.values() ?? []) if (row.betId === key) ids.add(row.id);
        for (const row of this.pmQuoteSnapshots.values()) if (row?.betId === key) ids.add(row.id);
        for (const id of ids) this.updateOddsLock(platform, id, locked);
        return;
      }
      if (indexed?.length) {
        for (const id of indexed) this.updateOddsLock(platform, id, locked);
        return;
      }
      const bucket = this.data.get(platform);
      if (!bucket)
        return;
      for (const [id, row] of bucket.entries()) {
        if (row.betId === key)
          this.updateOddsLock(platform, id, locked);
      }
    },

    /**
     * OB `/odd/*` MQTT 锁盘解析（**当前未接线**：A8 UMe 亦只处理 market 三 topic）。
     * 保留供将来对齐 odd 级推送；盘级锁盘走 `updateBetLock`（market/statusUpdate|suspended）。
     */
    applyObOddLock(
      platform: PlatformId,
      row: { id?: unknown; status?: unknown; visible?: unknown; suspended?: unknown },
      topic: string,
    ) {
      const oddsId = String(row.id ?? "");
      if (!oddsId)
        return;
      let locked = false;
      if (topic === "/odd/suspended/") {
        locked = Number(row.suspended) === 1;
      }
      else if (topic === "/odd/visible/") {
        locked = Number(row.visible) !== 1;
      }
      else if (topic === "/odd/statusUpdate/") {
        if (row.status !== undefined)
          locked = Number(row.status) !== OB_MARKET_OPEN;
      }
      this.updateOddsLock(platform, oddsId, locked);
    },

    /** 记录平台最近 WS/MQTT 消息（调试） */
    updateMessage(platform: PlatformId, payload: string) {
      this.messages.set(platform, payload);
    },

    /**
     * 清理赔率缓存条目（对齐 A8 `p.clean()`，主循环拉列表成功时调用）。
     * - 传入 platform：清空该平台 data / betIndex（采集轮次切换时用）
     * - 不传：全局扫描，删除 time 超过 1 小时的 stale odd（不碰 betIndex 孤儿索引，靠 save 重建）
     */
    clean(platform?: PlatformId) {
      const cutoff = Date.now() - 3_600_000;
      if (platform) {
        if (platform === PLATFORMS.Polymarket) {
          for (const [id, row] of this.data.get(platform) ?? [])
            this.pmQuoteSnapshots.set(id, row.time < cutoff ? null : Object.freeze({ ...row }));
          for (const [id, row] of this.pmQuoteSnapshots) if (row && row.time < cutoff) this.pmQuoteSnapshots.set(id, null);
        }
        this.data.set(platform, new Map());
        this.betIndex.set(platform, new Map());
        return;
      }
      for (const [provider, bucket] of this.data) {
        for (const [id, row] of [...bucket.entries()]) {
          if (row.time < cutoff) {
            bucket.delete(id);
            if (provider === PLATFORMS.Polymarket) this.pmQuoteSnapshots.set(id, null);
          }
        }
      }
      for (const [id, row] of this.pmQuoteSnapshots) if (row && row.time < cutoff) this.pmQuoteSnapshots.set(id, null);
    },

    maybeCleanExpiredLimits(platform?: PlatformId) {
      const now = Date.now();
      if (now - this._limitsCleanedAt < 1000)
        return;
      this._limitsCleanedAt = now;
      this.cleanExpiredLimits(platform);
    },

    /** 给定 oddId 列表中是否任一条存在未过期的限红 */
    hasLimit(platform: PlatformId, ids: string[]): boolean {
      this.maybeCleanExpiredLimits(platform);
      const bucket = this.limits.get(platform);
      if (!bucket)
        return false;
      const now = Date.now();
      return ids.some((id) => {
        const row = bucket.get(id);
        return Boolean(row && (!row.expireTime || row.expireTime >= now));
      });
    },

    /** 取单条限红；过期返回 undefined */
    getLimit(platform: PlatformId, oddsId: string): LimitEntry | undefined {
      const row = this.limits.get(platform)?.get(oddsId);
      if (!row)
        return undefined;
      if (row.expireTime && row.expireTime < Date.now())
        return undefined;
      return row;
    },

    /**
     * 写入限红（对齐 A8 `QIe`）。
     * @param value 限红金额
     * @param payout 可选派彩上限
     * @param ttlSec 可选 TTL（秒），到期后 getLimit 视为无
     */
    setLimit(
      platform: PlatformId,
      oddsId: string,
      value: number,
      payout?: number,
      ttlSec?: number,
    ) {
      if (!this.limits.has(platform))
        this.limits.set(platform, new Map());
      const expireTime = ttlSec ? Date.now() + ttlSec * 1000 : undefined;
      const entry: LimitEntry = { value, expireTime };
      if (payout)
        entry.payout = payout;
      this.limits.get(platform)!.set(oddsId, entry);
    },

    /** 删除单条限红 */
    deleteLimit(platform: PlatformId, oddsId: string) {
      this.limits.get(platform)?.delete(oddsId);
    },

    /** 删除已过期的 limits 条目；可只清某平台 */
    cleanExpiredLimits(platform?: PlatformId) {
      const now = Date.now();
      const buckets = platform
        ? [[platform, this.limits.get(platform)] as const]
        : [...this.limits.entries()];
      for (const [, bucket] of buckets) {
        if (!bucket)
          continue;
        for (const [id, row] of [...bucket.entries()]) {
          if (row.expireTime && row.expireTime < now)
            bucket.delete(id);
        }
      }
    },
  },
});

import type { OrderRow } from "@/types/order";
import { defineStore } from "pinia";
import { getOrderList } from "@/api/esport";
import { Currency, getExchange } from "@changmen/shared/currency";
import {
  dropOrphanPolymarketSellGroups,
  filterOrdersBelongingToDate,
  groupOrdersByEffectiveLink,
  isLinkedArbOrderGroup,
  isPolymarketOpenPosition,
  isPredictionSellRow,
  orderBelongsToDateKey,
  orderLinkLegend,
  orderLinkMapEntries,
  toOrderDateKeyLocal,
  computeOrderGroupProfit,
  polymarketMoneyForAggregate,
} from "@/shared/orderLink";
import { truncateShareUsdtAmount } from "@/shared/pfOrderDisplay";
import { resolvePmRemainingShares } from "@changmen/venue-adapter/polymarket";
import { accountOrderDisplayName } from "@/shared/accountDisplayName";
import { useAccountStore } from "@/stores/accountStore";
import { useMessageStore } from "@/stores/messageStore";
import { useUserStore } from "@/stores/userStore";

function todayKey() {
  return toOrderDateKeyLocal(Date.now());
}

function isSportsOrder(row: OrderRow): boolean {
  return String(row.Domain ?? "").trim() === "sports";
}

type FetchOrdersOptions = {
  sideEffects?: boolean;
};

export { isLinkedArbOrderGroup as isLinkedArbGroup };

/** 对齐 A8 `Io.getOrders` / `orders` / `orderDate` */
export const useOrderStore = defineStore("order", {
  state: () => ({
    orders: new Map<number, OrderRow[]>(),
    orderDate: todayKey(),
    dayProfit: 0,
    loading: false,
    filterAccountId: 0,
  }),

  getters: {
    filteredOrders(state): Map<number, OrderRow[]> {
      if (!state.filterAccountId)
        return state.orders;
      const out = new Map<number, OrderRow[]>();
      for (const [link, rows] of state.orders) {
        const filtered = rows.filter(r => r.PlayerID === state.filterAccountId);
        if (filtered.length)
          out.set(link, filtered);
      }
      return out;
    },

    /** 模板 v-for：顺序与 A8 groupBy(Link) 一致（已按 Link 降序） */
    orderEntries(): [number, OrderRow[]][] {
      return orderLinkMapEntries(this.filteredOrders);
    },

    accountOptions(): { value: number; label: string }[] {
      const accounts = useAccountStore().accounts;
      const seen = new Set(accounts.map(a => a.accountId));
      const opts = accounts.map(a => ({
        value: a.accountId,
        label: `${a.platformName || a.provider}/${accountOrderDisplayName(a)}`,
      }));
      // 已删账号仍出现在当日订单：筛选取名对齐后台历史展示
      for (const rows of this.orders.values()) {
        for (const r of rows) {
          const pid = Number(r.PlayerID) || 0;
          if (!pid || seen.has(pid))
            continue;
          seen.add(pid);
          const name = String(r.Player?.UserName || "").trim() || `#${pid}`;
          const platform = String(r.Player?.Platform || r.Type || "").trim();
          const base = platform ? `${platform}/${name}` : name;
          opts.push({
            value: pid,
            label: r.PlayerDeleted ? `${base}（已删）` : base,
          });
        }
      }
      return [{ value: 0, label: "全部" }, ...opts];
    },
  },

  actions: {
    /** [A8 可证实] `Io.getOrders` / `E()`：`groupBy(Link)` + `updateTodayProfit` */
    async fetchOrders(date?: string, options: FetchOrdersOptions = {}) {
      const userStore = useUserStore();
      if (!userStore.userId)
        return false;
      const sideEffects = options.sideEffects !== false;
      const accountStore = useAccountStore();
      if (!accountStore.accounts.length && accountStore.loaded) {
        /* 允许空账号时仍拉订单 */
      }
      this.loading = true;
      try {
        const nextDate = date ?? todayKey();
        this.orderDate = nextDate;
        const page = await getOrderList({ date: this.orderDate, pageSize: 1024 });
        if (!page)
          return false;
        // 后端已按 Link 开弓日取数并过滤；前端再滤一次防脏数据
        const list = filterOrdersBelongingToDate(page.list ?? [], this.orderDate);
        this.orders = dropOrphanPolymarketSellGroups(groupOrdersByEffectiveLink(list));
        if (sideEffects) {
          this.updateTodayProfit(list);
          const reportBase = list.filter(r => !isSportsOrder(r));
          const reportRows = reportBase
            .filter(r => orderBelongsToDateKey(r, this.orderDate, reportBase))
            .map(r => ({ ...r, Money: polymarketMoneyForAggregate(r, reportBase) }));
          useMessageStore().orderReportMessage(accountStore.accounts, reportRows);
          // 恢复「平仓中」会话：跑完 CLOB 终态（已平仓 / 可再卖）
          void import("@/stores/account/pmManualSell")
            .then(m => m.resumePmManualSellClosings())
            .catch(() => {});
        }
        return true;
      }
      finally {
        this.loading = false;
      }
    },

    updateTodayProfit(list: OrderRow[]) {
      const accountStore = useAccountStore();
      const today = this.orderDate;
      /** 展示已按 Link 开弓日过滤；盈亏与列表同一天 */
      const esportList = list.filter(r => !isSportsOrder(r));
      const inDay = esportList.filter(r => orderBelongsToDateKey(r, today, esportList));
      const moneyOf = (r: OrderRow) => polymarketMoneyForAggregate(r, inDay);
      const byPlayer = new Map<number, OrderRow[]>();
      for (const row of inDay) {
        const pid = Number(row.PlayerID) || 0;
        if (!byPlayer.has(pid))
          byPlayer.set(pid, []);
        byPlayer.get(pid)!.push(row);
      }

      const accById = new Map(accountStore.accounts.map(a => [a.accountId, a]));

      for (const acc of accById.values()) {
        acc.today = 0;
        acc.orderCount = 0;
        if (today === todayKey())
          acc.todayOrder = 0;
      }

      for (const [playerId, rows] of byPlayer) {
        const acc = accById.get(playerId);
        if (!acc)
          continue;
        const profit = rows.reduce((sum, r) => sum + moneyOf(r), 0);
        acc.today = Math.round(profit);
        // 笔数不计 PM/PF 卖单（依附买单）
        const primaryCount = rows.filter(r => !isPredictionSellRow(r)).length;
        acc.orderCount = primaryCount;
        if (today === todayKey()) {
          acc.todayOrder = primaryCount;
          const unsettled = rows.filter((r) => {
            if (isPredictionSellRow(r))
              return false;
            if (String(r.Status ?? "") !== "None")
              return false;
            if (String(r.Type ?? "") === "Polymarket")
              return isPolymarketOpenPosition(r);
            if (String(r.Type ?? "") === "PredictFun") {
              const state = String(r.PfSellState ?? "").toLowerCase();
              if (state === "closed" || state === "settled")
                return false;
              return true;
            }
            return true;
          });
          acc.unsettle = unsettled.length;
          acc.winBalance
            = (acc.balance ?? 0)
              + unsettled.reduce((sum, r) => {
                const fx = getExchange(Currency.USDT);
                if (String(r.Type ?? "") === "Polymarket" && r.PmSide !== "sell") {
                  const rem = resolvePmRemainingShares(r);
                  if (rem > 0.0001)
                    return sum + rem * fx;
                  const fill = Number(r.PmShares) || 0;
                  if (fill > 0.0001)
                    return sum + fill * fx;
                  const stakeUsdc = Number(r.PmStakeUsdc) || 0;
                  const price = Number(r.PmFillPrice);
                  if (stakeUsdc > 0 && price > 0 && price < 1)
                    return sum + (stakeUsdc / price) * fx;
                  return sum;
                }
                if (String(r.Type ?? "") === "PredictFun" && r.PfSide !== "sell") {
                  const hold = Number(r.PfHoldShares) || 0;
                  const fill = Number(r.PfShares) || 0;
                  const shares = hold > 0 ? hold : fill;
                  if (shares > 0)
                    return sum + truncateShareUsdtAmount(shares) * fx;
                  const notional = Number(r.PfNotionalUsdt) || Number(r.BetMoney) || 0;
                  const book = Number(r.PfBookPrice);
                  if (notional > 0 && book > 0 && book < 1)
                    return sum + truncateShareUsdtAmount(notional / book) * fx;
                  return sum;
                }
                const odds = Number(r.Odds) || 0;
                return sum + (Number(r.BetMoney) || 0) * odds;
              }, 0);
        }
      }

      this.dayProfit = inDay.reduce((sum, r) => sum + moneyOf(r), 0);
    },

    linkLegend(rows: OrderRow[]) {
      return orderLinkLegend(rows);
    },

    linkClass(rows: OrderRow[]) {
      const total = computeOrderGroupProfit(rows);
      if (total === 0)
        return "default";
      return total > 0 ? "success" : "fail";
    },

    playerLabel(row: OrderRow) {
      const accountStore = useAccountStore();
      const acc = accountStore.findAccount(row.PlayerID);
      if (acc) {
        const platform = accountStore.getPlatformName(acc.platformId, acc.platformName);
        return `${platform} / ${accountOrderDisplayName(acc)}`;
      }
      // 账号已删：后端 Client_GetOrderList 回填 Player（含 soft-delete）
      if (row.Player?.Platform || row.Player?.UserName) {
        const base = `${row.Player.Platform || ""} / ${row.Player.UserName || ""}`.trim();
        return row.PlayerDeleted && base ? `${base}（已删）` : base;
      }
      const pid = Number(row.PlayerID) || 0;
      return pid ? `#${pid}` : "";
    },

    /** 对齐 A8 OrderView：暂停账号平台角标加 `.Stop` 删除线 */
    platformClass(row: OrderRow) {
      const acc = useAccountStore().findAccount(row.PlayerID);
      if (acc?.active)
        return "Stop";
      return undefined;
    },
  },
});

import { createPinia, setActivePinia } from "pinia";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { useUserStore } from "@/stores/userStore";
import { SessionRestoreConfigurationError } from "@/lib/sessionRestoreError";
import { capturePmFokPreflightMode, setPmFokPreflightMode } from "@changmen/venue-adapter/polymarket";
import { getClientData, getClientDataArray, saveClientDataDetailed } from "@/api/esport";

const auth = vi.hoisted(() => ({
  clearAuthSession: vi.fn(),
