describe("FOK preflight preference persistence", () => {
  const modeForNewAttempt = () => capturePmFokPreflightMode({} as any);
  beforeEach(() => {
    setActivePinia(createPinia()); setPmFokPreflightMode("legacy");
    const user = useUserStore(); user.userId = 12;
    vi.spyOn(user, "syncPbCollectModeFromLocal").mockResolvedValue();
    vi.spyOn(user, "syncPmArbPriceBufferFromPrefs").mockResolvedValue();
    vi.spyOn(user, "syncPmFokDepthBufferFromPrefs").mockResolvedValue();
    vi.spyOn(user, "syncPfArbPriceBufferFromPrefs").mockResolvedValue();
    vi.mocked(saveClientDataDetailed).mockReset();
    vi.mocked(getClientDataArray).mockResolvedValue([]);
  });
  it("loads the saved mode and resets old accounts without the field to legacy", async () => {
    vi.mocked(getClientData).mockResolvedValue({ pmFokPreflightMode: "optimized" });
    await useUserStore().loadExtras(true);
    expect(modeForNewAttempt()).toBe("optimized");
    vi.mocked(getClientData).mockResolvedValue({});
    await useUserStore().loadExtras(true);
    expect(modeForNewAttempt()).toBe("legacy");
  });
  it("does not activate an unsaved edit or a failed save", async () => {
    useUserStore().extensionPrefs.pmFokPreflightMode = "optimized";
    expect(modeForNewAttempt()).toBe("legacy");
    vi.mocked(saveClientDataDetailed).mockResolvedValue({ ok: false, msg: "offline" });
    await expect(useUserStore().saveExtensionPrefs()).rejects.toThrow("offline");
    expect(modeForNewAttempt()).toBe("legacy");
  });
  it("applies exactly the persisted selection after success, leaving pending edits for the next save", async () => {
    const user = useUserStore(); user.extensionPrefs.pmFokPreflightMode = "optimized";
    let finish!: (value: any) => void;
    vi.mocked(saveClientDataDetailed).mockImplementation(() => new Promise(resolve => { finish = resolve; }));
    const saving = user.saveExtensionPrefs();
    await vi.waitFor(() => expect(saveClientDataDetailed).toHaveBeenCalledOnce());
    user.extensionPrefs.pmFokPreflightMode = "legacy";
    expect(modeForNewAttempt()).toBe("legacy");
    expect(JSON.parse(vi.mocked(saveClientDataDetailed).mock.calls[0]![1]).pmFokPreflightMode).toBe("optimized");
    finish({ ok: true }); await saving;
    expect(modeForNewAttempt()).toBe("optimized");
  });
  it("does not apply a prior user's pending save to a different login", async () => {
    const user = useUserStore(); user.extensionPrefs.pmFokPreflightMode = "optimized";
    let finish!: (value: any) => void;
    vi.mocked(saveClientDataDetailed).mockImplementation(() => new Promise(resolve => { finish = resolve; }));
    const saving = user.saveExtensionPrefs();
    await vi.waitFor(() => expect(saveClientDataDetailed).toHaveBeenCalledOnce());
    user.userId = 13;
    finish({ ok: true }); await saving;
    expect(modeForNewAttempt()).toBe("legacy");
  });
});

describe("userStore.restoreSession", () => {
  afterEach(() => vi.unstubAllGlobals());
  beforeEach(() => {
    setActivePinia(createPinia());
    auth.token = "access-token";
    auth.refreshToken = "refresh-token";
    auth.cookieMode = false;
    auth.clearAuthSession.mockReset();
    auth.clearAuthSession.mockImplementation(() => {
      auth.token = null;
      auth.refreshToken = null;
    });
    auth.ensureTokenRefresh.mockReset();
    auth.ensureTokenRefresh.mockResolvedValue(undefined);
    auth.logout.mockReset();
    auth.probe.mockReset();
  });
  it("preserves a configuration error on the first probe without a local session hint", async () => {
    auth.token = null; auth.refreshToken = null; auth.cookieMode = false;
    vi.stubGlobal("window", {}); vi.stubGlobal("document", {});
    auth.probe.mockRejectedValue(new SessionRestoreConfigurationError("服务端未启用 Cookie 登录"));
    const store = useUserStore();
    expect(await store.restoreSession()).toBe(false);
    expect(store.sessionRestoreRetryable).toBe(false);
    expect(store.sessionRestoreError).toBe("服务端未启用 Cookie 登录");
    expect(auth.clearAuthSession).not.toHaveBeenCalled();
  });

  it("preserves new user state when an old logout is superseded", async () => {
    const store = useUserStore();
    store.userName = "new-user";
    store.ready = true;
    auth.logout.mockResolvedValue(false);
    expect(await store.logout()).toBe(false);
    expect(store.userName).toBe("new-user");
    expect(store.ready).toBe(true);
  });

  it("keeps the logout entry available when server confirmation fails", async () => {
    const store = useUserStore();
    store.userName = "river";
    store.ready = true;
    auth.logout.mockRejectedValue(new Error("退出尚未确认"));
    await expect(store.logout()).rejects.toThrow("退出尚未确认");
    expect(store.userName).toBe("river");
    expect(store.ready).toBe(true);
  });

  it("keeps local credentials and offers retry after a temporary user-info failure", async () => {
    const store = useUserStore();
    store.fetchUserInfo = vi.fn().mockRejectedValue(new Error("502 Bad Gateway"));

    await expect(store.restoreSession()).resolves.toBe(false);

    expect(auth.token).toBe("access-token");
    expect(auth.refreshToken).toBe("refresh-token");
    expect(auth.clearAuthSession).not.toHaveBeenCalled();
    expect(store.sessionChecked).toBe(false);
    expect(store.sessionRestoreError).toBe("连接暂时不可用，请检查网络后重试");
  });

  it("finishes session checking after an explicit invalidation cleared the token", async () => {
    const store = useUserStore();
    store.fetchUserInfo = vi.fn().mockImplementation(async () => {
      auth.token = null;
      auth.refreshToken = null;
      throw new Error("未登录");
    });

    await expect(store.restoreSession()).resolves.toBe(false);

    expect(store.sessionChecked).toBe(true);
    expect(store.sessionRestoreError).toBe("");
  });

  it("shows recovery error when a cookie session cannot obtain an access token", async () => {
    auth.token = null;
    auth.refreshToken = null;
    auth.cookieMode = true;
    const store = useUserStore();
    await expect(store.restoreSession()).resolves.toBe(false);
    expect(store.ready).toBe(false);
    expect(store.sessionChecked).toBe(false);
    expect(store.sessionRestoreError).toBeTruthy();
    expect(auth.clearAuthSession).not.toHaveBeenCalled();
  });

  it("handles an initialization exception without abandoning the local session", async () => {
    auth.ensureTokenRefresh.mockRejectedValue(new Error("chunk unavailable"));
    const store = useUserStore();
    await expect(store.restoreSession()).resolves.toBe(false);
    expect(store.sessionRestoreError).toBeTruthy();
    expect(auth.clearAuthSession).not.toHaveBeenCalled();
  });

  it("preserves credentials and the specific error when restoration requires a configuration fix", async () => {
    auth.ensureTokenRefresh.mockRejectedValue(new SessionRestoreConfigurationError("认证来源配置不匹配"));
    const store = useUserStore();
    await expect(store.restoreSession()).resolves.toBe(false);
    expect(store.sessionRestoreError).toBe("认证来源配置不匹配");
    expect(store.sessionRestoreRetryable).toBe(false);
    expect(auth.clearAuthSession).not.toHaveBeenCalled();
  });
});

import type { UserInfo } from "@/types/esport";
import { setPmFokPreflightMode } from "@changmen/venue-adapter/polymarket";
import type { FollowConfig } from "@/types/order";
import type { ExtensionPrefs } from "@/types/extensionPrefs";
import type { MessageConfig, ProxyRow } from "@/types/userExtras";
import type { UserConfig } from "@/types/userConfig";
import { createDefaultExtensionPrefs, normalizeExtensionPrefs, serializeExtensionPrefsForSave } from "@/types/extensionPrefs";
import { readPbWsShadowUiLocal, writePbWsShadowUiLocal } from "@/shared/pbWsShadowUiLocal";
import { readPbChangmenExtensionsLocal, writePbChangmenExtensionsLocal } from "@/shared/pbExtensionsLocal";
import { defineStore } from "pinia";
import { toRaw } from "vue";
import {
  clearAuthSession,
  browserAuthState,
  getRefreshToken,
  hasAuthSession,
  isCookieAuthMode,
  isWebAuthenticated,
} from "@/api/client";
import {
  login as apiLogin,
  logout as apiLogout,
  updateUserSetting as apiUpdateUserSetting,
  getClientData,
  getClientDataArray,
  getUserInfo,
  saveClientData,
  saveClientDataDetailed,
} from "@/api/esport";
import { ensureTokenRefresh, startTokenRefresh, stopTokenRefresh } from "@/lib/sessionRefresh";
import { SessionRestoreConfigurationError } from "@/lib/sessionRestoreError";
import { subscribeUserChannel, unsubscribeUserChannel } from "@/realtime/userChannel";
import { ensureBetTargetChannelSubscribed } from "@/realtime/betTargetChannel";
import { ensurePublishChannelSubscribed } from "@/realtime/publishChannel";
import { parseFormBool } from "@/shared/parseFormBool";
import { setAssignedMarketHubOrigin } from "@changmen/client-core/shared/hkRelayOrigin";
import {
  createDefaultUserConfig,
  mergeUserConfig,
} from "@/types/userConfig";

const USER_KEY = "app:userName";
const HIDDEN_NAME_KEY = "hiddenUserName";
const CONFIG_KEY = "USERCONFIG";

export interface ConfigSaveResult {
  ok: boolean;
  msg?: string;
}

/** 对齐 A8 Pinia `Pn`（`g=Pn()`）：用户 / 登录态 + `config`（A8 `g.config`） */
export const useUserStore = defineStore("user", {
  state: () => ({
    userName: localStorage.getItem(USER_KEY) || "",
    userId: 0,
    setting: {} as Record<string, unknown>,
    /** 对齐 A8 `g.config`（USERCONFIG） */
    config: createDefaultUserConfig(),
    configLoaded: false,
    configSaving: false,
    /** 平博 v4 用 A8 账号，来自 GetUserInfo 或 /api/a8/credit-plate-user */
    creditPlateUserName: "",
    /** restoreSession / 无 token 判定完成后为 true，避免已登录刷新闪登录框 */
    sessionChecked: !hasAuthSession(),
    /** 有本地会话但后端暂不可达时保留 token，并在恢复页展示重试入口。 */
    sessionRestoreError: "",
    sessionRestoreRetryable: true,
    ready: false,
    error: null as string | null,
    hiddenUserName: localStorage.getItem(HIDDEN_NAME_KEY) === "1",
    proxyList: [] as ProxyRow[],
    message: {} as MessageConfig,
    extensionPrefs: createDefaultExtensionPrefs(),
    /**
     * PB WS 影子价旁显。仅本机 localStorage，不进 Extensions / RDS。
     * 默认关。
     */
    pbWsShadowUi: readPbWsShadowUiLocal(),
    /**
     * PB changmen 扩展总开关。仅本机 localStorage。
     * 默认关 = A8（仅 live 写 fo）；开 = changmen（双循环 + 赛前写 fo 等）。
     */
    pbChangmenExtensions: readPbChangmenExtensionsLocal(),
    follow: null as FollowConfig | null,
    extrasLoaded: false,
    /** 递增以作废过期的 loadExtras，防止慢 GetData 冲掉已保存的扩展偏好 */
    extrasLoadGen: 0,
    isAdmin: false,
    role: "user" as "admin" | "leader" | "user",
    teamId: null as string | null,
  }),

  getters: {
    isLoggedIn: () => isWebAuthenticated(),
    isLeader: state => state.role === "leader",
    canAccessAdmin: state => state.isAdmin || state.role === "leader",

    displayName(state): string {
      return state.hiddenUserName ? String(state.userId || "—") : state.userName;
    },

    followEnabled(state): boolean {
      return Boolean(state.setting?.Follow);
    },
  },

  actions: {
    async login(password: string, userName?: string) {
      const name = userName ?? this.userName;
      this.error = null;
      const info = await apiLogin(name, password);
      this.userName = info.userName;
      this.userId = info.ID;
      localStorage.setItem(USER_KEY, info.userName);
      await this.fetchUserInfo();
      await startTokenRefresh();
      return info;
    },

    async fetchUserInfo() {
      if (!isWebAuthenticated()) {
        this.ready = false;
        if (hasAuthSession())
          throw new Error("登录会话暂未恢复，请稍后重试");
        return;
      }
      try {
        // 尽早按本机缓存开门控，勿等 Extensions GetData
        await this.syncPbCollectModeFromLocal();
        const info: UserInfo = await getUserInfo();
        this.userId = info.ID;
        this.userName = info.UserName;
        setAssignedMarketHubOrigin(info.MarketHubOrigin);
        this.setting = info.Setting ?? {};
        this.isAdmin = info.IsAdmin === true || info.IsAdmin === 1;
        this.role = info.Role || "user";
        this.teamId = info.TeamId || null;
        const cp = info.CreditPlateUserName?.trim();
        if (cp)
          this.creditPlateUserName = cp;
        await this.loadExtras();
        void subscribeUserChannel(this.userId).catch((err) => {
          console.warn("[pubsub] USER channel:", err);
        });
        void ensureBetTargetChannelSubscribed().catch((err) => {
          console.warn("[pubsub] BetTarget channel:", err);
        });
        void ensurePublishChannelSubscribed().catch((err) => {
          console.warn("[pubsub] Publish channel:", err);
        });
        this.ready = true;
        this.error = null;
      }
      catch (e) {
        setAssignedMarketHubOrigin("");
        this.error = e instanceof Error ? e.message : String(e);
        this.ready = false;
        throw e;
      }
    },

    async restoreSession() {
      this.sessionRestoreRetryable = true;
      if (!hasAuthSession() && typeof window !== "undefined" && typeof document !== "undefined") {
        // HttpOnly Cookie 可能仍有效而本机提示已清除；只读探测，不自动重新登录。
        const { probeCookieSession } = await import("@/lib/webSession");
        try { await probeCookieSession(false, true); }
        catch (err) {
          this.ready = false;
          this.sessionChecked = false;
          this.sessionRestoreRetryable = !(err instanceof SessionRestoreConfigurationError);
          this.sessionRestoreError = this.sessionRestoreRetryable
            ? "连接暂时不可用，请检查网络后重试"
            : (err as Error).message;
          this.error = err instanceof Error ? err.message : String(err);
          return false;
        }
      }
      if (!hasAuthSession()) {
        this.ready = false;
        this.sessionRestoreError = "";
        this.sessionChecked = true;
        browserAuthState.value = "anonymous";
        return false;
      }
      this.sessionChecked = false;
      this.sessionRestoreError = "";
      // 提前启动 JWT refresh，防止 token 在使用中到期
      try {
        const rft = getRefreshToken();
        if (rft || isCookieAuthMode())
          await ensureTokenRefresh();
        await this.fetchUserInfo();
        this.sessionRestoreError = "";
        return true;
      }
      catch (err) {
        this.ready = false;
        // client.ts 只会在服务端明确判定会话失效时清 token；网络/502 保留会话。
        if (hasAuthSession()) {
          this.sessionRestoreRetryable = !(err instanceof SessionRestoreConfigurationError);
          this.sessionRestoreError = this.sessionRestoreRetryable
            ? "连接暂时不可用，请检查网络后重试"
            : (err as Error).message;
          this.error = err instanceof Error ? err.message : String(err);
          return false;
        }
        clearAuthSession();
        this.sessionRestoreError = "";
        return false;
      }
      finally {
        this.sessionChecked = this.ready || !hasAuthSession();
      }
    },

    async logout() {
      unsubscribeUserChannel();
      await stopTokenRefresh();
      if (await apiLogout() === false) return false;
      this.userName = "";
      this.userId = 0;
      this.setting = {};
      this.creditPlateUserName = "";
      this.proxyList = [];
      this.message = {};
      this.extensionPrefs = createDefaultExtensionPrefs();
      setPmFokPreflightMode(this.extensionPrefs.pmFokPreflightMode);
      // 本机影子价偏好保留在 localStorage；登出只关运行时门控，下次登录再按本地值恢复
      try {
        const { setPbWsShadowUiAllowed, setPbChangmenExtensions } = await import("@changmen/venue-adapter/pb");
        setPbWsShadowUiAllowed(false);
        setPbChangmenExtensions(false);
      }
      catch {
        /* adapter 未加载时忽略 */
      }
      try {
        await this.syncPmArbPriceBufferFromPrefs();
        await this.syncPmFokDepthBufferFromPrefs();
        await this.syncPfArbPriceBufferFromPrefs();
      }
      catch {
        /* adapter 未加载时忽略 */
      }
      this.follow = null;
      this.extrasLoaded = false;
      this.config = createDefaultUserConfig();
      this.configLoaded = false;
      this.configSaving = false;
      this.isAdmin = false;
      this.role = "user";
      this.teamId = null;
      this.ready = false;
      setAssignedMarketHubOrigin("");
      localStorage.removeItem(USER_KEY);
      return true;
    },

    async loadExtras(force = false) {
      if (this.extrasLoaded && !force)
        return;
      // 世代号：打开弹窗的慢请求不得盖掉用户已改/已保存的扩展偏好
      const gen = ++this.extrasLoadGen;
      try {
        const proxies = await getClientDataArray<ProxyRow>("PROXY");
        if (gen !== this.extrasLoadGen)
          return;
        this.proxyList = proxies.filter(p => p?.proxyId != null);
      }
      catch {
        /* PROXY GetData 失败时保留已有列表 */
      }
      const msg = await getClientData<MessageConfig>("Message");
      const ext = await getClientData<ExtensionPrefs>("Extensions");
      const follow = await getClientData<FollowConfig & Record<string, unknown>>("Follow");
      if (gen !== this.extrasLoadGen)
        return;
      this.message = msg ?? {};
      this.extensionPrefs = normalizeExtensionPrefs(ext);
      setPmFokPreflightMode(this.extensionPrefs.pmFokPreflightMode);
      await this.syncPbCollectModeFromLocal();
      await this.syncPmArbPriceBufferFromPrefs();
      await this.syncPmFokDepthBufferFromPrefs();
      await this.syncPfArbPriceBufferFromPrefs();
      if (gen !== this.extrasLoadGen)
        return;
      this.follow = follow ?? null;
      this.extrasLoaded = true;
    },

    async saveFollowConfig(payload: FollowConfig) {
      await saveClientData("Follow", JSON.stringify(payload));
      this.follow = payload;
    },

    async saveProxyList() {
      await saveClientData("PROXY", JSON.stringify(this.proxyList));
    },

    async saveMessageConfig() {
      await saveClientData("Message", JSON.stringify(this.message));
    },

    /** 从本机恢复 PB 采集模式（A8 默认）并同步运行时门控 */
    async syncPbCollectModeFromLocal() {
      this.pbChangmenExtensions = readPbChangmenExtensionsLocal();
      this.pbWsShadowUi = readPbWsShadowUiLocal();
      const { setPbChangmenExtensions, setPbWsShadowUiAllowed } = await import("@changmen/venue-adapter/pb");
      setPbChangmenExtensions(this.pbChangmenExtensions === true);
      setPbWsShadowUiAllowed(this.pbChangmenExtensions === true && this.pbWsShadowUi === true);
    },

    /** Extensions → venue-adapter PM 套利缓冲配置（供后续 FOK/展示接线） */
    async syncPmArbPriceBufferFromPrefs() {
      const { setPmArbPriceBufferPrefs } = await import("@changmen/venue-adapter/polymarket");
      setPmArbPriceBufferPrefs(this.extensionPrefs.pmArbPriceBuffer);
    },

    /** Extensions → venue-adapter PM FOK 深度倍数（预检 1× 走出 P 后验 P 及更优） */
    async syncPmFokDepthBufferFromPrefs() {
      const { setPmFokDepthBufferPrefs } = await import("@changmen/venue-adapter/polymarket");
      setPmFokDepthBufferPrefs(this.extensionPrefs.pmFokDepthBuffer ?? {
        enabled: false,
        multiplier: 1.5,
      });
    },

    /** Extensions → venue-adapter PF 套利缓冲配置（展示/限价接线） */
    async syncPfArbPriceBufferFromPrefs() {
      const { setPfArbPriceBufferPrefs } = await import("@changmen/venue-adapter/predictfun");
      setPfArbPriceBufferPrefs(this.extensionPrefs.pfArbPriceBuffer);
    },

    /** 本机缓存立即生效，不写 RDS */
    async setPbWsShadowUi(on: boolean) {
      const next = on === true;
      this.pbWsShadowUi = next;
      writePbWsShadowUiLocal(next);
      const { setPbWsShadowUiAllowed } = await import("@changmen/venue-adapter/pb");
      setPbWsShadowUiAllowed(this.pbChangmenExtensions === true && next);
    },

    /** 本机立即生效：关=A8；开=changmen 扩展（双循环、赛前写 fo、RotNum、WS 影子） */
    async setPbChangmenExtensions(on: boolean) {
      const next = on === true;
      const prev = this.pbChangmenExtensions === true;
      this.pbChangmenExtensions = next;
      writePbChangmenExtensionsLocal(next);
      // 子开关未显式写过时跟总开关：开扩展即开影子
      this.pbWsShadowUi = readPbWsShadowUiLocal();
      const { setPbChangmenExtensions, setPbWsShadowUiAllowed } = await import("@changmen/venue-adapter/pb");
      setPbChangmenExtensions(next);
      setPbWsShadowUiAllowed(next && this.pbWsShadowUi === true);
      if (prev !== next) {
        const { restartCollector } = await import("@/runtime/collectors");
        restartCollector("PB");
      }
    },

    async saveExtensionPrefs() {
      // 作废进行中的 loadExtras，避免「保存成功后被打开弹窗时的旧 GetData 冲回关」
      this.extrasLoadGen += 1;
      // 失败减仓暂锁死：保存前再归一化，避免内存/旧 KV 把 enabled:true 写回
      this.extensionPrefs = normalizeExtensionPrefs(this.extensionPrefs);
      const savedPreflightMode = this.extensionPrefs.pmFokPreflightMode;
      const savedForUserId = this.userId;
      const saveGeneration = this.extrasLoadGen;
      await this.syncPmArbPriceBufferFromPrefs();
      await this.syncPmFokDepthBufferFromPrefs();
      await this.syncPfArbPriceBufferFromPrefs();
      const result = await saveClientDataDetailed(
        "Extensions",
        serializeExtensionPrefsForSave({ ...this.extensionPrefs, pmFokPreflightMode: savedPreflightMode }),
      );
      if (!result.ok)
        throw new Error(result.msg || "保存扩展配置失败");
      // [changmen 扩展] 保存成功才应用；异步保存期间的编辑不能改变本次持久化的选择。
      if (this.userId === savedForUserId && this.extrasLoadGen === saveGeneration)
        setPmFokPreflightMode(savedPreflightMode);
    },

    async deleteProxy(proxyId: number) {
      const { useAccountStore } = await import("@/stores/accountStore");
      const accounts = useAccountStore().accounts;
      const inUse = accounts.some(a => a.proxyId === proxyId);
      if (inUse) {
        throw new Error("当前代理正在被账号使用");
      }
      this.proxyList = this.proxyList.filter(p => p.proxyId !== proxyId);
      await this.saveProxyList();
    },

    toggleHiddenUserName() {
      this.hiddenUserName = !this.hiddenUserName;
      localStorage.setItem(HIDDEN_NAME_KEY, this.hiddenUserName ? "1" : "0");
    },

    async patchSetting(patch: Record<string, unknown>) {
      const next = await apiUpdateUserSetting(patch);
      this.setting = { ...this.setting, ...next };
      return next;
    },

    betTargetEnabled(): boolean {
      return parseFormBool(this.setting?.BetTarget);
    },

    async loadConfig() {
      const raw = await getClientData<Partial<UserConfig>>(CONFIG_KEY);
      this.config = mergeUserConfig(raw ?? undefined);
      this.configLoaded = true;
    },

    buildConfigSavePayload(): UserConfig {
      const raw = toRaw(this.config) as UserConfig & {
        arbDetectEngine?: unknown;
        arbExecuteEngine?: unknown;
      };
      const {
        arbDetectEngine: _legacyDetectEngine,
        arbExecuteEngine: _legacyExecuteEngine,
        ...configBody
      } = raw;
      return {
        ...configBody,
        betMoney: Number(this.config.betMoney) || 100,
        betMoneyMode: this.config.betMoneyMode === "total" ? "total" : "buy",
        minMoney: Number(this.config.minMoney) || 0,
        maxMoney: Number(this.config.maxMoney) || 0,
        profit: Number(this.config.profit) || 1.03,
        maxProfit: Number(this.config.maxProfit) || 1.2,
        minOdds: Number(this.config.minOdds) || 1.3,
        maxOdds: Number(this.config.maxOdds) || 10,
        makeProfit: Number(this.config.makeProfit) || 1.01,
        makeUp_odds: Number(this.config.makeUp_odds) || 0,
        makeUp_defaultOdds: Number(this.config.makeUp_defaultOdds) || 0,
        anyOddsProfit: Number(this.config.anyOddsProfit) || 0.95,
        checkTimeout: Number(this.config.checkTimeout) || 3000,
      };
    },

    async saveConfig(): Promise<ConfigSaveResult> {
      this.configSaving = true;
      try {
        const payload = this.buildConfigSavePayload();
        let content: string;
        try {
          content = JSON.stringify(payload);
        }
        catch {
          return { ok: false, msg: "配置无法序列化，请刷新页面后重试" };
        }
        const result = await saveClientDataDetailed(CONFIG_KEY, content);
        if (result.ok) {
          this.config = payload;
        }
        return result;
      }
      finally {
        this.configSaving = false;
      }
    },
  },
});

import type { PlatformId } from "@changmen/api-contract";
import type { UserConfig } from "@changmen/client-core/types/userConfig";
import { ALL_PLATFORMS } from "@changmen/venue-adapter/registry";
import { normalizeWaitTime } from "@/shared/betTiming";

export type { UserConfig, BetSorting } from "@changmen/client-core/types/userConfig";
export { ALL_PLATFORMS };

export function createDefaultUserConfig(): UserConfig {
  return {
    betting: false,
    bettingAutoOpen: false,
    bettingAutoOpenTime: 0,
    betMoney: 100,
    betMoneyMode: "buy",
    minMoney: 0,
    maxMoney: 0,
    tenNumber: false,
    makeUp: false,
    makeUp_odds: 0,
    makeUp_defaultOdds: 0,
    makeProfit: 1.01,
    noSameProvider: false,
    noSameBet: false,
    allowSameBet: ["PB"],
    anyOdds: false,
    anyOddsProfit: 0.95,
    betSorting: "Custom",
    winRateValue: 0.15,
    providerSortValue: [...ALL_PLATFORMS],
    providerFixed: [],
    profit: 1.03,
    maxProfit: 1.2,
    minOdds: 1.3,
    maxOdds: 10,
    betCount: 0,
    betInterval: 30,
    checkTimeout: 3000,
    betChecked: false,
    singleBet: false,
    waitTime: {},
    valueBetMoney: 100,
    valueBetConfirm: true,
  };
}

/** [A8 可证实] D8 加载：保留用户顺序，将 ALL_PLATFORMS 中缺失的平台 append 到末尾 */
export function mergeProviderSortValue(values: PlatformId[]): PlatformId[] {
  const merged = [...values];
  for (const platform of ALL_PLATFORMS) {
    if (!merged.includes(platform))
      merged.push(platform);
  }
  return merged;
}

export function mergeUserConfig(raw: Partial<UserConfig> | null | undefined): UserConfig {
  const base = createDefaultUserConfig();
  if (!raw || typeof raw !== "object")
    return base;
  const {
    arbDetectEngine: _legacyDetectEngine,
    arbExecuteEngine: _legacyExecuteEngine,
    ...rest
  } = raw as Partial<UserConfig> & {
    arbDetectEngine?: unknown;
    arbExecuteEngine?: unknown;
  };
  return {
    ...base,
    ...rest,
    betMoneyMode: raw.betMoneyMode === "total" ? "total" : "buy",
    providerSortValue: mergeProviderSortValue(
      Array.isArray(raw.providerSortValue)
        ? (raw.providerSortValue as PlatformId[])
        : base.providerSortValue,
    ),
    providerFixed: Array.isArray(raw.providerFixed)
      ? (raw.providerFixed as PlatformId[])
      : base.providerFixed,
    allowSameBet: Array.isArray(raw.allowSameBet)
      ? (raw.allowSameBet as PlatformId[])
      : base.allowSameBet,
    waitTime: normalizeWaitTime(
      raw.waitTime && typeof raw.waitTime === "object"
        ? (raw.waitTime as Record<string, unknown>)
        : undefined,
    ),
    valueBetMoney: normalizeValueBetMoney(raw.valueBetMoney, base.valueBetMoney),
    valueBetConfirm: raw.valueBetConfirm !== false,
  };
}

/** 正 EV 建议注码：非法/缺省回退默认；允许 0（不展示金额） */
export function normalizeValueBetMoney(raw: unknown, fallback = 100): number {
  const n = Number(raw);
  if (!Number.isFinite(n) || n < 0)
    return fallback;
  return Math.round(n);
}

