import { afterEach, expect, test, vi } from "vitest";
import { PmOrderBookService, BookStore, reduceBookFrame } from "../src/index";
import type { BookHostPorts } from "../src/service";
import type { WorkerPort, ServiceMessage } from "../src/serviceProtocol";
import type { MarketStreamEvent } from "../src/marketStreamProtocol";
import { BookStore as CompatibilityStore } from "../../../../packages/venue-adapter/polymarket/realtime/orderBook/bookStore";
import { reduceBookFrame as compatibilityReducer } from "../../../../packages/venue-adapter/polymarket/realtime/orderBook/bookReducer";

afterEach(() => { vi.useRealTimers(); vi.unstubAllGlobals(); });
function fixture(allowed = true) {
  vi.useFakeTimers();
  const messages: ServiceMessage[] = [];
  const worker: WorkerPort = { onmessage: null, onerror: null, onmessageerror: null,
    postMessage: value => { messages.push(value); }, terminate: vi.fn() };
  let forward!: (event: MarketStreamEvent) => void;
  const release = vi.fn(), createWorker = vi.fn(() => worker);
  const source = { subscribedAssets: () => ["1"], observe: vi.fn((next: typeof forward) => {
    forward = next; next({ type: "state", state: { epoch: 1, open: true, source: "official" } }); return release;
  }) };
  const ports: BookHostPorts = { source, createWorker, allowed: () => allowed, monotonicNow: () => performance.now() };
  return { ports, worker, messages, release, createWorker, source, push: (event: MarketStreamEvent) => forward(event),
    revoke: () => { allowed = false; } };
}
test("old paths export the canonical reducer and store identities", () => {
  expect(CompatibilityStore).toBe(BookStore);
  expect(compatibilityReducer).toBe(reduceBookFrame);
});
test("an unauthorized host cannot create a Worker or observe the source", () => {
  const f = fixture(false), owner = new PmOrderBookService(f.ports);
  expect(f.createWorker).not.toHaveBeenCalled(); expect(f.source.observe).not.toHaveBeenCalled();
  expect(owner.report()).toMatchObject({ worker: false, assets: 0 }); owner.stop();
});
test("the injected owner creates one Worker, never gains subscription authority, and releases once", () => {
  const f = fixture(), owner = new PmOrderBookService(f.ports);
  try {
    const first = owner.acquire(), second = owner.acquire();
    expect(first.setInterests(["1", "2"])).toEqual([{ asset: "1", status: "admitted" }, { asset: "2", status: "not_subscribed" }]);
    expect(f.createWorker).toHaveBeenCalledOnce(); expect(f.source.observe).toHaveBeenCalledOnce();
    first.release(); second.release(); expect(owner.report().worker).toBe(true);
    f.revoke(); owner.reconcile(); owner.reconcile(); owner.stop();
    expect(f.release).toHaveBeenCalledOnce(); expect(f.worker.terminate).toHaveBeenCalledOnce();
    expect(owner.report()).toMatchObject({ worker: false, consumers: 0 });
  } finally { owner.stop(); }
});
test("a revoke synchronously cancels an existing complete read", async () => {
  const f = fixture(), owner = new PmOrderBookService(f.ports);
  const lease = owner.acquire(); lease.setInterests(["1"]);
  const reading = lease.readFullBook("1"); f.revoke(); owner.reconcile();
  expect(await reading).toMatchObject({ asset: "1", status: "service_stopped" });
  expect(owner.report().pendingReads).toBe(0); owner.stop();
});

/**
 * 从 packages/venue-adapter/registry/manifest.json 生成平台角标 CSS。
 * predev / prebuild 门禁：manifest.icon 必须对应 public/assets/venue/ 下真实文件。
 *
 * 用法：node scripts/gen-platform-icons-css.mjs
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import manifest from "../../../packages/venue-adapter/registry/manifest.json" with { type: "json" };

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const webRoot = path.join(__dirname, "..");
const venuePublicDir = path.join(webRoot, "public/assets/venue");
const outFile = path.join(webRoot, "src/styles/platform-icons.generated.css");

const VENUE_ICON_PUBLIC_DIR = "/assets/venue";

/** @param {string} id */
function cssEscapePlatformId(id) {
  return id.replace(/[^\w-]/g, "\\$&");
}

const lines = [
  "/**",
  " * AUTO-GENERATED — 勿手改。",
  " * 源：packages/venue-adapter/registry/manifest.json（icon 字段）",
  " * 命令：node client/web/scripts/gen-platform-icons-css.mjs",
  " */",
  "",
];

let failed = 0;
for (const entry of manifest) {
  if (!entry.icon)
    continue;

  const filePath = path.join(venuePublicDir, entry.icon);
  if (!fs.existsSync(filePath)) {
    console.error(`[gen-platform-icons-css] missing file for ${entry.id}: ${entry.icon}`);
    failed += 1;
    continue;
  }

  const selector = cssEscapePlatformId(entry.id);
  const url = `${VENUE_ICON_PUBLIC_DIR}/${entry.icon}`;
  lines.push(
    `.cm-platform-icon.${selector},`,
    `.provider-icon.${selector} {`,
    `  background-image:url(${url});`,
    "}",
    "",
  );
}

if (failed) {
  console.error(`[gen-platform-icons-css] FAILED (${failed} missing icon file(s))`);
  process.exit(1);
}

const next = `${lines.join("\n")}\n`;
const prev = fs.existsSync(outFile) ? fs.readFileSync(outFile, "utf8") : "";
if (next !== prev) {
  fs.writeFileSync(outFile, next);
  console.log(`[gen-platform-icons-css] wrote ${path.relative(webRoot, outFile)} (${manifest.filter((e) => e.icon).length} platforms)`);
}
else {
  console.log(`[gen-platform-icons-css] up to date (${manifest.filter((e) => e.icon).length} platforms)`);
}

#!/usr/bin/env node
/**
 * 从 monorepo 内 @changmen/venue-adapter/* 引用生成 package.json exports 白名单。
 * 扫描：client/web/src、packages/venue-adapter（含 vi.mock / dynamic import）。
 *
 * 用法：
 *   node packages/venue-adapter/scripts/sync-package-exports.mjs          # 写回 package.json
 *   node packages/venue-adapter/scripts/sync-package-exports.mjs --check  # 仅校验，有漂移 exit 1
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "../../..");
const ADAPTER_ROOT = path.resolve(__dirname, "../../../packages/venue-adapter");
const PKG_JSON = path.join(ADAPTER_ROOT, "package.json");
const PKG = "@changmen/venue-adapter";
const CHECK = process.argv.includes("--check");

const SCAN_ROOTS = [
  path.join(REPO_ROOT, "client", "web", "src"),
  ADAPTER_ROOT,
];

const IMPORT_RES = [
  new RegExp(`(?:from|import)\\s*(?:\\(?\\s*)?["']${PKG}/([^"']+)["']`, "g"),
  new RegExp(`import\\s*\\(\\s*["']${PKG}/([^"']+)["']\\s*\\)`, "g"),
  new RegExp(`vi\\.mock\\s*\\(\\s*["']${PKG}/([^"']+)["']`, "g"),
];

/** 固定公共入口；旧浏览器入口不能因应用改用新包而被扫描器删除。 */
const FIXED_EXPORTS = {
  ".": "./registry/index.ts",
  "./loader/adapter_paths.js": "./loader/adapter_paths.mjs",
  "./loader/adapter_paths.mjs": "./loader/adapter_paths.mjs",
  "./polymarket/orderBook": "./polymarket/orderBook.ts",
  "./polymarket/wsBookShadow": "./polymarket/wsBookShadow.ts",
};

function walk(dir, out = []) {
  for (const name of fs.readdirSync(dir)) {
    if (name === "node_modules" || name === "dist")
      continue;
    const p = path.join(dir, name);
    const st = fs.statSync(p);
    if (st.isDirectory())
      walk(p, out);
    else if (/\.(ts|tsx|vue|mjs|js)$/.test(name))
      out.push(p);
  }
  return out;
}

function resolveExportTarget(sub) {
  const rel = sub.replace(/\\/g, "/");
  const candidates = [
    `${rel}.ts`,
    `${rel}.tsx`,
    `${rel}/index.ts`,
    `${rel}.mjs`,
    `${rel}/index.mjs`,
  ];
  for (const c of candidates) {
    const abs = path.join(ADAPTER_ROOT, c);
    if (fs.existsSync(abs))
      return `./${c}`;
  }
  return null;
}

function collectSubpaths() {
  const subs = new Set();
  for (const root of SCAN_ROOTS) {
    if (!fs.existsSync(root))
      continue;
    for (const file of walk(root)) {
      const text = fs.readFileSync(file, "utf8");
      for (const re of IMPORT_RES) {
        re.lastIndex = 0;
        let m;
        while ((m = re.exec(text)) !== null)
          subs.add(m[1]);
      }
    }
  }
  return subs;
}

function buildExports() {
  const exports = { ...FIXED_EXPORTS };
  const missing = [];
  for (const sub of [...collectSubpaths()].sort()) {
    const target = resolveExportTarget(sub);
    if (!target) {
      missing.push(sub);
      continue;
    }
    exports[`./${sub}`] = target;
  }
  if (missing.length) {
    console.error("sync-package-exports: 无法解析以下子路径到磁盘文件：");
    for (const m of missing)
      console.error(`  ./${m}`);
    process.exit(1);
  }
  return exports;
}

function sortedExportsObject(exports) {
  const out = {};
  for (const key of Object.keys(exports).sort())
    out[key] = exports[key];
  return out;
}

function readCurrentExports() {
  const pkg = JSON.parse(fs.readFileSync(PKG_JSON, "utf8"));
  return pkg.exports ?? {};
}

function exportsEqual(a, b) {
  const ka = Object.keys(a).sort();
  const kb = Object.keys(b).sort();
  if (ka.length !== kb.length)
    return false;
  return ka.every((k, i) => k === kb[i] && a[k] === b[k]);
}

const nextExports = sortedExportsObject(buildExports());

if (CHECK) {
  const cur = readCurrentExports();
  if (!exportsEqual(cur, nextExports)) {
    console.error("sync-package-exports --check: package.json exports 与扫描结果不一致");
    console.error("运行: npm run sync:exports --workspace=@changmen/venue-adapter");
    process.exit(1);
  }
  console.log(`sync-package-exports --check: OK (${Object.keys(nextExports).length} entries)`);
  process.exit(0);
}

const pkg = JSON.parse(fs.readFileSync(PKG_JSON, "utf8"));
pkg.exports = nextExports;
fs.writeFileSync(PKG_JSON, `${JSON.stringify(pkg, null, 2)}\n`);
console.log(`sync-package-exports: wrote ${Object.keys(nextExports).length} exports to package.json`);

