    if (name === "node_modules" || name === "dist" || name === "scripts")
      continue;
    const p = path.join(dir, name);
    const st = fs.statSync(p);
    if (st.isDirectory())
      walk(p, out);
    else if (/\.(ts|tsx|vue)$/.test(name))
      out.push(p);
  }
  return out;
