  ["orderModes/gtc/manual.ts", new Set(["polymarket/gtc", "polymarket/orders"])],
  ["orderModes/gtc/gateway.ts", new Set(["polymarket/gtc"])],
  ["orderModes/gtc/orderCardView.ts", new Set(["polymarket/gtc"])],
  ["orderModes/gtc/pollingPolicy.ts", new Set(["polymarket/gtc"])],
  ["orderModes/gtc/sellFinancials.ts", new Set(["polymarket/gtc"])],
  ["orderModes/gtc/financialOrder.ts", new Set(["polymarket/orders"])],
  // [changmen 扩展] 订单盘口名复用 PM 原生元数据缓存，不从合场 Map 推断。
  ["orderModes/gtc/orderDisplayProjection.ts", new Set(["polymarket/orders"])],
  ["runtime/venueAdapters.ts", new Set(["registry/adapters"])],
  // vitest setup → oddsStore：勿经 polymarket/predictfun barrel 预加载 CLOB transport，否则场馆单测 vi.mock 失效
  ["stores/oddsStore.ts", new Set([
    "polymarket/pmArbPriceBufferMode",
    "predictfun/pfArbPriceBufferMode",
  ])],
]);

const IMPORT_RE = new RegExp(
  `(?:from|import)\\s*(?:\\(?\\s*)?["']${PKG}/([^"']+)["']`,
  "g",
);
const DYNAMIC_RE = new RegExp(
  `import\\s*\\(\\s*["']${PKG}/([^"']+)["']\\s*\\)`,
  "g",
);
const MOCK_RE = new RegExp(
  `vi\\.mock\\s*\\(\\s*["']${PKG}/([^"']+)["']`,
  "g",
);

function walk(dir, out = []) {
  for (const name of fs.readdirSync(dir)) {
    const p = path.join(dir, name);
    const st = fs.statSync(p);
    if (st.isDirectory())
      walk(p, out);
    else if (/\.(ts|vue|tsx)$/.test(name))
      out.push(p);
  }
  return out;
}

const subs = new Set();
const deepViolations = [];

for (const file of walk(WEB_SRC)) {
  const text = fs.readFileSync(file, "utf8");
  const isTest = /\.(test|spec)\.(ts|tsx)$/.test(file);
  for (const re of [IMPORT_RE, DYNAMIC_RE, MOCK_RE]) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(text)) !== null) {
      const sub = m[1];
      subs.add(sub);
      const top = sub.split("/")[0];
      const isDeep = sub.includes("/");
      if (isDeep) {
        if (MOCK_ONLY_DEEP.has(sub) && isTest)
          continue;
        const rel = path.relative(WEB_SRC, file).replace(/\\/g, "/");
        const allowed = RUNTIME_DEEP.get(rel);
        if (allowed?.has(sub))
          continue;
        if (!MOCK_ONLY_DEEP.has(sub) || !isTest)
          deepViolations.push({ file, sub });
      }
      else if (!BARREL_TOPS.has(top)) {
        deepViolations.push({ file, sub });
      }
    }
  }
}

const sorted = [...subs].sort();
const roots = new Set(sorted.map((s) => s.split("/")[0]));
console.log(`${PKG} subpaths from client/web/src (${sorted.length}, ${roots.size} top-level):`);
for (const sub of sorted) {
  console.log(`  ./${sub}`);
}

if (CHECK) {
  if (deepViolations.length) {
    console.error("\nlist-web-venue-imports --check: 非 barrel / 非法深路径 import：");
    for (const v of deepViolations)
      console.error(`  ${path.relative(process.cwd(), v.file)} → ./${v.sub}`);
    process.exit(1);
  }
  console.log("\nlist-web-venue-imports --check: OK");
}

#!/usr/bin/env node
/**
 * 从 monorepo 内 @changmen/venue-adapter/* 引用生成 package.json exports 白名单。
 * 扫描：client/web/src、packages/venue-adapter（含 vi.mock / dynamic import）。
 *
 * 用法：
 *   node packages/venue-adapter/scripts/sync-package-exports.mjs          # 写回 package.json
 *   node packages/venue-adapter/scripts/sync-package-exports.mjs --check  # 仅校验，有漂移 exit 1
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "../../..");
const ADAPTER_ROOT = path.resolve(__dirname, "../../../packages/venue-adapter");
const PKG_JSON = path.join(ADAPTER_ROOT, "package.json");
const PKG = "@changmen/venue-adapter";
const CHECK = process.argv.includes("--check");

const SCAN_ROOTS = [
  path.join(REPO_ROOT, "client", "web", "src"),
  ADAPTER_ROOT,
];

const IMPORT_RES = [
  new RegExp(`(?:from|import)\\s*(?:\\(?\\s*)?["']${PKG}/([^"']+)["']`, "g"),
  new RegExp(`import\\s*\\(\\s*["']${PKG}/([^"']+)["']\\s*\\)`, "g"),
  new RegExp(`vi\\.mock\\s*\\(\\s*["']${PKG}/([^"']+)["']`, "g"),
];

/** Browser entries are retired; this package exposes only its retained Node loader aliases. */
const FIXED_EXPORTS = {
  "./loader/adapter_paths.js": "./loader/adapter_paths.mjs",
  "./loader/adapter_paths.mjs": "./loader/adapter_paths.mjs",
};

function walk(dir, out = []) {
  for (const name of fs.readdirSync(dir)) {
    if (name === "node_modules" || name === "dist")
      continue;
    const p = path.join(dir, name);
    const st = fs.statSync(p);
    if (st.isDirectory())
      walk(p, out);
    else if (/\.(ts|tsx|vue|mjs|js)$/.test(name))
      out.push(p);
  }
  return out;
}

function resolveExportTarget(sub) {
  const rel = sub.replace(/\\/g, "/");
  const candidates = [
    `${rel}.ts`,
    `${rel}.tsx`,
    `${rel}/index.ts`,
    `${rel}.mjs`,
    `${rel}/index.mjs`,
  ];
  for (const c of candidates) {
    const abs = path.join(ADAPTER_ROOT, c);
    if (fs.existsSync(abs))
      return `./${c}`;
  }
  return null;
}

function collectSubpaths() {
  const subs = new Set();
  for (const root of SCAN_ROOTS) {
    if (!fs.existsSync(root))
      continue;
    for (const file of walk(root)) {
      const text = fs.readFileSync(file, "utf8");
      for (const re of IMPORT_RES) {
        re.lastIndex = 0;
        let m;
        while ((m = re.exec(text)) !== null)
          subs.add(m[1]);
      }
    }
  }
  return subs;
}

function buildExports() {
  const exports = { ...FIXED_EXPORTS };
  const missing = [];
  for (const sub of [...collectSubpaths()].sort()) {
    const target = resolveExportTarget(sub);
    if (!target) {
      missing.push(sub);
      continue;
    }
    exports[`./${sub}`] = target;
  }
  if (missing.length) {
    console.error("sync-package-exports: 无法解析以下子路径到磁盘文件：");
    for (const m of missing)
      console.error(`  ./${m}`);
    process.exit(1);
  }
  return exports;
}

function sortedExportsObject(exports) {
  const out = {};
  for (const key of Object.keys(exports).sort())
    out[key] = exports[key];
  return out;
}

function readCurrentExports() {
  const pkg = JSON.parse(fs.readFileSync(PKG_JSON, "utf8"));
  return pkg.exports ?? {};
}

function exportsEqual(a, b) {
  const ka = Object.keys(a).sort();
  const kb = Object.keys(b).sort();
  if (ka.length !== kb.length)
    return false;
  return ka.every((k, i) => k === kb[i] && a[k] === b[k]);
}

const nextExports = sortedExportsObject(buildExports());

if (CHECK) {
  const cur = readCurrentExports();
  if (!exportsEqual(cur, nextExports)) {
    console.error("sync-package-exports --check: package.json exports 与扫描结果不一致");
    console.error("运行: npm run sync:exports --workspace=@changmen/venue-adapter");
    process.exit(1);
  }
  console.log(`sync-package-exports --check: OK (${Object.keys(nextExports).length} entries)`);
  process.exit(0);
}

const pkg = JSON.parse(fs.readFileSync(PKG_JSON, "utf8"));
pkg.exports = nextExports;
fs.writeFileSync(PKG_JSON, `${JSON.stringify(pkg, null, 2)}\n`);
console.log(`sync-package-exports: wrote ${Object.keys(nextExports).length} exports to package.json`);

// [changmen 扩展] Exercise real commands against an isolated miniature repository.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { expect, it } from "vitest";

const repo = fileURLToPath(new URL("../../../", import.meta.url));
function fixture(run) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "changmen-venue-tools-"));
  const write = (name, text) => { const file = path.join(root, name); fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, text); };
  for (const name of ["list-web-venue-imports", "relativize-internal-imports", "sync-package-exports"]) {
    for (const prefix of ["packages/venue-adapter/scripts", "client/devtools/venue-adapter"])
      write(`${prefix}/${name}.mjs`, fs.readFileSync(path.join(repo, prefix, `${name}.mjs`), "utf8"));
  }
  write("client/web/src/main.ts", 'import { adapter } from "@changmen/venue-adapter/polymarket";');
  write("packages/venue-adapter/polymarket/index.ts", "export const adapter = 1;");
  write("packages/venue-adapter/package.json", JSON.stringify({ exports: {
    ".": "./registry/index.ts", "./loader/adapter_paths.js": "./loader/adapter_paths.mjs",
    "./loader/adapter_paths.mjs": "./loader/adapter_paths.mjs", "./polymarket": "./polymarket/index.ts",
    "./polymarket/orderBook": "./polymarket/orderBook.ts", "./polymarket/wsBookShadow": "./polymarket/wsBookShadow.ts",
  } }));
  const command = (name, args = ["--check"], canonical = false) => spawnSync(process.execPath,
    [path.join(root, canonical ? "client/devtools/venue-adapter" : "packages/venue-adapter/scripts", `${name}.mjs`), ...args],
    { cwd: os.tmpdir(), encoding: "utf8", windowsHide: true });
  try { run({ root, write, command }); }
  finally { if (path.dirname(root) === path.resolve(os.tmpdir()) && path.basename(root).startsWith("changmen-venue-tools-")) fs.rmSync(root, { recursive: true, force: true }); }
}
it("keeps old and canonical checks equivalent independently of cwd", () => fixture(({ command }) => {
  for (const name of ["list-web-venue-imports", "relativize-internal-imports", "sync-package-exports"]) {
    const old = command(name), next = command(name, ["--check"], true);
    expect(old.status, old.stderr).toBe(0); expect(next.status, next.stderr).toBe(0);
    expect(next.stdout).toBe(old.stdout); expect(next.stderr).toBe(old.stderr);
  }
}));
it("still rejects illegal web deep imports and export drift", () => fixture(({ write, command }) => {
  write("client/web/src/main.ts", 'import { x } from "@changmen/venue-adapter/polymarket/private";');
  expect(command("list-web-venue-imports").status).toBe(1);
  write("client/web/src/main.ts", 'import { x } from "@changmen/venue-adapter/polymarket";');
  write("packages/venue-adapter/package.json", '{"exports":{}}');
  expect(command("sync-package-exports").status).toBe(1);
  expect(command("sync-package-exports", []).status).toBe(0);
  expect(command("sync-package-exports").status).toBe(0);
}));
it("rewrites only adapter source using the original adapter root", () => fixture(({ root, write, command }) => {
  write("packages/venue-adapter/polymarket/source.ts", 'import { adapter } from "@changmen/venue-adapter/polymarket";');
  expect(command("relativize-internal-imports").status).toBe(1);
  expect(command("relativize-internal-imports", []).status).toBe(0);
  expect(fs.readFileSync(path.join(root, "packages/venue-adapter/polymarket/source.ts"), "utf8")).toContain('from "./index"');
  expect(fs.readFileSync(path.join(root, "client/web/src/main.ts"), "utf8")).toContain("@changmen/venue-adapter/polymarket");
  expect(command("relativize-internal-imports").status).toBe(0);
}));
it("retains both browser compatibility exports after the last application import is removed", () => fixture(({ root, write, command }) => {
  write("client/web/src/main.ts", "export {};\n");
  expect(command("sync-package-exports", []).status).toBe(0);
  const exports = JSON.parse(fs.readFileSync(path.join(root, "packages/venue-adapter/package.json"), "utf8")).exports;
  expect(exports["./polymarket/orderBook"]).toBe("./polymarket/orderBook.ts");
  expect(exports["./polymarket/wsBookShadow"]).toBe("./polymarket/wsBookShadow.ts");
}));
